-- Practice 283: Part 2 (Questions 96 to 190)
-- Table: public.question_explanations

INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-96', 'practice_283', 'Tuyên bố nào thể hiện hiệu quả chi phí của Đám mây AWS? (Chọn HAI.)', 'Domain 1: Cloud Concepts', 'Quản lý chi phí & Thanh toán AWS', 'Các tuyên bố thể hiện hiệu quả chi phí của Đám mây AWS là: Người dùng có thể đổi chi phí cố định lấy chi phí biến đổi. Bằng cách sử dụng Đám mây AWS, người dùng chỉ có thể trả tiền cho những tài nguyên họ sử dụng, thay vì đầu tư vào chi phí cố định và trả trước cho phần cứng và phần mềm. Điều này có thể làm giảm tổng chi phí sở hữu và tăng lợi tức đầu tư. Người dùng được hưởng lợi từ tính kinh tế theo quy mô. Bằng cách sử dụng Đám mây AWS, người dùng có thể tận dụng quy mô lớn và hiệu quả của AWS để tiếp cận mức giá thấp hơn và hiệu suất cao hơn. AWS chuyển khoản tiết kiệm chi phí cho người dùng thông qua việc giảm giá và đổi mới. Khung giá trị đám mây AWS', '[{"label": "A", "text_vi": "Người dùng có thể trao đổi chi phí cố định để lấy chi phí thay đổi.", "is_correct": true, "analysis_vi": "Đúng. Người dùng có thể trao đổi chi phí cố định để lấy chi phí thay đổi. là đáp án chính xác. Các tuyên bố thể hiện hiệu quả chi phí của Đám mây AWS là: Người dùng có thể đổi chi phí cố định lấy chi phí biến đổi."}, {"label": "B", "text_vi": "Người dùng có thể triển khai trên toàn thế giới trong vài phút.", "is_correct": false, "analysis_vi": "Sai. Người dùng có thể triển khai trên toàn thế giới trong vài phút. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "AWS mang lại tốc độ và tính linh hoạt cao hơn.", "is_correct": false, "analysis_vi": "Sai. AWS mang lại tốc độ và tính linh hoạt cao hơn.: Tính nhanh nhạy (Agility) giúp rút ngắn thời gian khởi tạo và thử nghiệm công nghệ từ hàng tuần xuống chỉ còn vài phút. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "AWS chịu trách nhiệm vá cơ sở hạ tầng.", "is_correct": false, "analysis_vi": "Sai. AWS chịu trách nhiệm vá cơ sở hạ tầng. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Người dùng được hưởng lợi từ quy mô kinh tế.", "is_correct": true, "analysis_vi": "Đúng. Người dùng được hưởng lợi từ quy mô kinh tế. là đáp án chính xác. Các tuyên bố thể hiện hiệu quả chi phí của Đám mây AWS là: Người dùng có thể đổi chi phí cố định lấy chi phí biến đổi."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '[]'::jsonb, NOW())
