INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-97', 'practice_283', 'Nhóm Hướng dẫn hỗ trợ doanh nghiệp AWS trợ giúp người dùng như thế nào?', 'Domain 4: Billing, Pricing and Support', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Nhóm Hướng dẫn hỗ trợ doanh nghiệp AWS là một nhóm gồm các chuyên gia tài khoản và thanh toán chuyên làm việc với khách hàng doanh nghiệp. Họ có thể giúp khách hàng giải đáp các thắc mắc về thanh toán, quản lý tài khoản, tối ưu hóa chi phí và các vấn đề phi kỹ thuật khác. Họ cũng có thể hỗ trợ khách hàng điều hướng và tối ưu hóa môi trường AWS của họ, chẳng hạn như thiết lập thanh toán tổng hợp, đăng ký tăng giới hạn dịch vụ hoặc yêu cầu hoàn lại tiền.', '[{"label": "A", "text_vi": "Hỗ trợ phát triển ứng dụng", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ phát triển ứng dụng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Cung cấp hướng dẫn kiến trúc", "is_correct": false, "analysis_vi": "Sai. Cung cấp hướng dẫn kiến trúc không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Trả lời các câu hỏi về thanh toán và tài khoản", "is_correct": true, "analysis_vi": "Đúng. Trả lời các câu hỏi về thanh toán và tài khoản là đáp án chính xác. Nhóm Hướng dẫn hỗ trợ doanh nghiệp AWS là một nhóm gồm các chuyên gia tài khoản và thanh toán chuyên làm việc với khách hàng doanh nghiệp."}, {"label": "D", "text_vi": "Giải đáp thắc mắc liên quan đến các trường hợp hỗ trợ kỹ thuật", "is_correct": false, "analysis_vi": "Sai. Giải đáp thắc mắc liên quan đến các trường hợp hỗ trợ kỹ thuật không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Ghi nhớ các ngưỡng SLA phản hồi: Business (<1h cho production down, 24/7 phone/chat/email), Enterprise (<15m cho mission-critical, có TAM)."]'::jsonb, '[{"term": "support plan", "points_to": "Developer / Business / Enterprise"}]'::jsonb, '[]'::jsonb, NOW())
