INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-98', 'practice_283', 'Người dùng đang di chuyển khối lượng công việc từ trung tâm dữ liệu cục bộ sang kiến trúc được phân phối giữa trung tâm dữ liệu cục bộ và Đám mây AWS. Đây là kiểu di cư nào?', 'Domain 3: Cloud Technology and Services', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'C đúng vì việc di chuyển khối lượng công việc từ trung tâm dữ liệu cục bộ sang kiến trúc được phân phối giữa trung tâm dữ liệu cục bộ và Đám mây AWS là một ví dụ về di chuyển tại chỗ sang kết hợp. Đám mây lai là môi trường điện toán đám mây sử dụng kết hợp các dịch vụ tại chỗ, đám mây riêng và đám mây công cộng với sự phối hợp giữa các nền tảng. Câu A không chính xác vì di chuyển tại chỗ sang đám mây gốc là quá trình di chuyển khối lượng công việc từ trung tâm dữ liệu cục bộ sang kiến ​​trúc được lưu trữ và quản lý hoàn toàn trên Đám mây AWS. B không chính xác vì di chuyển gốc sang đám mây là quá trình di chuyển khối lượng công việc từ kiến ​​trúc được phân phối giữa trung tâm dữ liệu cục bộ và Đám mây AWS sang kiến ​​trúc được lưu trữ và quản lý hoàn toàn trên Đám mây AWS. D không chính xác vì di chuyển gốc sang kết hợp đám mây là quá trình di chuyển khối lượng công việc từ kiến ​​trúc được lưu trữ và quản lý hoàn toàn trên Đám mây AWS sang kiến ​​trúc được phân phối giữa trung tâm dữ liệu cục bộ và Đám mây AWS.', '[{"label": "A", "text_vi": "Tại chỗ đến trên nền tảng đám mây", "is_correct": false, "analysis_vi": "Sai. Tại chỗ đến trên nền tảng đám mây không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Kết hợp với đám mây gốc", "is_correct": false, "analysis_vi": "Sai. Kết hợp với đám mây gốc không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Tại chỗ đến kết hợp", "is_correct": true, "analysis_vi": "Đúng. Tại chỗ đến kết hợp đáp ứng đầy đủ yêu cầu của đề bài. C đúng vì việc di chuyển khối lượng công việc từ trung tâm dữ liệu cục bộ sang kiến trúc được phân phối giữa trung tâm dữ liệu cục bộ và Đám mây AWS là một ví dụ về di chuyển tại chỗ sang kết hợp."}, {"label": "D", "text_vi": "Đám mây có nguồn gốc từ lai", "is_correct": false, "analysis_vi": "Sai. Đám mây có nguồn gốc từ lai không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
