INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-99', 'practice_283', 'Một công ty muốn quản lý quyền truy cập và quyền đối với các ứng dụng phần mềm bên thứ ba dưới dạng dịch vụ (SaaS). Công ty muốn sử dụng một cổng thông tin nơi người dùng cuối có thể truy cập vào các tài khoản AWS được chỉ định và ứng dụng Đám mây AWS. Công ty nên sử dụng dịch vụ AWS nào để đáp ứng những yêu cầu này?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Trung tâm nhận dạng AWS IAM (AWS Single Sign-On) là dịch vụ AWS mà công ty nên sử dụng để đáp ứng yêu cầu quản lý quyền truy cập và quyền đối với các ứng dụng SaaS của bên thứ ba. AWS Single Sign-On là dịch vụ dựa trên đám mây giúp dễ dàng quản lý tập trung quyền truy cập đăng nhập một lần (SSO) vào nhiều tài khoản AWS và ứng dụng kinh doanh. Bạn có thể sử dụng AWS Single Sign-On để cho phép người dùng đăng nhập vào cổng người dùng bằng thông tin xác thực hiện có của công ty và truy cập tất cả các tài khoản và ứng dụng được chỉ định của họ từ một nơi4.', '[{"label": "A", "text_vi": "Amazon Cognito", "is_correct": false, "analysis_vi": "Sai. Amazon Cognito không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Trung tâm nhận dạng AWS IAM (Đăng nhập một lần AWS)", "is_correct": true, "analysis_vi": "Đúng. Trung tâm nhận dạng AWS IAM (Đăng nhập một lần AWS) là đáp án chính xác. Trung tâm nhận dạng AWS IAM (AWS Single Sign-On) là dịch vụ AWS mà công ty nên sử dụng để đáp ứng yêu cầu quản lý quyền truy cập và quyền đối với các ứng dụng SaaS của bên thứ ba."}, {"label": "C", "text_vi": "Quản lý quyền truy cập và nhận dạng AWS (IAM)", "is_correct": false, "analysis_vi": "Sai. Quản lý quyền truy cập và nhận dạng AWS (IAM): AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Dịch vụ thư mục AWS dành cho Microsoft Active Directory", "is_correct": false, "analysis_vi": "Sai. Dịch vụ thư mục AWS dành cho Microsoft Active Directory không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS IAM"]'::jsonb, NOW())
