INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-100', 'practice_283', 'Một công ty muốn theo dõi chi phí dịch vụ của tài khoản AWS của mình. Công ty cũng muốn nhận được thông báo khi chi phí được dự báo sẽ đạt đến một mức cụ thể. Dịch vụ hoặc công cụ AWS nào cung cấp chức năng này?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'Ngân sách AWS cung cấp cho bạn khả năng đặt ngân sách tùy chỉnh để thông báo cho bạn khi chi phí hoặc mức sử dụng của bạn vượt quá (hoặc được dự báo sẽ vượt quá) số tiền dự kiến của bạn. Bạn cũng có thể sử dụng Ngân sách AWS để đặt mục tiêu sử dụng dự trữ hoặc phạm vi bảo hiểm và nhận thông báo khi mức sử dụng của bạn giảm xuống dưới ngưỡng bạn xác định2.', '[{"label": "A", "text_vi": "Ngân sách AWS", "is_correct": true, "analysis_vi": "Đúng. Ngân sách AWS là đáp án chính xác. Ngân sách AWS cung cấp cho bạn khả năng đặt ngân sách tùy chỉnh để thông báo cho bạn khi chi phí hoặc mức sử dụng của bạn vượt quá (hoặc được dự báo sẽ vượt quá) số tiền dự kiến của bạn."}, {"label": "B", "text_vi": "Trình AWS Cost Explorer AWS", "is_correct": false, "analysis_vi": "Sai. Trình AWS Cost Explorer AWS: AWS Cost Explorer cung cấp giao diện trực quan để phân tích, hiểu rõ chi phí lịch sử và dự báo chi tiêu AWS trong tương lai lên đến 12 tháng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Kế hoạch tiết kiệm", "is_correct": false, "analysis_vi": "Sai. Kế hoạch tiết kiệm không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Người thực hiện thanh toán AWS", "is_correct": false, "analysis_vi": "Sai. Người thực hiện thanh toán AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["AWS Cost Explorer", "AWS Budgets"]'::jsonb, NOW())
