INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-101', 'practice_283', 'Một công ty đang có kế hoạch di chuyển sang Đám mây AWS. Công ty đang tiến hành chuyển đổi tổ chức và mong muốn phản hồi nhanh hơn các yêu cầu và phản hồi của khách hàng. Công ty nên thực hiện những nhiệm vụ nào để đáp ứng các yêu cầu này theo Khung áp dụng đám mây AWS (AWS CAF)? (Chọn HAI.)', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Sắp xếp lại các nhóm để tập trung vào sản phẩm và dòng giá trị, đồng thời sử dụng các phương pháp linh hoạt để lặp lại và phát triển nhanh chóng là những nhiệm vụ mà công ty nên thực hiện nhằm đáp ứng yêu cầu phản hồi nhanh hơn các yêu cầu và phản hồi của khách hàng, theo Khung áp dụng đám mây AWS (AWS CAF). AWS CAF tổ chức hướng dẫn thành sáu lĩnh vực trọng tâm, được gọi là quan điểm: kinh doanh, con người, quản trị, nền tảng, bảo mật và vận hành. Mỗi khía cạnh được chia thành các khả năng, mô tả các kỹ năng và quy trình để thực hiện quá trình chuyển đổi một cách hiệu quả. Quan điểm con người giúp bạn chuẩn bị cho tổ chức của mình áp dụng đám mây và bao gồm các khả năng như quản lý thay đổi tổ chức, kỹ năng và sự sẵn sàng của nhân viên cũng như sự liên kết của tổ chức. Quan điểm kinh doanh giúp bạn điều chỉnh chiến lược CNTT với chiến lược kinh doanh và bao gồm các khả năng như phát triển đề án kinh doanh, đề xuất giá trị và quyền sở hữu sản phẩm. Tạo ra các tuyên bố giá trị mới bằng các sản phẩm và dịch vụ mới là một nhiệm vụ thuộc về quan điểm kinh doanh, nhưng nó không liên quan trực tiếp đến yêu cầu phản hồi nhanh hơn các yêu cầu và phản hồi của khách hàng. Sử dụng nền tảng dữ liệu và phân tích mới để tạo ra những hiểu biết hữu ích là một nhiệm vụ thuộc về quan điểm nền tảng, giúp bạn thiết kế, triển khai và tối ưu hóa kiến ​​trúc của môi trường AWS. Tuy nhiên, nó cũng không liên quan trực tiếp đến yêu cầu đáp ứng tốt hơn các yêu cầu và phản hồi của khách hàng. Di chuyển và hiện đại hóa cơ sở hạ tầng cũ là một nhiệm vụ thuộc góc độ hoạt động, giúp bạn kích hoạt, vận hành, sử dụng, vận hành và khôi phục khối lượng công việc CNTT đến mức đã thỏa thuận với các bên liên quan trong doanh nghiệp của bạn. Tuy nhiên, nó cũng không liên quan trực tiếp đến yêu cầu đáp ứng tốt hơn các yêu cầu và phản hồi của khách hàng.', '[{"label": "A", "text_vi": "Sắp xếp lại các nhóm để tập trung vào sản phẩm và dòng giá trị.", "is_correct": true, "analysis_vi": "Đúng. Sắp xếp lại các nhóm để tập trung vào sản phẩm và dòng giá trị. là đáp án chính xác. Sắp xếp lại các nhóm để tập trung vào sản phẩm và dòng giá trị, đồng thời sử dụng các phương pháp linh hoạt để lặp lại và phát triển nhanh chóng là những nhiệm vụ mà công ty nên thực hiện nhằm đáp ứng yêu cầu phản hồi nhanh hơn các yêu cầu và phản hồi của khách hàng, theo Khung áp dụng đám mây AWS (AWS CAF)."}, {"label": "B", "text_vi": "Tạo ra các tuyên bố giá trị mới bằng các sản phẩm và dịch vụ mới.", "is_correct": false, "analysis_vi": "Sai. Tạo ra các tuyên bố giá trị mới bằng các sản phẩm và dịch vụ mới. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Sử dụng các phương pháp linh hoạt để lặp lại và phát triển nhanh chóng.", "is_correct": true, "analysis_vi": "Đúng. Sử dụng các phương pháp linh hoạt để lặp lại và phát triển nhanh chóng. là đáp án chính xác. Sắp xếp lại các nhóm để tập trung vào sản phẩm và dòng giá trị, đồng thời sử dụng các phương pháp linh hoạt để lặp lại và phát triển nhanh chóng là những nhiệm vụ mà công ty nên thực hiện nhằm đáp ứng yêu cầu phản hồi nhanh hơn các yêu cầu và phản hồi của khách hàng, theo Khung áp dụng đám mây AWS (AWS CAF)."}, {"label": "D", "text_vi": "Sử dụng nền tảng dữ liệu và phân tích mới để tạo ra những hiểu biết sâu sắc có thể hành động.", "is_correct": false, "analysis_vi": "Sai. Sử dụng nền tảng dữ liệu và phân tích mới để tạo ra những hiểu biết sâu sắc có thể hành động. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Di chuyển và hiện đại hóa cơ sở hạ tầng cũ.", "is_correct": false, "analysis_vi": "Sai. Di chuyển và hiện đại hóa cơ sở hạ tầng cũ. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
