INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-102', 'practice_283', 'Dịch vụ AWS nào có thể chạy cơ sở dữ liệu PostgreSQL được quản lý cung cấp khả năng xử lý giao dịch trực tuyến (OLTP)?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý toàn phần, hỗ trợ một số công cụ cơ sở dữ liệu, bao gồm cả PostgreSQL. Amazon RDS có thể chạy cơ sở dữ liệu PostgreSQL được quản lý cung cấp khả năng xử lý giao dịch trực tuyến (OLTP), đây là một loại khối lượng công việc cơ sở dữ liệu xử lý các hoạt động đọc và ghi thường xuyên trên một lượng nhỏ dữ liệu. Amazon RDS cho PostgreSQL mang lại hiệu suất, độ sẵn sàng, khả năng mở rộng, bảo mật và khả năng tương thích cao với phiên bản cộng đồng PostgreSQL. Amazon RDS cũng cung cấp tính năng sao lưu tự động, khôi phục tại thời điểm, mã hóa, giám sát và bảo trì cho cơ sở dữ liệu PostgreSQL.', '[{"label": "A", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon DynamoDB: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon Athena", "is_correct": false, "analysis_vi": "Sai. Amazon Athena không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Amazon RDS", "is_correct": true, "analysis_vi": "Đúng. Amazon RDS là giải pháp đáp ứng yêu cầu. Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý toàn phần, hỗ trợ một số công cụ cơ sở dữ liệu, bao gồm cả PostgreSQL. Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao."}, {"label": "D", "text_vi": "Amazon EMR", "is_correct": false, "analysis_vi": "Sai. Amazon EMR không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon RDS", "Amazon DynamoDB"]'::jsonb, NOW())
