INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-103', 'practice_283', 'AWS chịu trách nhiệm về tùy chọn nào theo mô hình trách nhiệm chung của AWS?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Phần cứng và cơ sở hạ tầng là tùy chọn mà AWS chịu trách nhiệm theo mô hình trách nhiệm chung của AWS. Mô hình trách nhiệm chung của AWS mô tả cách AWS và khách hàng chia sẻ trách nhiệm về bảo mật và tuân thủ trên đám mây. AWS chịu trách nhiệm bảo mật đám mây, nghĩa là bảo vệ cơ sở hạ tầng chạy tất cả các dịch vụ được cung cấp trên Đám mây AWS. Cơ sở hạ tầng này bao gồm phần cứng, phần mềm, mạng và cơ sở vật chất chạy các dịch vụ Đám mây AWS. Khách hàng chịu trách nhiệm về bảo mật trên đám mây, nghĩa là quan tâm đến tính bảo mật của các ứng dụng, dữ liệu và hệ điều hành của chính họ. Điều này bao gồm cấu hình mạng và tường lửa, mã hóa dữ liệu phía máy khách, quản lý quyền của người dùng, v.v.', '[{"label": "A", "text_vi": "Cấu hình mạng và tường lửa", "is_correct": false, "analysis_vi": "Sai. Cấu hình mạng và tường lửa: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Mã hóa dữ liệu phía máy khách", "is_correct": false, "analysis_vi": "Sai. Mã hóa dữ liệu phía máy khách không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Quản lý quyền của người dùng", "is_correct": false, "analysis_vi": "Sai. Quản lý quyền của người dùng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Phần cứng và cơ sở hạ tầng", "is_correct": true, "analysis_vi": "Đúng. Phần cứng và cơ sở hạ tầng là đáp án chính xác. Phần cứng và cơ sở hạ tầng là tùy chọn mà AWS chịu trách nhiệm theo mô hình trách nhiệm chung của AWS."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '[]'::jsonb, NOW())
