INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-104', 'practice_283', 'Một công ty đang có kế hoạch chuyển sang Đám mây AWS và muốn phản hồi nhanh hơn các yêu cầu và phản hồi của khách hàng. Công ty muốn tập trung vào việc chuyển đổi tổ chức. Một công ty muốn cung cấp cho khách hàng khả năng xem dữ liệu cụ thể được lưu trữ trong bộ chứa Amazon S3. Công ty muốn giữ quyền kiểm soát toàn bộ bộ dữ liệu mà công ty chia sẻ với khách hàng. Tính năng nào của S3 sẽ đáp ứng được những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ lưu trữ Amazon S3 & Vòng đời dữ liệu', 'Điểm truy cập S3 là một tính năng của Amazon S3 cho phép bạn dễ dàng quản lý quyền truy cập vào dữ liệu cụ thể được lưu trữ trong bộ chứa S3. Điểm truy cập S3 là tên máy chủ duy nhất mà khách hàng có thể sử dụng để truy cập dữ liệu trong bộ chứa S3. Bạn có thể tạo nhiều điểm truy cập cho một nhóm duy nhất, mỗi nhóm có tên và quyền riêng. Bạn có thể sử dụng Điểm truy cập S3 để cung cấp các cấp độ truy cập khác nhau cho các nhóm khách hàng khác nhau, chẳng hạn như quyền truy cập chỉ đọc hoặc chỉ ghi. Bạn cũng có thể sử dụng Điểm truy cập S3 để thực thi các yêu cầu mã hóa hoặc ghi nhật ký đối với dữ liệu cụ thể. Điểm truy cập S3 giúp bạn giữ quyền kiểm soát toàn bộ tập dữ liệu mà bạn chia sẻ với khách hàng, đồng thời đơn giản hóa việc quản lý quyền truy cập và cải thiện hiệu suất cũng như khả năng mở rộng của ứng dụng.', '[{"label": "A", "text_vi": "Ống kính lưu trữ S3", "is_correct": false, "analysis_vi": "Sai. Ống kính lưu trữ S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Sao chép liên vùng S3 (CRR)", "is_correct": false, "analysis_vi": "Sai. Sao chép liên vùng S3 (CRR): Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Phiên bản S3", "is_correct": false, "analysis_vi": "Sai. Phiên bản S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Điểm truy cập S3", "is_correct": true, "analysis_vi": "Đúng. Điểm truy cập S3 là đáp án chính xác. Điểm truy cập S3 là một tính năng của Amazon S3 cho phép bạn dễ dàng quản lý quyền truy cập vào dữ liệu cụ thể được lưu trữ trong bộ chứa S3."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3"]'::jsonb, NOW())
