INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-105', 'practice_283', 'Một công ty muốn thiết kế một ứng dụng web đáng tin cậy được lưu trữ trên Amazon EC2. Cách tiếp cận nào sẽ đạt được mục tiêu này?', 'Domain 2: Security and Compliance', 'Dịch vụ điện toán đám mây Amazon EC2', 'Cách tiếp cận sẽ đạt được mục tiêu thiết kế một ứng dụng web đáng tin cậy được lưu trữ trên Amazon EC2 là trải rộng các phiên bản EC2 trên nhiều Availability Zone (AZ). Availability Zone (AZ) là một vị trí biệt lập về mặt vật lý trong AWS Region có nguồn điện, khả năng làm mát và kết nối mạng riêng. Bằng cách trải rộng các phiên bản EC2 trên nhiều Availability Zone (AZ), người dùng có thể tăng khả năng chịu lỗi và tính khả dụng của ứng dụng web của họ, cũng như giảm độ trễ cho người dùng cuối2. Việc khởi chạy các phiên bản EC2 lớn trong cùng Availability Zone (AZ), phân bổ các phiên bản EC2 trên nhiều Security Group hoặc sử dụng Hình ảnh máy Amazon (AMI) từ AWS Marketplace là không đủ để đảm bảo độ tin cậy vì chúng không cung cấp khả năng dự phòng hoặc khả năng phục hồi trong trường hợp mất điện ở một Availability Zone (AZ).', '[{"label": "A", "text_vi": "Khởi chạy các phiên bản EC2 lớn trong cùng Availability Zone (AZ).", "is_correct": false, "analysis_vi": "Sai. Khởi chạy các phiên bản EC2 lớn trong cùng Availability Zone (AZ).: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Trải rộng các phiên bản EC2 trên nhiều Security Group.", "is_correct": false, "analysis_vi": "Sai. Trải rộng các phiên bản EC2 trên nhiều Security Group.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Trải rộng các phiên bản EC2 trên nhiều Availability Zone (AZ).", "is_correct": true, "analysis_vi": "Đúng. Trải rộng các phiên bản EC2 trên nhiều Availability Zone (AZ). là đáp án chính xác. Cách tiếp cận sẽ đạt được mục tiêu thiết kế một ứng dụng web đáng tin cậy được lưu trữ trên Amazon EC2 là trải rộng các phiên bản EC2 trên nhiều Availability Zone (AZ)."}, {"label": "D", "text_vi": "Sử dụng Hình ảnh máy Amazon (AMI) từ AWS Marketplace.", "is_correct": false, "analysis_vi": "Sai. Sử dụng Hình ảnh máy Amazon (AMI) từ AWS Marketplace. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
