INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-106', 'practice_283', 'Những dịch vụ AWS nào được Savings Plans hỗ trợ? (Chọn HAI.)', 'Domain 4: Billing, Pricing and Support', 'Các gói hỗ trợ kỹ thuật AWS Support Plans', 'Các dịch vụ AWS được Savings Plans hỗ trợ là: Amazon EC2: Amazon EC2 là dịch vụ cung cấp khả năng tính toán có thể mở rộng trên đám mây AWS. Bạn có thể sử dụng Amazon EC2 để khởi chạy máy chủ ảo, đặt cấu hình bảo mật và kết nối mạng cũng như quản lý bộ nhớ. Amazon EC2 đủ điều kiện cho cả Kế hoạch tiết kiệm điện toán và Kế hoạch tiết kiệm phiên bản EC212. Amazon SageMaker: Amazon SageMaker là dịch vụ giúp bạn xây dựng và triển khai các mô hình machine learning. Bạn có thể sử dụng Amazon SageMaker để truy cập sổ ghi chép Jupyter, sử dụng các thuật toán học máy phổ biến, đào tạo và điều chỉnh các mô hình cũng như triển khai chúng trên môi trường được lưu trữ. Amazon SageMaker đủ điều kiện tham gia SageMaker Savings Plans13. Các tùy chọn khác không được Savings Plans hỗ trợ. Amazon RDS, Amazon Redshift và Amazon DynamoDB là các dịch vụ cơ sở dữ liệu đủ điều kiện cho Phiên bản dự trữ, nhưng không đủ điều kiện cho Savings Plans4. Các bãi chứa AWS-Certified-Cloud-Practitioner hợp lệ được EduDump.com chia sẻ để giúp vượt qua kỳ thi dành cho người thực hành trên nền tảng đám mây được chứng nhận AWS! EduDump.com hiện cung cấp các kết xuất bài thi AWS- Certified-Cloud-Practitioner mới nhất, các câu hỏi thi EduDump.com AWS-Certified-Cloud-Practitioner đã được cập nhật và các câu trả lời đã được sửa. Hãy tải các kết xuất bài thi EduDump.com AWS-Certified-Cloud-Practitioner mới nhất với Test Engine tại đây: https://www.edudump.com/exams/Amazon/AWS-Certified-Cloud-Practitioner/premium/ ( 600 lượt hỏi đáp, GIẢM GIÁ 35% Mã giảm giá đặc biệt: freecram )', '[{"label": "A", "text_vi": "Amazon EC2", "is_correct": true, "analysis_vi": "Đúng. Amazon EC2 là giải pháp đáp ứng yêu cầu. Các dịch vụ AWS được Savings Plans hỗ trợ là: Amazon EC2: Amazon EC2 là dịch vụ cung cấp khả năng tính toán có thể mở rộng trên đám mây AWS. Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật."}, {"label": "B", "text_vi": "Amazon RDS", "is_correct": true, "analysis_vi": "Đúng. Amazon RDS là giải pháp đáp ứng yêu cầu. Các dịch vụ AWS được Savings Plans hỗ trợ là: Amazon EC2: Amazon EC2 là dịch vụ cung cấp khả năng tính toán có thể mở rộng trên đám mây AWS. Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao."}, {"label": "C", "text_vi": "Amazon SageMaker", "is_correct": false, "analysis_vi": "Sai. Amazon SageMaker không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Dịch chuyển đỏ của Amazon", "is_correct": false, "analysis_vi": "Sai. Amazon RDS, Amazon Redshift và Amazon DynamoDB là các dịch vụ cơ sở dữ liệu đủ điều kiện cho Phiên bản dự trữ, nhưng không đủ điều kiện cho Savings Plans4."}, {"label": "E", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon RDS, Amazon Redshift và Amazon DynamoDB là các dịch vụ cơ sở dữ liệu đủ điều kiện cho Phiên bản dự trữ, nhưng không đủ điều kiện cho Savings Plans4."}]'::jsonb, '["Ghi nhớ các ngưỡng SLA phản hồi: Business (<1h cho production down, 24/7 phone/chat/email), Enterprise (<15m cho mission-critical, có TAM)."]'::jsonb, '[{"term": "support plan", "points_to": "Developer / Business / Enterprise"}]'::jsonb, '["Amazon EC2", "Amazon RDS", "Amazon DynamoDB"]'::jsonb, NOW())
