INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-107', 'practice_283', 'Một công ty có hai tài khoản AWS trong một tổ chức trong AWS Organs để thanh toán tổng hợp. Tất cả tài nguyên AWS của công ty đều được lưu trữ tại một AWS Region. Tài khoản A đã mua 5 Phiên bản dự trữ tiêu chuẩn (RI) của Amazon EC2 và có 4 phiên bản EC2 đang chạy. Tài khoản B chưa mua bất kỳ RI nào và cũng có 4 phiên bản EC2 đang chạy. Câu nào đúng về giá của tám trường hợp này?', 'Domain 4: Billing, Pricing and Support', 'Dịch vụ điện toán đám mây Amazon EC2', 'Tuyên bố đúng về giá của tám phiên bản này là: bốn phiên bản sẽ được tính phí dưới dạng RI và bốn phiên bản sẽ được tính phí như phiên bản thông thường. Phiên bản dự trữ (RI) của Amazon EC2 là mô hình định giá cho phép người dùng đặt trước phiên bản EC2 trong một thời hạn cụ thể và hưởng lợi từ mức giá chiết khấu theo giờ cũng như dự trữ công suất. RI được mua cho một AWS Region cụ thể và có thể được chia sẻ trên nhiều tài khoản trong một tổ chức trong AWS Organs để thanh toán tổng hợp. Tuy nhiên, RI được áp dụng trên cơ sở ai đến trước được phục vụ trước và không có gì đảm bảo rằng tất cả các phiên bản trong tổ chức sẽ bị tính phí theo mức RI. Trong trường hợp này, Tài khoản A đã mua 5 RI và có 4 phiên bản đang chạy, do đó cả 4 phiên bản sẽ bị tính phí theo mức RI. Tài khoản B chưa mua bất kỳ RI nào và cũng có 4 phiên bản đang chạy, vì vậy cả 4 phiên bản sẽ bị tính phí ở mức thông thường. RI còn lại trong Tài khoản A sẽ không được áp dụng cho bất kỳ phiên bản nào trong Tài khoản B và sẽ bị lãng phí.', '[{"label": "A", "text_vi": "Tám phiên bản sẽ được tính phí như phiên bản thông thường.", "is_correct": false, "analysis_vi": "Sai. Tám phiên bản sẽ được tính phí như phiên bản thông thường. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Bốn phiên bản sẽ bị tính phí dưới dạng RI và bốn phiên bản sẽ bị tính phí như phiên bản thông thường.", "is_correct": true, "analysis_vi": "Đúng. Bốn phiên bản sẽ bị tính phí dưới dạng RI và bốn phiên bản sẽ bị tính phí như phiên bản thông thường. là đáp án chính xác. Tuyên bố đúng về giá của tám phiên bản này là: bốn phiên bản sẽ được tính phí dưới dạng RI và bốn phiên bản sẽ được tính phí như phiên bản thông thường."}, {"label": "C", "text_vi": "Năm phiên bản sẽ bị tính phí dưới dạng RI và ba phiên bản sẽ bị tính phí như phiên bản thông thường.", "is_correct": false, "analysis_vi": "Sai. Năm phiên bản sẽ bị tính phí dưới dạng RI và ba phiên bản sẽ bị tính phí như phiên bản thông thường. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Tám phiên bản sẽ được tính phí dưới dạng RI.", "is_correct": false, "analysis_vi": "Sai. Tám phiên bản sẽ được tính phí dưới dạng RI. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon EC2", "AWS Organizations"]'::jsonb, NOW())
