INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-108', 'practice_283', 'Tính năng hoặc tài nguyên AWS nào là mẫu phiên bản Amazon EC2 có thể triển khai được đóng gói sẵn với các yêu cầu về phần mềm và bảo mật?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Amazon Machine Image (AMI) là một mẫu phiên bản Amazon EC2 có thể triển khai được đóng gói sẵn với các yêu cầu về phần mềm và bảo mật. Nó cung cấp thông tin cần thiết để khởi chạy một phiên bản, đó là một máy chủ ảo trên đám mây. Bạn có thể sử dụng AMI để khởi chạy bao nhiêu phiên bản tùy thích. Bạn cũng có thể tạo AMI tùy chỉnh của riêng mình hoặc sử dụng AMI được chia sẻ bởi những người dùng AWS khác1.', '[{"label": "A", "text_vi": "Khối lượng Amazon Elastic Block Store (Amazon EBS)", "is_correct": false, "analysis_vi": "Sai. Khối lượng Amazon Elastic Block Store (Amazon EBS): Amazon EBS cung cấp các khối lưu trữ cấp block gắn trực tiếp vào phiên bản EC2 với độ trễ thấp và tính bền vững cao trong một Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Mẫu AWS CloudFormation", "is_correct": false, "analysis_vi": "Sai. Mẫu AWS CloudFormation không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Ảnh chụp nhanh của Amazon Elastic Block Store (Amazon EBS)", "is_correct": false, "analysis_vi": "Sai. Ảnh chụp nhanh của Amazon Elastic Block Store (Amazon EBS): Amazon EBS cung cấp các khối lưu trữ cấp block gắn trực tiếp vào phiên bản EC2 với độ trễ thấp và tính bền vững cao trong một Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Hình ảnh máy Amazon (AMI)", "is_correct": true, "analysis_vi": "Đúng. Hình ảnh máy Amazon (AMI) là đáp án chính xác. Amazon Machine Image (AMI) là một mẫu phiên bản Amazon EC2 có thể triển khai được đóng gói sẵn với các yêu cầu về phần mềm và bảo mật."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["Amazon EC2", "AWS CloudFormation"]'::jsonb, NOW())
