INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-109', 'practice_283', 'Một công ty có một phiên bản Amazon EC2 duy nhất. Công ty muốn áp dụng một kiến ​​trúc có tính sẵn sàng cao. Công ty có thể làm gì để đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Mở rộng quy mô theo chiều ngang trên nhiều Availability Zone (AZ) là một cách để áp dụng kiến trúc có tính sẵn sàng cao vì nó làm tăng khả năng chịu lỗi và khả năng phục hồi của ứng dụng. Mở rộng quy mô theo chiều dọc đến kích thước phiên bản EC2 lớn hơn là một cách để cải thiện hiệu suất của ứng dụng, nhưng nó không cải thiện tính khả dụng. Mua Phiên bản chuyên dụng EC2 là một cách để tách phiên bản đó khỏi các khách hàng AWS khác, nhưng việc này không cải thiện tính khả dụng. Việc thay đổi dòng phiên bản EC2 thành phiên bản được tối ưu hóa điện toán là một cách để tối ưu hóa loại phiên bản cho khối lượng công việc nhưng không cải thiện tính khả dụng. Những khái niệm này được giải thích trong AWS Well- Architected Framework2.', '[{"label": "A", "text_vi": "Chia tỷ lệ theo chiều dọc thành kích thước phiên bản EC2 lớn hơn.", "is_correct": false, "analysis_vi": "Sai. Chia tỷ lệ theo chiều dọc thành kích thước phiên bản EC2 lớn hơn.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Chia tỷ lệ theo chiều ngang trên nhiều Availability Zone (AZ).", "is_correct": true, "analysis_vi": "Đúng. Chia tỷ lệ theo chiều ngang trên nhiều Availability Zone (AZ). là đáp án chính xác. Mở rộng quy mô theo chiều ngang trên nhiều Availability Zone (AZ) là một cách để áp dụng kiến trúc có tính sẵn sàng cao vì nó làm tăng khả năng chịu lỗi và khả năng phục hồi của ứng dụng."}, {"label": "C", "text_vi": "Mua Phiên bản chuyên dụng EC2.", "is_correct": false, "analysis_vi": "Sai. Mua Phiên bản chuyên dụng EC2.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Thay đổi dòng phiên bản EC2 thành phiên bản được tối ưu hóa về điện toán.", "is_correct": false, "analysis_vi": "Sai. Mở rộng quy mô theo chiều dọc đến kích thước phiên bản EC2 lớn hơn là một cách để cải thiện hiệu suất của ứng dụng, nhưng nó không cải thiện tính khả dụng."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
