INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-110', 'practice_283', 'Một công ty có một thư viện băng từ vật lý để lưu trữ các bản sao lưu dữ liệu. Thư viện băng sắp hết dung lượng. Công ty cần mở rộng dung lượng của thư viện băng từ lên Đám mây AWS. Công ty nên sử dụng dịch vụ AWS nào để đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS Storage Gateway là dịch vụ lưu trữ đám mây lai cung cấp quyền truy cập tại chỗ vào bộ lưu trữ đám mây gần như không giới hạn. Bạn có thể sử dụng AWS Storage Gateway để đơn giản hóa việc quản lý lưu trữ và giảm chi phí cho các trường hợp sử dụng lưu trữ đám mây kết hợp chính. Một trong những trường hợp sử dụng này là sao lưu dựa trên băng từ, cho phép bạn lưu trữ các bản sao lưu dữ liệu trên băng ảo trong Đám mây AWS. Bạn có thể sử dụng tính năng Cổng băng từ của AWS Storage Gateway để mở rộng thư viện băng từ vật lý hiện có của mình lên Đám mây AWS. Cổng băng từ cung cấp cơ sở hạ tầng băng từ ảo có khả năng mở rộng quy mô một cách liền mạch theo nhu cầu sao lưu của bạn và loại bỏ gánh nặng hoạt động trong việc cung cấp, mở rộng quy mô và duy trì cơ sở hạ tầng băng từ vật lý123.', '[{"label": "A", "text_vi": "Hệ thống tệp đàn hồi của Amazon (Amazon EFS)", "is_correct": false, "analysis_vi": "Sai. Hệ thống tệp đàn hồi của Amazon (Amazon EFS): Amazon EFS cung cấp hệ thống tệp chia sẻ mạng (NFS) co giãn hoàn toàn tự động, có thể gắn đồng thời vào hàng nghìn phiên bản EC2 trên nhiều AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Cửa hàng khối đàn hồi Amazon (Amazon EBS)", "is_correct": true, "analysis_vi": "Đúng. Cửa hàng khối đàn hồi Amazon (Amazon EBS) là giải pháp đáp ứng yêu cầu. AWS Storage Gateway là dịch vụ lưu trữ đám mây lai cung cấp quyền truy cập tại chỗ vào bộ lưu trữ đám mây gần như không giới hạn. Amazon EBS cung cấp các khối lưu trữ cấp block gắn trực tiếp vào phiên bản EC2 với độ trễ thấp và tính bền vững cao trong một Availability Zone."}, {"label": "C", "text_vi": "Amazon S3", "is_correct": false, "analysis_vi": "Sai. Amazon S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "AWS Storage Gateway", "is_correct": false, "analysis_vi": "Sai. AWS Storage Gateway là dịch vụ lưu trữ đám mây lai cung cấp quyền truy cập tại chỗ vào bộ lưu trữ đám mây gần như không giới hạn."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3", "AWS Storage Gateway"]'::jsonb, NOW())
