INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-111', 'practice_283', 'Một công ty muốn các phiên bản Amazon EC2 của mình dùng chung khu vực địa lý nhưng sử dụng nhiều nguồn điện cơ bản độc lập. Giải pháp nào đạt được mục tiêu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Giải pháp đạt được mục tiêu là có các phiên bản Amazon EC2 dùng chung cùng một khu vực địa lý nhưng sử dụng nhiều nguồn điện cơ bản độc lập là sử dụng các phiên bản EC2 trong nhiều Availability Zone (AZ) trong cùng một AWS Region. Availability Zone (AZ) là một vị trí biệt lập về mặt vật lý trong AWS Region có nguồn điện, khả năng làm mát và kết nối mạng riêng. AWS Region là một khu vực địa lý bao gồm hai Availability Zone (AZ) trở lên. Bằng cách sử dụng nhiều Availability Zone (AZ), người dùng có thể tăng khả năng chịu lỗi và khả năng phục hồi của ứng dụng cũng như giảm độ trễ cho người dùng cuối3. Việc sử dụng các phiên bản EC2 trong một Availability Zone (AZ), nhiều AWS Region hoặc cùng một vị trí biên và cùng một AWS Region sẽ không đáp ứng yêu cầu có nhiều nguồn điện độc lập.', '[{"label": "A", "text_vi": "Sử dụng các phiên bản EC2 trong một Availability Zone (AZ) duy nhất.", "is_correct": false, "analysis_vi": "Sai. Sử dụng các phiên bản EC2 trong một Availability Zone (AZ) duy nhất.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Sử dụng phiên bản EC2 ở nhiều AWS Region.", "is_correct": false, "analysis_vi": "Sai. Sử dụng phiên bản EC2 ở nhiều AWS Region.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Sử dụng các phiên bản EC2 trong nhiều Availability Zone (AZ) trong cùng một AWS Region.", "is_correct": true, "analysis_vi": "Đúng. Sử dụng các phiên bản EC2 trong nhiều Availability Zone (AZ) trong cùng một AWS Region. là đáp án chính xác. Giải pháp đạt được mục tiêu là có các phiên bản Amazon EC2 dùng chung cùng một khu vực địa lý nhưng sử dụng nhiều nguồn điện cơ bản độc lập là sử dụng các phiên bản EC2 trong nhiều Availability Zone (AZ) trong cùng một AWS Region."}, {"label": "D", "text_vi": "Sử dụng các phiên bản EC2 ở cùng vị trí biên và cùng AWS Region.", "is_correct": false, "analysis_vi": "Sai. Sử dụng các phiên bản EC2 ở cùng vị trí biên và cùng AWS Region.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
