INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-112', 'practice_283', 'Một công ty muốn dịch vụ AWS cung cấp đề xuất sản phẩm dựa trên dữ liệu khách hàng của mình. Dịch vụ AWS nào sẽ đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Amazon Personalize là dịch vụ AWS giúp các nhà phát triển nhanh chóng xây dựng và triển khai công cụ đề xuất tùy chỉnh với khả năng cá nhân hóa và phân khúc người dùng theo thời gian thực1. Nó sử dụng máy học (ML) để phân tích dữ liệu khách hàng và đưa ra các đề xuất có liên quan dựa trên sở thích, hành vi và bối cảnh của họ. Bạn có thể sử dụng Amazon Personalize cho nhiều trường hợp sử dụng khác nhau như tối ưu hóa đề xuất, nhắm mục tiêu khách hàng chính xác hơn, tối đa hóa giá trị của văn bản phi cấu trúc và quảng cáo các mặt hàng bằng quy tắc kinh doanh1. Các tùy chọn khác không phù hợp để cung cấp đề xuất sản phẩm dựa trên dữ liệu khách hàng. Amazon Polly là dịch vụ chuyển đổi văn bản thành giọng nói sống động như thật. Amazon Comprehend là dịch vụ sử dụng xử lý ngôn ngữ tự nhiên (NLP) để trích xuất thông tin chuyên sâu từ văn bản và tài liệu. Amazon Rekognition là dịch vụ sử dụng thị giác máy tính (CV) để phân tích hình ảnh và video về khuôn mặt, vật thể, cảnh và hoạt động.', '[{"label": "A", "text_vi": "Amazon Polly", "is_correct": false, "analysis_vi": "Sai. Amazon Polly không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Amazon Personalize", "is_correct": true, "analysis_vi": "Đúng. Amazon Personalize là đáp án chính xác. Amazon Personalize là dịch vụ AWS giúp các nhà phát triển nhanh chóng xây dựng và triển khai công cụ đề xuất tùy chỉnh với khả năng cá nhân hóa và phân khúc người dùng theo thời gian thực1."}, {"label": "C", "text_vi": "Amazon Hiểu", "is_correct": false, "analysis_vi": "Sai. Amazon Hiểu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Nhận thức lại Amazon", "is_correct": false, "analysis_vi": "Sai. Nhận thức lại Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
