INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-113', 'practice_283', 'Khả năng phối cảnh con người của AWS Cloud Adoption Framework (AWS CAF) có những tùy chọn nào? (Chọn HAI.)', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Khả năng phối cảnh con người của Khung áp dụng đám mây AWS (AWS CAF) là các kỹ năng và quy trình tổ chức cho phép áp dụng đám mây hiệu quả. Theo báo cáo chuyên sâu về quan điểm con người của AWS CAF1, có bảy khả năng trong quan điểm này, hai trong số đó là: Liên kết tổ chức: Khả năng này giúp bạn điều chỉnh cơ cấu tổ chức, vai trò và trách nhiệm để hỗ trợ các mục tiêu và mục đích chuyển đổi đám mây của bạn. Quá trình này bao gồm việc đánh giá trạng thái liên kết hiện tại và mong muốn của bạn, xác định các khoảng trống và sai lệch cũng như thiết kế và triển khai các thay đổi để tối ưu hóa hiệu suất đám mây của bạn1. Thiết kế tổ chức: Khả năng này giúp bạn thiết kế và phát triển tổ chức của mình để mang lại sự linh hoạt, đổi mới và cộng tác trên đám mây. Nó liên quan đến việc xác định mô hình vận hành đám mây của bạn, xác định các kỹ năng và năng lực cần thiết cho các vai trò trên đám mây, đồng thời tạo ra lộ trình nghề nghiệp và kế hoạch phát triển cho lực lượng lao động trên đám mây của bạn1. Các tùy chọn khác không phải là khả năng ở góc độ con người AWS CAF. Quản lý danh mục đầu tư, quản lý rủi ro và phát triển ứng dụng hiện đại lần lượt là các khả năng ở góc độ kinh doanh, góc độ quản trị và góc độ nền tảng của AWS CAF2.', '[{"label": "A", "text_vi": "Liên kết tổ chức", "is_correct": true, "analysis_vi": "Đúng. Liên kết tổ chức là đáp án chính xác. Khả năng phối cảnh con người của Khung áp dụng đám mây AWS (AWS CAF) là các kỹ năng và quy trình tổ chức cho phép áp dụng đám mây hiệu quả."}, {"label": "B", "text_vi": "Quản lý danh mục đầu tư", "is_correct": false, "analysis_vi": "Sai. Quản lý danh mục đầu tư không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Thiết kế tổ chức", "is_correct": true, "analysis_vi": "Đúng. Thiết kế tổ chức là đáp án chính xác. Khả năng phối cảnh con người của Khung áp dụng đám mây AWS (AWS CAF) là các kỹ năng và quy trình tổ chức cho phép áp dụng đám mây hiệu quả."}, {"label": "D", "text_vi": "Quản lý rủi ro", "is_correct": false, "analysis_vi": "Sai. Quản lý rủi ro không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Phát triển ứng dụng hiện đại", "is_correct": false, "analysis_vi": "Sai. Phát triển ứng dụng hiện đại không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
