INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-114', 'practice_283', 'Nhà phát triển muốn triển khai ứng dụng một cách nhanh chóng trên AWS mà không cần tạo các tài nguyên cần thiết theo cách thủ công. Dịch vụ AWS nào sẽ đáp ứng những yêu cầu này?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'AWS Elastic Beanstalk là dịch vụ cho phép bạn triển khai và quản lý ứng dụng trên AWS mà không cần tạo và đặt cấu hình thủ công các tài nguyên cần thiết, chẳng hạn như phiên bản EC2, Load Balancer (ELB), Security Group, cơ sở dữ liệu, v.v. AWS Elastic Beanstalk tự động xử lý việc cung cấp, thay đổi quy mô, cân bằng tải, theo dõi tình trạng và cập nhật ứng dụng của bạn, đồng thời cung cấp cho bạn toàn quyền kiểm soát các tài nguyên AWS cơ bản nếu cần. AWS Elastic Beanstalk hỗ trợ nhiều nền tảng và ngôn ngữ khác nhau, chẳng hạn như Java, .NET, PHP, Node.js, Python, Ruby, Go và Docker. Bạn có thể sử dụng Bảng điều khiển quản lý AWS, AWS CLI, AWS SDK hoặc API AWS Elastic Beanstalk để tạo và quản lý ứng dụng của mình. Bạn cũng có thể sử dụng AWS CodeStar, AWS CodeCommit, AWS CodeBuild, AWS CodeDeploy và AWS CodePipeline để tích hợp AWS Elastic Beanstalk với quy trình phát triển và triển khai của bạn12', '[{"label": "A", "text_vi": "Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "AWS Elastic Beanstalk", "is_correct": true, "analysis_vi": "Đúng. AWS Elastic Beanstalk là đáp án chính xác. AWS Elastic Beanstalk là dịch vụ cho phép bạn triển khai và quản lý ứng dụng trên AWS mà không cần tạo và đặt cấu hình thủ công các tài nguyên cần thiết, chẳng hạn như phiên bản EC2, Load Balancer (ELB), Security Group, cơ sở dữ liệu, v.v."}, {"label": "C", "text_vi": "AWS CodeBuild", "is_correct": false, "analysis_vi": "Sai. AWS CodeBuild không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Amazon Personalize", "is_correct": false, "analysis_vi": "Sai. Amazon Personalize không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS Elastic Beanstalk"]'::jsonb, NOW())
