INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-115', 'practice_283', 'Một công ty muốn chuyển sang AWS và sử dụng cùng phần mềm bảo mật mà công ty sử dụng tại cơ sở. Nhà cung cấp phần mềm bảo mật cung cấp phần mềm bảo mật của mình dưới dạng dịch vụ trên AWS. Công ty có thể mua giải pháp bảo mật ở đâu?', 'Domain 3: Cloud Technology and Services', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'AWS Marketplace là cửa hàng trực tuyến giúp khách hàng tìm, mua và bắt đầu sử dụng ngay phần mềm và dịch vụ chạy trên AWS. Khách hàng có thể chọn từ nhiều sản phẩm phần mềm thuộc các danh mục phổ biến như bảo mật, kết nối mạng, lưu trữ, học máy, kinh doanh thông minh, cơ sở dữ liệu và DevOps. Khách hàng cũng có thể sử dụng AWS Marketplace để mua giải pháp phần mềm dưới dạng dịch vụ (SaaS) được tích hợp với AWS. Khách hàng có thể hưởng lợi từ quy trình mua sắm, thanh toán và triển khai được đơn giản hóa cũng như các tùy chọn giá linh hoạt và bản dùng thử miễn phí. Khách hàng cũng có thể tận dụng AWS Marketplace để khám phá và đăng ký các giải pháp do Đối tác AWS cung cấp, chẳng hạn như nhà cung cấp phần mềm bảo mật được đề cập trong câu hỏi.', '[{"label": "A", "text_vi": "Công cụ tìm giải pháp đối tác AWS", "is_correct": false, "analysis_vi": "Sai. Công cụ tìm giải pháp đối tác AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Trung tâm hỗ trợ AWS", "is_correct": false, "analysis_vi": "Sai. Trung tâm hỗ trợ AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Bảng điều khiển quản lý AWS", "is_correct": false, "analysis_vi": "Sai. Bảng điều khiển quản lý AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Thị trường AWS", "is_correct": true, "analysis_vi": "Đúng. Thị trường AWS là đáp án chính xác. AWS Marketplace là cửa hàng trực tuyến giúp khách hàng tìm, mua và bắt đầu sử dụng ngay phần mềm và dịch vụ chạy trên AWS."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '[]'::jsonb, NOW())
