INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-117', 'practice_283', 'Một công ty quản lý máy móc của nhà máy theo thời gian thực. Công ty muốn sử dụng công nghệ AWS để triển khai các ứng dụng giám sát của mình càng gần máy móc của nhà máy càng tốt. Giải pháp AWS nào sẽ đáp ứng các yêu cầu này với độ trễ NHỎ NHẤT?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS Outposts là dịch vụ được quản lý toàn phần giúp mở rộng cơ sở hạ tầng AWS, dịch vụ AWS, API và công cụ tới hầu hết mọi trung tâm dữ liệu, không gian dùng chung hoặc cơ sở tại chỗ để có trải nghiệm kết hợp thực sự nhất quán. AWS Outposts cho phép bạn chạy các dịch vụ AWS trong trung tâm dữ liệu tại chỗ của bạn1.', '[{"label": "A", "text_vi": "Tiền đồn AWS", "is_correct": true, "analysis_vi": "Đúng. Tiền đồn AWS là đáp án chính xác. AWS Outposts là dịch vụ được quản lý toàn phần giúp mở rộng cơ sở hạ tầng AWS, dịch vụ AWS, API và công cụ tới hầu hết mọi trung tâm dữ liệu, không gian dùng chung hoặc cơ sở tại chỗ để có trải nghiệm kết hợp thực sự nhất quán."}, {"label": "B", "text_vi": "Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Trình chạy ứng dụng AWS", "is_correct": false, "analysis_vi": "Sai. Trình chạy ứng dụng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Lô AWS", "is_correct": false, "analysis_vi": "Sai. Lô AWS: AWS Batch cho phép các nhà phát triển và kỹ sư dễ dàng chạy hàng trăm nghìn công việc xử lý hàng loạt (batch computing) trên AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
