INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-118', 'practice_283', 'Một công ty đang chạy phiên bản Amazon EC2 trong VPC. Một công ty thương mại điện tử đang sử dụng nhóm Amazon EC2 Auto Scaling để quản lý nhóm máy chủ web chạy trên Amazon EC2. Kiến trúc này tuân theo phương pháp thực hành tốt nhất nào về Khung kiến ​​trúc tối ưu AWS?', 'Domain 1: Cloud Concepts', 'Dịch vụ điện toán đám mây Amazon EC2', 'Thiết kế cho sự thất bại là một trong những biện pháp thực hành tốt nhất của Khung kiến trúc tối ưu AWS. Điều đó có nghĩa là kiến ​​trúc phải có khả năng phục hồi và có khả năng chịu lỗi cũng như có thể xử lý các lỗi mà không ảnh hưởng đến tính khả dụng và hiệu suất của ứng dụng. Bằng cách sử dụng các nhóm Amazon EC2 Auto Scaling, công ty thương mại điện tử có thể thiết kế để xử lý lỗi bằng cách tự động tăng hoặc giảm quy mô số lượng phiên bản EC2 dựa trên nhu cầu hoặc trạng thái hoạt động. Các nhóm Auto Scaling của Amazon EC2 cũng có thể phân phối các phiên bản EC2 trên nhiều Availability Zone (AZ), là các vị trí biệt lập trong AWS Region có nguồn điện, khả năng làm mát và kết nối mạng độc lập. Bằng cách này, công ty có thể đảm bảo rằng máy chủ web của họ có thể xử lý lưu lượng truy cập tăng đột biến, phục hồi sau lỗi và cung cấp trải nghiệm người dùng nhất quán', '[{"label": "A", "text_vi": "Đảm bảo khối lượng công việc", "is_correct": false, "analysis_vi": "Sai. Đảm bảo khối lượng công việc không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Tách rời các thành phần cơ sở hạ tầng", "is_correct": false, "analysis_vi": "Sai. Tách rời các thành phần cơ sở hạ tầng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Thiết kế cho sự thất bại", "is_correct": true, "analysis_vi": "Đúng. Thiết kế cho sự thất bại là đáp án chính xác. Thiết kế cho sự thất bại là một trong những biện pháp thực hành tốt nhất của Khung kiến trúc tối ưu AWS."}, {"label": "D", "text_vi": "Hãy suy nghĩ song song", "is_correct": false, "analysis_vi": "Sai. Điều đó có nghĩa là kiến ​​trúc phải có khả năng phục hồi và có khả năng chịu lỗi cũng như có thể xử lý các lỗi mà không ảnh hưởng đến tính khả dụng và hiệu suất của ứng dụng."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon VPC"]'::jsonb, NOW())
