INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-119', 'practice_283', 'Một công ty muốn cung cấp và quản lý cơ sở hạ tầng AWS của mình bằng cách sử dụng các ngôn ngữ lập trình phổ biến TypeScript, Python, Java và .NET. Dịch vụ AWS nào sẽ đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Bộ công cụ phát triển đám mây AWS (AWS CDK) là một khung phát triển phần mềm nguồn mở cho phép bạn lập mô hình và cung cấp cơ sở hạ tầng đám mây bằng các ngôn ngữ lập trình quen thuộc như TypeScript, Python, Java và .NET. AWS CDK cho phép bạn sử dụng sức mạnh biểu đạt của ngôn ngữ yêu thích để xác định tài nguyên đám mây của mình, chẳng hạn như các dịch vụ điện toán, lưu trữ, mạng và ứng dụng. AWS CDK cũng cung cấp một thư viện gồm các cấu trúc cấp cao đại diện cho các dịch vụ và biện pháp thực hành tốt nhất của AWS. AWS CDK sử dụng AWS CloudFormation ở chế độ nền để triển khai tài nguyên của bạn theo cách an toàn và có thể lặp lại12.', '[{"label": "A", "text_vi": "AWS CodeBuild", "is_correct": false, "analysis_vi": "Sai. AWS CodeBuild không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Đám mây AWS", "is_correct": false, "analysis_vi": "Sai. Đám mây AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "AWSCLI", "is_correct": false, "analysis_vi": "Sai. AWSCLI không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Bộ công cụ phát triển đám mây AWS (AWS CDK)", "is_correct": true, "analysis_vi": "Đúng. Bộ công cụ phát triển đám mây AWS (AWS CDK) là đáp án chính xác. Bộ công cụ phát triển đám mây AWS (AWS CDK) là một khung phát triển phần mềm nguồn mở cho phép bạn lập mô hình và cung cấp cơ sở hạ tầng đám mây bằng các ngôn ngữ lập trình quen thuộc như TypeScript, Python, Java và .NET."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS CloudFormation"]'::jsonb, NOW())
