INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-120', 'practice_283', 'Một công ty có khối lượng công việc đòi hỏi phải thu thập, phân tích và lưu trữ dữ liệu tại cơ sở. Công ty muốn mở rộng việc sử dụng các dịch vụ AWS để chạy tại chỗ với quyền truy cập vào mạng công ty và VPC của công ty. Dịch vụ AWS nào đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Hạ tầng mạng & Phân phối nội dung (VPC & Networking)', 'AWS Outposts là dịch vụ AWS đáp ứng yêu cầu chạy dịch vụ AWS tại cơ sở với quyền truy cập vào mạng công ty và VPC của công ty. AWS Outposts là dịch vụ được quản lý toàn phần giúp mở rộng cơ sở hạ tầng AWS, dịch vụ AWS, API và công cụ tới hầu hết mọi trung tâm dữ liệu, không gian dùng chung hoặc cơ sở tại chỗ để có trải nghiệm kết hợp thực sự nhất quán. AWS Outposts lý tưởng cho khối lượng công việc yêu cầu truy cập có độ trễ thấp vào hệ thống tại chỗ, xử lý dữ liệu cục bộ hoặc lưu trữ dữ liệu cục bộ2.', '[{"label": "A", "text_vi": "Tiền đồn AWS", "is_correct": true, "analysis_vi": "Đúng. Tiền đồn AWS là đáp án chính xác. AWS Outposts là dịch vụ AWS đáp ứng yêu cầu chạy dịch vụ AWS tại cơ sở với quyền truy cập vào mạng công ty và VPC của công ty."}, {"label": "B", "text_vi": "AWS Storage Gateway", "is_correct": false, "analysis_vi": "Sai. AWS Storage Gateway: AWS Storage Gateway kết nối môi trường tại chỗ với lưu trữ đám mây AWS, cung cấp quyền truy cập liền mạch vào S3 và EBS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Kết nối trực tiếp AWS", "is_correct": false, "analysis_vi": "Sai. Kết nối trực tiếp AWS: AWS Direct Connect thiết lập kết nối mạng chuyên dụng riêng biệt từ hạ tầng on-premises tới AWS, bỏ qua mạng Internet công cộng để có băng thông ổn định. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Quả cầu tuyết AWS", "is_correct": false, "analysis_vi": "Sai. Quả cầu tuyết AWS: AWS Snowball là thiết bị lưu trữ vật lý an toàn được vận chuyển tận nơi để di chuyển dữ liệu quy mô terabyte đến petabyte vào hoặc ra khỏi AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon VPC", "AWS Direct Connect", "AWS Storage Gateway", "AWS Snowball"]'::jsonb, NOW())
