INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-121', 'practice_283', 'Một công ty muốn tích hợp xử lý ngôn ngữ tự nhiên (NLP) vào bảng điều khiển thông minh kinh doanh (Bl). Công ty muốn đặt câu hỏi và nhận câu trả lời bằng hình ảnh trực quan phù hợp. Dịch vụ hoặc công cụ AWS nào sẽ đáp ứng những yêu cầu này?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Amazon QuickSight Q là tính năng truy vấn ngôn ngữ tự nhiên cho phép người dùng đặt câu hỏi về dữ liệu của họ và nhận câu trả lời dưới dạng trực quan hóa có liên quan1. Amazon Macie là dịch vụ bảo mật dữ liệu và quyền riêng tư dữ liệu sử dụng công nghệ máy học và khớp mẫu để khám phá và bảo vệ dữ liệu nhạy cảm trong AWS2. Amazon Rekognition là dịch vụ thị giác máy tính có thể phân tích hình ảnh và video về khuôn mặt, vật thể, cảnh, văn bản, v.v.3. Amazon Lex là dịch vụ xây dựng giao diện đàm thoại bằng giọng nói và văn bản4. Các bãi chứa AWS-Certified-Cloud-Practitioner hợp lệ được EduDump.com chia sẻ để giúp vượt qua kỳ thi dành cho người thực hành trên nền tảng đám mây được chứng nhận AWS! EduDump.com hiện cung cấp các kết xuất bài thi AWS- Certified-Cloud-Practitioner mới nhất, các câu hỏi thi EduDump.com AWS-Certified-Cloud-Practitioner đã được cập nhật và các câu trả lời đã được sửa. Hãy tải các kết xuất bài thi EduDump.com AWS-Certified-Cloud-Practitioner mới nhất với Test Engine tại đây: https://www.edudump.com/exams/Amazon/AWS-Certified-Cloud-Practitioner/premium/ ( 600 lượt hỏi đáp, GIẢM GIÁ 35% Mã giảm giá đặc biệt: freecram )', '[{"label": "A", "text_vi": "Amazon Macie", "is_correct": false, "analysis_vi": "Sai. Amazon Macie: Amazon Macie sử dụng máy học và đối sánh mẫu để tự động phát hiện, phân loại và bảo vệ dữ liệu nhạy cảm (như PII, số thẻ tín dụng) trên Amazon S3. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Nhận thức lại Amazon", "is_correct": false, "analysis_vi": "Sai. Nhận thức lại Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Amazon QuickSight Q", "is_correct": true, "analysis_vi": "Đúng. Amazon QuickSight Q là đáp án chính xác. Amazon QuickSight Q là tính năng truy vấn ngôn ngữ tự nhiên cho phép người dùng đặt câu hỏi về dữ liệu của họ và nhận câu trả lời dưới dạng trực quan hóa có liên quan1."}, {"label": "D", "text_vi": "Amazon Lex", "is_correct": false, "analysis_vi": "Sai. Amazon Lex không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon RDS", "Amazon Macie"]'::jsonb, NOW())
