INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-122', 'practice_283', 'Dịch vụ hoặc công cụ AWS nào có thể được sử dụng để hợp nhất các khoản thanh toán cho một công ty có nhiều tài khoản AWS?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS Organizations là dịch vụ quản lý tài khoản cho phép bạn hợp nhất nhiều tài khoản AWS vào một tổ chức do bạn tạo và quản lý tập trung. AWS Organizations bao gồm khả năng quản lý tài khoản và thanh toán tổng hợp cho phép bạn đáp ứng tốt hơn các nhu cầu về ngân sách, bảo mật và tuân thủ của doanh nghiệp bạn1.', '[{"label": "A", "text_vi": "Báo cáo chi phí và mức sử dụng AWS", "is_correct": false, "analysis_vi": "Sai. Báo cáo chi phí và mức sử dụng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "AWS Organizations", "is_correct": true, "analysis_vi": "Đúng. AWS Organizations là đáp án chính xác. AWS Organizations là dịch vụ quản lý tài khoản cho phép bạn hợp nhất nhiều tài khoản AWS vào một tổ chức do bạn tạo và quản lý tập trung."}, {"label": "C", "text_vi": "AWS Cost Explorer", "is_correct": false, "analysis_vi": "Sai. AWS Cost Explorer: AWS Cost Explorer cung cấp giao diện trực quan để phân tích, hiểu rõ chi phí lịch sử và dự báo chi tiêu AWS trong tương lai lên đến 12 tháng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Ngân sách AWS", "is_correct": false, "analysis_vi": "Sai. Ngân sách AWS: AWS Budgets cho phép thiết lập ngưỡng ngân sách tùy chỉnh và gửi thông báo hoặc kích hoạt hành động tự động khi chi phí dự kiến vượt ngưỡng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Cost Explorer", "AWS Budgets", "AWS Organizations"]'::jsonb, NOW())
