INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-123', 'practice_283', 'Một công ty có số lượng lớn phiên bản Linux Amazon EC2 trên một số Availability Zone (AZ) trong AWS Region. Các ứng dụng chạy trên phiên bản EC2 cần có quyền truy cập vào một nhóm tệp chung. Công ty nên sử dụng dịch vụ hoặc thiết bị AWS nào để đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Amazon Elastic File System (Amazon EFS) là dịch vụ cung cấp hệ thống tệp linh hoạt và có thể mở rộng cho khối lượng công việc dựa trên Linux. Nó có thể được gắn trên nhiều phiên bản Amazon EC2 trên các Availability Zone (AZ) khác nhau trong một khu vực, cho phép các ứng dụng truy cập vào một tập hợp tệp chung1. AWS Backup là dịch vụ cung cấp cách sao lưu dữ liệu tập trung và tự động trên các dịch vụ AWS. Amazon Elastic Block Store (Amazon EBS) là dịch vụ cung cấp khối lượng lưu trữ khối liên tục cho các phiên bản Amazon EC2. AWS Snowball Edge Storage Optimized là thiết bị cung cấp giải pháp điện toán biên và truyền tải dữ liệu ở quy mô petabyte.', '[{"label": "A", "text_vi": "Sao lưu AWS", "is_correct": false, "analysis_vi": "Sai. Sao lưu AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Hệ thống tệp đàn hồi của Amazon (Amazon EFS)", "is_correct": true, "analysis_vi": "Đúng. Hệ thống tệp đàn hồi của Amazon (Amazon EFS) là đáp án chính xác. Amazon Elastic File System (Amazon EFS) là dịch vụ cung cấp hệ thống tệp linh hoạt và có thể mở rộng cho khối lượng công việc dựa trên Linux."}, {"label": "C", "text_vi": "Cửa hàng khối đàn hồi Amazon (Amazon EBS)", "is_correct": false, "analysis_vi": "Sai. Cửa hàng khối đàn hồi Amazon (Amazon EBS): Amazon EBS cung cấp các khối lưu trữ cấp block gắn trực tiếp vào phiên bản EC2 với độ trễ thấp và tính bền vững cao trong một Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Tối ưu hóa bộ nhớ AWS Snowball Edge", "is_correct": false, "analysis_vi": "Sai. Tối ưu hóa bộ nhớ AWS Snowball Edge: AWS Snowball là thiết bị lưu trữ vật lý an toàn được vận chuyển tận nơi để di chuyển dữ liệu quy mô terabyte đến petabyte vào hoặc ra khỏi AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS Snowball"]'::jsonb, NOW())
