INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-124', 'practice_283', 'Một công ty đang lưu trữ dữ liệu nhạy cảm của khách hàng trong bộ chứa Amazon S3. Công ty muốn bảo vệ dữ liệu khỏi việc vô tình xóa hoặc ghi đè. Công ty nên sử dụng tính năng nào của S3 để đáp ứng những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ lưu trữ Amazon S3 & Vòng đời dữ liệu', 'Lập phiên bản S3 là một tính năng cho phép bạn giữ nhiều phiên bản của một đối tượng trong cùng một nhóm. Bạn có thể sử dụng Lập phiên bản S3 để bảo vệ dữ liệu của mình khỏi việc vô tình xóa hoặc ghi đè bằng cách bật dữ liệu đó trên một nhóm hoặc một đối tượng cụ thể. Phiên bản S3 cũng cho phép bạn khôi phục các phiên bản trước của một đối tượng nếu cần. Quy tắc Vòng đời S3 được sử dụng để tự động hóa quá trình chuyển đổi đối tượng giữa các lớp lưu trữ hoặc hết hạn đối tượng sau một khoảng thời gian nhất định. Chính sách vùng lưu trữ S3 được sử dụng để kiểm soát quyền truy cập vào các đối tượng trong vùng lưu trữ. Mã hóa phía máy chủ S3 được sử dụng để mã hóa dữ liệu ở phần còn lại trong S3.', '[{"label": "A", "text_vi": "Quy tắc vòng đời S3", "is_correct": false, "analysis_vi": "Sai. Quy tắc vòng đời S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Phiên bản S3", "is_correct": true, "analysis_vi": "Đúng. Phiên bản S3 là đáp án chính xác. Lập phiên bản S3 là một tính năng cho phép bạn giữ nhiều phiên bản của một đối tượng trong cùng một nhóm."}, {"label": "C", "text_vi": "Chính sách vùng lưu trữ S3", "is_correct": false, "analysis_vi": "Sai. Chính sách vùng lưu trữ S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Mã hóa phía máy chủ S3", "is_correct": false, "analysis_vi": "Sai. Mã hóa phía máy chủ S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3"]'::jsonb, NOW())
