INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-125', 'practice_283', 'Trách nhiệm nào sau đây của khách hàng theo mô hình trách nhiệm chung của AWS? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Mô hình trách nhiệm chung của AWS mô tả cách AWS và khách hàng chia sẻ trách nhiệm về tính bảo mật và tuân thủ của môi trường AWS. AWS chịu trách nhiệm về bảo mật của đám mây, bao gồm bảo mật vật lý của các cơ sở AWS, cơ sở hạ tầng, phần cứng, phần mềm và mạng chạy các dịch vụ AWS. Khách hàng chịu trách nhiệm về bảo mật trên đám mây, bao gồm cấu hình Security Group, mã hóa dữ liệu khách hàng trên AWS, quản lý cơ sở hạ tầng AWS Lambda và quản lý thông lượng mạng của từng AWS Region.', '[{"label": "A", "text_vi": "Bảo mật vật lý của cơ sở AWS", "is_correct": false, "analysis_vi": "Sai. Bảo mật vật lý của cơ sở AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Cấu hình Security Group", "is_correct": true, "analysis_vi": "Đúng. Cấu hình Security Group là đáp án chính xác. Mô hình trách nhiệm chung của AWS mô tả cách AWS và khách hàng chia sẻ trách nhiệm về tính bảo mật và tuân thủ của môi trường AWS."}, {"label": "C", "text_vi": "Mã hóa dữ liệu khách hàng trên AWS", "is_correct": true, "analysis_vi": "Đúng. Mã hóa dữ liệu khách hàng trên AWS là đáp án chính xác. Mô hình trách nhiệm chung của AWS mô tả cách AWS và khách hàng chia sẻ trách nhiệm về tính bảo mật và tuân thủ của môi trường AWS."}, {"label": "D", "text_vi": "Quản lý cơ sở hạ tầng AWS Lambda", "is_correct": false, "analysis_vi": "Sai. Quản lý cơ sở hạ tầng AWS Lambda: AWS Lambda là dịch vụ điện toán không máy chủ (Serverless), tự động chạy mã phản hồi sự kiện và tính phí chính xác theo mili-giây thực thi, không cần quản lý máy chủ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "E", "text_vi": "Quản lý thông lượng mạng của từng AWS Region", "is_correct": false, "analysis_vi": "Sai. Quản lý thông lượng mạng của từng AWS Region không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["AWS Lambda"]'::jsonb, NOW())
