INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-126', 'practice_283', 'Một công ty muốn có hướng dẫn để tối ưu hóa chi phí và hiệu suất của môi trường AWS hiện tại của mình. Công ty nên sử dụng dịch vụ hoặc công cụ AWS nào để xác định các khu vực cần tối ưu hóa?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'AWS Trusted Advisor là dịch vụ hoặc công cụ AWS mà công ty nên sử dụng để xác định các lĩnh vực cần tối ưu hóa. Theo Hướng dẫn sử dụng AWS Trusted Advisor, "AWS Trusted Advisor là một công cụ trực tuyến cung cấp cho bạn hướng dẫn theo thời gian thực để giúp bạn cung cấp tài nguyên theo các biện pháp thực hành tốt nhất của AWS. Kiểm tra AWS Trusted Advisor giúp tối ưu hóa cơ sở hạ tầng AWS của bạn, tăng tính bảo mật và hiệu suất, giảm tổng chi phí và giám sát giới hạn dịch vụ." Amazon QuickSight, AWS Organizations và AWS Budgets không được thiết kế để đưa ra đề xuất tối ưu hóa cho môi trường AWS hiện tại.', '[{"label": "A", "text_vi": "Amazon QuickSight", "is_correct": false, "analysis_vi": "Sai. Kiểm tra AWS Trusted Advisor giúp tối ưu hóa cơ sở hạ tầng AWS của bạn, tăng tính bảo mật và hiệu suất, giảm tổng chi phí và giám sát giới hạn dịch vụ.\" Amazon QuickSight, AWS Organizations và AWS Budgets không được thiết kế để đưa ra đề xuất tối ưu hóa cho môi trường AWS hiện tại.."}, {"label": "B", "text_vi": "AWS Trusted Advisor", "is_correct": true, "analysis_vi": "Đúng. AWS Trusted Advisor là đáp án chính xác. AWS Trusted Advisor là dịch vụ hoặc công cụ AWS mà công ty nên sử dụng để xác định các lĩnh vực cần tối ưu hóa."}, {"label": "C", "text_vi": "AWS Organizations", "is_correct": false, "analysis_vi": "Sai. Kiểm tra AWS Trusted Advisor giúp tối ưu hóa cơ sở hạ tầng AWS của bạn, tăng tính bảo mật và hiệu suất, giảm tổng chi phí và giám sát giới hạn dịch vụ.\" Amazon QuickSight, AWS Organizations và AWS Budgets không được thiết kế để đưa ra đề xuất tối ưu hóa cho môi trường AWS hiện tại.."}, {"label": "D", "text_vi": "Ngân sách AWS", "is_correct": false, "analysis_vi": "Sai. Kiểm tra AWS Trusted Advisor giúp tối ưu hóa cơ sở hạ tầng AWS của bạn, tăng tính bảo mật và hiệu suất, giảm tổng chi phí và giám sát giới hạn dịch vụ.\" Amazon QuickSight, AWS Organizations và AWS Budgets không được thiết kế để đưa ra đề xuất tối ưu hóa cho môi trường AWS hiện tại.."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["AWS Trusted Advisor", "AWS Budgets", "AWS Organizations"]'::jsonb, NOW())
