INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-127', 'practice_283', 'Một công ty bán lẻ đang xây dựng một ứng dụng di động mới. Công ty đang đánh giá xem nên xây dựng ứng dụng tại trung tâm dữ liệu tại chỗ hay trên Đám mây AWS. mô hình trách nhiệm?', 'Domain 3: Cloud Technology and Services', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Dịch vụ thư mục AWS dành cho Microsoft Active Directory là dịch vụ AWS cung cấp Microsoft Active Directory được quản lý trên Đám mây AWS. Nó cho phép người dùng sử dụng người dùng, nhóm và chính sách Active Directory hiện có của họ để truy cập các tài nguyên AWS, chẳng hạn như phiên bản Amazon EC2, bộ chứa Amazon S3 và Đăng nhập một lần AWS. Nó cũng tích hợp với các ứng dụng và dịch vụ khác của Microsoft, chẳng hạn như Microsoft SQL Server, Microsoft Office 365 và Microsoft SharePoint', '[{"label": "A", "text_vi": "Amazon FSx dành cho Máy chủ tệp Windows", "is_correct": false, "analysis_vi": "Sai. Amazon FSx dành cho Máy chủ tệp Windows không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Máy tính để bàn Windows ảo Amazon Workspaces", "is_correct": false, "analysis_vi": "Sai. Máy tính để bàn Windows ảo Amazon Workspaces không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Dịch vụ thư mục AWS dành cho Microsoft Active Directory", "is_correct": true, "analysis_vi": "Đúng. Dịch vụ thư mục AWS dành cho Microsoft Active Directory là đáp án chính xác. Dịch vụ thư mục AWS dành cho Microsoft Active Directory là dịch vụ AWS cung cấp Microsoft Active Directory được quản lý trên Đám mây AWS."}, {"label": "D", "text_vi": "Amazon RDS cho máy chủ Microsoft SQL", "is_correct": false, "analysis_vi": "Sai. Amazon RDS cho máy chủ Microsoft SQL: Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon RDS"]'::jsonb, NOW())
