INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-128', 'practice_283', 'Dịch vụ AWS nào luôn được cung cấp miễn phí?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'AWS Identity and Access Management (IAM) là dịch vụ web giúp bạn kiểm soát quyền truy cập vào tài nguyên AWS một cách an toàn. Bạn có thể sử dụng IAM để tạo và quản lý người dùng và nhóm AWS, đồng thời sử dụng các quyền để cho phép và từ chối quyền truy cập của họ vào tài nguyên AWS. IAM luôn được cung cấp miễn phí12.', '[{"label": "A", "text_vi": "Amazon S3", "is_correct": false, "analysis_vi": "Sai. Amazon S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Quản lý quyền truy cập và nhận dạng AWS (IAM)", "is_correct": true, "analysis_vi": "Đúng. Quản lý quyền truy cập và nhận dạng AWS (IAM) là đáp án chính xác. AWS Identity and Access Management (IAM) là dịch vụ web giúp bạn kiểm soát quyền truy cập vào tài nguyên AWS một cách an toàn."}, {"label": "C", "text_vi": "Cân bằng tải đàn hồi", "is_correct": false, "analysis_vi": "Sai. Cân bằng tải đàn hồi không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "AWS WAF", "is_correct": false, "analysis_vi": "Sai. AWS WAF: AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon S3", "AWS WAF", "AWS IAM"]'::jsonb, NOW())
