INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-129', 'practice_283', 'Một công ty có một môi trường bao gồm các phiên bản Amazon EC2, Amazon Lightsail và các máy chủ tại chỗ. Công ty muốn tự động hóa các bản cập nhật bảo mật cho hệ điều hành và ứng dụng của mình. Giải pháp nào sẽ đáp ứng những yêu cầu này với nỗ lực vận hành ÍT NHẤT?', 'Domain 2: Security and Compliance', 'Dịch vụ điện toán đám mây Amazon EC2', 'AWS Systems Manager Patch Manager là khả năng cho phép người dùng tự động hóa các bản cập nhật bảo mật cho hệ điều hành và ứng dụng của họ. Nó cho phép người dùng quét các phiên bản của họ để tìm các bản vá bị thiếu, xác định đường cơ sở của bản vá, lên lịch các giai đoạn vá lỗi và giám sát việc tuân thủ bản vá. Nó hỗ trợ các phiên bản Amazon EC2, phiên bản Amazon Lightsail và máy chủ tại chỗ. AWS Shield là dịch vụ cung cấp khả năng bảo vệ chống lại các cuộc tấn công từ chối dịch vụ phân tán (DDoS) đối với các tài nguyên và dịch vụ AWS. Nó không tự động cập nhật bảo mật cho hệ điều hành và ứng dụng. Kết nối với từng máy chủ bằng cách sử dụng kết nối máy tính từ xa và chạy tập lệnh cập nhật là giải pháp thủ công và tốn thời gian, đòi hỏi nhiều nỗ lực vận hành. Đây không phải là phương pháp hay nhất được khuyến nghị để tự động hóa các bản cập nhật bảo mật cho hệ điều hành và ứng dụng. Amazon GuardDuty là dịch vụ cung cấp khả năng phát hiện mối đe dọa thông minh và giám sát liên tục đối với các tài khoản và tài nguyên AWS. Nó không tự động cập nhật bảo mật cho hệ điều hành và ứng dụng.', '[{"label": "A", "text_vi": "Sử dụng AWS Shield để xác định và quản lý các sự kiện bảo mật.", "is_correct": false, "analysis_vi": "Sai. Sử dụng AWS Shield để xác định và quản lý các sự kiện bảo mật.: AWS Shield là dịch vụ phòng chống tấn công từ chối dịch vụ phân tán (DDoS), bản Standard miễn phí tích hợp sẵn và bản Advanced hỗ trợ phản ứng 24/7 từ đội SRT. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Kết nối với từng máy chủ bằng cách sử dụng kết nối máy tính để bàn từ xa. Chạy một tập lệnh cập nhật.", "is_correct": false, "analysis_vi": "Sai. Kết nối với từng máy chủ bằng cách sử dụng kết nối máy tính để bàn từ xa. Chạy một tập lệnh cập nhật. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Sử dụng chức năng Trình quản lý bản vá của Trình quản lý hệ thống AWS.", "is_correct": true, "analysis_vi": "Đúng. Sử dụng chức năng Trình quản lý bản vá của Trình quản lý hệ thống AWS. là đáp án chính xác. AWS Systems Manager Patch Manager là khả năng cho phép người dùng tự động hóa các bản cập nhật bảo mật cho hệ điều hành và ứng dụng của họ."}, {"label": "D", "text_vi": "Lên lịch để Amazon GuardDuty chạy hàng đêm.", "is_correct": false, "analysis_vi": "Sai. Lên lịch để Amazon GuardDuty chạy hàng đêm.: Amazon GuardDuty là dịch vụ phát hiện mối đe dọa thông minh sử dụng máy học để liên tục phân tích VPC Flow Logs, CloudTrail Logs và DNS Logs. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["Amazon EC2", "AWS Shield", "Amazon GuardDuty", "AWS Secrets Manager", "AWS Direct Connect"]'::jsonb, NOW())
