INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-130', 'practice_283', 'Lợi ích của điện toán serverless AWS là gì?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Điện toán serverless AWS là cách xây dựng và chạy ứng dụng mà không cần quan tâm đến máy chủ. AWS quản lý cơ sở hạ tầng cho bạn nên bạn không phải cung cấp, thay đổi quy mô, vá lỗi hoặc giám sát máy chủ. Bạn chỉ trả tiền cho thời gian tính toán mà bạn sử dụng và có thể tập trung vào logic ứng dụng của mình thay vì quản lý máy chủ12.', '[{"label": "A", "text_vi": "Không cần triển khai và quản lý ứng dụng", "is_correct": false, "analysis_vi": "Sai. Điện toán serverless AWS là cách xây dựng và chạy ứng dụng mà không cần quan tâm đến máy chủ."}, {"label": "B", "text_vi": "Bảo mật ứng dụng sẽ được quản lý hoàn toàn bởi AWS", "is_correct": false, "analysis_vi": "Sai. Điện toán serverless AWS là cách xây dựng và chạy ứng dụng mà không cần quan tâm đến máy chủ."}, {"label": "C", "text_vi": "Không cần giám sát và ghi nhật ký", "is_correct": false, "analysis_vi": "Sai. AWS quản lý cơ sở hạ tầng cho bạn nên bạn không phải cung cấp, thay đổi quy mô, vá lỗi hoặc giám sát máy chủ."}, {"label": "D", "text_vi": "Việc quản lý cơ sở hạ tầng được chuyển sang AWS", "is_correct": true, "analysis_vi": "Đúng. Việc quản lý cơ sở hạ tầng được chuyển sang AWS là đáp án chính xác. AWS quản lý cơ sở hạ tầng cho bạn nên bạn không phải cung cấp, thay đổi quy mô, vá lỗi hoặc giám sát máy chủ."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
