INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-131', 'practice_283', 'Người dùng có khối lượng công việc ở trạng thái sẽ chạy trên Amazon EC2 trong 3 năm tới. Mô hình định giá hiệu quả nhất về mặt chi phí cho khối lượng công việc này là gì?', 'Domain 4: Billing, Pricing and Support', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Phiên bản dự trữ là mô hình định giá cung cấp mức giảm giá đáng kể khi sử dụng Amazon EC2 so với Phiên bản theo yêu cầu. Phiên bản dự trữ phù hợp với khối lượng công việc có trạng thái có mô hình sử dụng nhất quán và có thể dự đoán được trong thời gian dài. Bằng cách cam kết thời hạn một năm hoặc ba năm, khách hàng có thể giảm tổng chi phí sở hữu và tối ưu hóa chi tiêu trên đám mây của mình. Phiên bản dự trữ cũng cung cấp tính năng dự trữ công suất, đảm bảo rằng khách hàng có quyền truy cập vào các phiên bản EC2 mà họ cần khi cần.', '[{"label": "A", "text_vi": "Phiên bản theo yêu cầu", "is_correct": true, "analysis_vi": "Đúng. Phiên bản theo yêu cầu là đáp án chính xác. Phiên bản dự trữ là mô hình định giá cung cấp mức giảm giá đáng kể khi sử dụng Amazon EC2 so với Phiên bản theo yêu cầu."}, {"label": "B", "text_vi": "Phiên bản dự trữ", "is_correct": false, "analysis_vi": "Sai. Phiên bản dự trữ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Phiên bản chuyên dụng", "is_correct": false, "analysis_vi": "Sai. Phiên bản chuyên dụng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Phiên bản Spot", "is_correct": false, "analysis_vi": "Sai. Phiên bản Spot không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
