INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-132', 'practice_283', 'Một công ty muốn nhanh chóng triển khai quy trình tích hợp liên tục/phân phối liên tục (CI/CD). Dịch vụ AWS nào sẽ đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS CodeStar là dịch vụ cho phép bạn nhanh chóng phát triển, xây dựng và triển khai ứng dụng trên AWS. Nó cung cấp giao diện người dùng thống nhất để quản lý vòng đời ứng dụng của bạn, bao gồm kho lưu trữ mã, quy trình xây dựng, triển khai và bảng điều khiển dự án. AWS CodeStar cũng tích hợp với các dịch vụ AWS khác, chẳng hạn như AWS CodeCommit, AWS CodeBuild, AWS CodeDeploy và AWS CodePipeline, để tạo quy trình CI/CD hoàn chỉnh cho ứng dụng của bạn12.', '[{"label": "A", "text_vi": "Cấu hình AWS", "is_correct": false, "analysis_vi": "Sai. Cấu hình AWS: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Nhận thức của Amazon", "is_correct": false, "analysis_vi": "Sai. Nhận thức của Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Đồng bộ hóa dữ liệu AWS", "is_correct": false, "analysis_vi": "Sai. Đồng bộ hóa dữ liệu AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Ngôi sao mã AWS", "is_correct": true, "analysis_vi": "Đúng. Ngôi sao mã AWS là đáp án chính xác. AWS CodeStar là dịch vụ cho phép bạn nhanh chóng phát triển, xây dựng và triển khai ứng dụng trên AWS."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
