INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-133', 'practice_283', 'Điều nào sau đây là đặc điểm của người dùng root tài khoản AWS?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Người dùng root của tài khoản AWS là danh tính đăng nhập đầu tiên khả dụng khi tạo tài khoản AWS. Nó có toàn quyền truy cập vào tất cả các dịch vụ và tài nguyên AWS trong tài khoản. Địa chỉ email và mật khẩu của người dùng root chính là thông tin xác thực được sử dụng để đăng nhập vào Bảng điều khiển quản lý AWS4. Người dùng root chỉ nên được sử dụng để thực hiện một số tác vụ quản lý tài khoản và dịch vụ. Đối với các tác vụ hàng ngày, bạn nên sử dụng người dùng hoặc vai trò AWS Identity and Access Management (IAM).', '[{"label": "A", "text_vi": "Người dùng root là người dùng duy nhất có thể được định cấu hình bằng xác thực đa yếu tố (MFA).", "is_correct": false, "analysis_vi": "Sai. Người dùng root là người dùng duy nhất có thể được định cấu hình bằng xác thực đa yếu tố (MFA).: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Người dùng root là người dùng duy nhất có thể truy cập Bảng điều khiển quản lý AWS.", "is_correct": false, "analysis_vi": "Sai. Người dùng root là người dùng duy nhất có thể truy cập Bảng điều khiển quản lý AWS. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Người dùng root là danh tính đăng nhập đầu tiên khả dụng khi tạo tài khoản AWS.", "is_correct": true, "analysis_vi": "Đúng. Người dùng root là danh tính đăng nhập đầu tiên khả dụng khi tạo tài khoản AWS. là đáp án chính xác. Người dùng root của tài khoản AWS là danh tính đăng nhập đầu tiên khả dụng khi tạo tài khoản AWS."}, {"label": "D", "text_vi": "Người dùng root có mật khẩu không thể thay đổi.", "is_correct": false, "analysis_vi": "Sai. Người dùng root có mật khẩu không thể thay đổi. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
