INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-134', 'practice_283', 'Những tính năng AWS nào sẽ đáp ứng những yêu cầu này? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Câu trả lời đúng là C và D vì chính sách nhóm S3 và chính sách người dùng IAM là những tính năng của AWS sẽ đáp ứng được yêu cầu. Chính sách vùng lưu trữ S3 là các chính sách truy cập có thể được đính kèm vào vùng lưu trữ Amazon S3 để cấp hoặc từ chối quyền đối với vùng lưu trữ và các đối tượng trong đó. Chính sách bộ chứa S3 có thể được sử dụng để kiểm soát ai có quyền đọc, ghi hoặc xóa các đối tượng mà công ty lưu trữ trong bộ chứa S3. Chính sách người dùng IAM là các chính sách truy cập có thể được đính kèm với người dùng IAM để cấp hoặc từ chối quyền đối với các tài nguyên và hành động của AWS. Chính sách người dùng IAM có thể được sử dụng để kiểm soát ai có quyền đọc, viết hoặc xóa các đối tượng mà công ty lưu trữ trong bộ chứa S3. Các tùy chọn khác không chính xác vì chúng không phải là tính năng của AWS sẽ đáp ứng yêu cầu. Security Group và ACL mạng là các tính năng AWS hoạt động như tường lửa để kiểm soát lưu lượng vào và ra đến và đi từ các phiên bản và mạng con của Amazon EC2. Các Security Group và ACL mạng không kiểm soát ai có quyền đọc, ghi hoặc xóa các đối tượng mà công ty lưu trữ trong bộ chứa S3. Lập phiên bản vùng lưu trữ S3 là một tính năng của AWS cho phép người dùng giữ nhiều phiên bản của cùng một đối tượng trong cùng một vùng lưu trữ. Lập phiên bản vùng lưu trữ S3 có thể được sử dụng để khôi phục sau khi vô tình ghi đè hoặc xóa các đối tượng, nhưng nó không kiểm soát ai có quyền đọc, ghi hoặc xóa các đối tượng mà công ty lưu trữ trong vùng lưu trữ S3.', '[{"label": "A", "text_vi": "Security Group", "is_correct": false, "analysis_vi": "Sai. Security Group: Security Group là tường lửa ảo ở cấp instance, hoạt động có trạng thái (Stateful) và chỉ cấu hình các quy tắc cho phép (Allow rules). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "ACL mạng", "is_correct": false, "analysis_vi": "Sai. ACL mạng: Network ACL là tường lửa ở cấp subnet, hoạt động không trạng thái (Stateless) và hỗ trợ cả quy tắc cho phép (Allow) lẫn từ chối (Deny). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Chính sách vùng lưu trữ S3", "is_correct": true, "analysis_vi": "Đúng. Chính sách vùng lưu trữ S3 là đáp án chính xác. Câu trả lời đúng là C và D vì chính sách nhóm S3 và chính sách người dùng IAM là những tính năng của AWS sẽ đáp ứng được yêu cầu."}, {"label": "D", "text_vi": "Chính sách người dùng IAM", "is_correct": true, "analysis_vi": "Đúng. Chính sách người dùng IAM là đáp án chính xác. Câu trả lời đúng là C và D vì chính sách nhóm S3 và chính sách người dùng IAM là những tính năng của AWS sẽ đáp ứng được yêu cầu."}, {"label": "E", "text_vi": "Phiên bản nhóm S3", "is_correct": false, "analysis_vi": "Sai. Phiên bản nhóm S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon S3", "AWS IAM"]'::jsonb, NOW())
