INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-135', 'practice_283', 'Một công ty đang vận hành một số nhà máy để sản xuất sản phẩm. Công ty cần khả năng xử lý dữ liệu, lưu trữ dữ liệu và chạy các ứng dụng có sự phụ thuộc lẫn nhau của hệ thống cục bộ yêu cầu độ trễ thấp. Công ty nên sử dụng dịch vụ AWS nào để đáp ứng những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS Outposts là dịch vụ cung cấp cơ sở hạ tầng và dịch vụ AWS được quản lý toàn phần tại cơ sở. Nó cho phép người dùng chạy các ứng dụng yêu cầu độ trễ thấp và xử lý dữ liệu cục bộ, đồng thời kết nối liền mạch với Đám mây AWS để có trải nghiệm kết hợp nhất quán. AWS IoT Greengrass là dịch vụ cung cấp khả năng điện toán, nhắn tin, lưu vào bộ nhớ đệm dữ liệu, đồng bộ hóa và suy luận ML cục bộ cho các thiết bị được kết nối. AWS Lambda là dịch vụ cho phép người dùng chạy mã mà không cần cung cấp hay quản lý máy chủ. AWS Snowball Edge là thiết bị cung cấp giải pháp điện toán biên và truyền dữ liệu ở quy mô petabyte.', '[{"label": "A", "text_vi": "AWS loT Greengrass", "is_correct": false, "analysis_vi": "Sai. AWS loT Greengrass không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "AWS Lambda", "is_correct": false, "analysis_vi": "Sai. AWS Lambda là dịch vụ cho phép người dùng chạy mã mà không cần cung cấp hay quản lý máy chủ."}, {"label": "C", "text_vi": "Tiền đồn AWS", "is_correct": true, "analysis_vi": "Đúng. Tiền đồn AWS là đáp án chính xác. AWS Outposts là dịch vụ cung cấp cơ sở hạ tầng và dịch vụ AWS được quản lý toàn phần tại cơ sở."}, {"label": "D", "text_vi": "AWS Snowball Edge", "is_correct": false, "analysis_vi": "Sai. AWS Snowball Edge: AWS Snowball là thiết bị lưu trữ vật lý an toàn được vận chuyển tận nơi để di chuyển dữ liệu quy mô terabyte đến petabyte vào hoặc ra khỏi AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["AWS Lambda", "AWS Snowball"]'::jsonb, NOW())
