INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-136', 'practice_283', 'Dịch vụ AWS nào cung cấp quyền truy cập dòng lệnh trực tiếp vào các công cụ và tài nguyên AWS (trình duyệt web bị rách?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS CloudShell là dịch vụ cung cấp quyền truy cập dòng lệnh vào các công cụ và tài nguyên AWS trực tiếp từ trình duyệt web. AWS CloudShell là một shell dựa trên trình duyệt giúp bạn dễ dàng quản lý, khám phá và tương tác một cách an toàn với các tài nguyên AWS của mình. Nó được xác thực trước bằng thông tin đăng nhập bảng điều khiển của bạn và các công cụ quản trị và phát triển phổ biến được cài đặt sẵn, do đó không cần cài đặt hoặc cấu hình cục bộ. Bạn có thể mở AWS CloudShell từ Bảng điều khiển quản lý AWS chỉ bằng một cú nhấp chuột và bắt đầu chạy các lệnh và tập lệnh bằng Giao diện dòng lệnh AWS (AWS CLI), Git hoặc SDK. AWS CloudShell cũng cung cấp các thư mục gốc ổn định với 1 GB dung lượng lưu trữ cho mỗi AWS Region12. Các dịch vụ khác không cung cấp quyền truy cập dòng lệnh vào các công cụ và tài nguyên AWS trực tiếp từ trình duyệt web. AWS CloudHSM là dịch vụ giúp bạn đáp ứng các yêu cầu tuân thủ quy định, hợp đồng và công ty về bảo mật dữ liệu bằng cách sử dụng các thiết bị Mô-đun bảo mật phần cứng (HSM) chuyên dụng trong AWS Cloud3. Amazon WorkSpaces là dịch vụ cung cấp giải pháp Máy tính để bàn dưới dạng dịch vụ (DaaS) an toàn, được quản lý toàn phần chạy trên AWS4. AWS Cloud Map là dịch vụ giúp các ứng dụng của bạn dễ dàng khám phá và kết nối với nhau bằng tên và thuộc tính logic5.', '[{"label": "A", "text_vi": "AWS CIoudHSM", "is_correct": false, "analysis_vi": "Sai. AWS CIoudHSM không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "AWS CloudShell", "is_correct": true, "analysis_vi": "Đúng. AWS CloudShell là đáp án chính xác. AWS CloudShell là dịch vụ cung cấp quyền truy cập dòng lệnh vào các công cụ và tài nguyên AWS trực tiếp từ trình duyệt web."}, {"label": "C", "text_vi": "Không gian làm việc của Amazon", "is_correct": false, "analysis_vi": "Sai. Không gian làm việc của Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Bản đồ đám mây AWS", "is_correct": false, "analysis_vi": "Sai. Bản đồ đám mây AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
