INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-137', 'practice_283', 'Dịch vụ AWS nào cung cấp cho người dùng khả năng cung cấp kết nối mạng riêng và chuyên dụng từ mạng nội bộ của họ tới AWS?', 'Domain 3: Cloud Technology and Services', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'AWS Direct Connect cung cấp cho người dùng khả năng cung cấp kết nối mạng riêng và chuyên dụng từ mạng nội bộ của họ tới AWS. AWS Direct Connect liên kết mạng nội bộ của người dùng với vị trí AWS Direct Connect qua cáp quang Ethernet tiêu chuẩn. Một đầu cáp được kết nối với bộ định tuyến của người dùng, đầu còn lại với bộ định tuyến AWS Direct Connect. Với kết nối này, người dùng có thể tạo giao diện ảo trực tiếp lên đám mây AWS và Amazon Virtual Private Cloud (Amazon VPC), bỏ qua các nhà cung cấp dịch vụ internet trong đường dẫn mạng2.', '[{"label": "A", "text_vi": "AWS CloudHSM", "is_correct": false, "analysis_vi": "Sai. AWS CloudHSM: AWS CloudHSM cung cấp thiết bị bảo mật phần cứng chuyên dụng (FIPS 140-2 Level 3) do khách hàng độc quyền kiểm soát để quản lý khóa mã hóa. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Kết nối trực tiếp AWS", "is_correct": true, "analysis_vi": "Đúng. Kết nối trực tiếp AWS là đáp án chính xác. AWS Direct Connect cung cấp cho người dùng khả năng cung cấp kết nối mạng riêng và chuyên dụng từ mạng nội bộ của họ tới AWS."}, {"label": "C", "text_vi": "AWS VPN", "is_correct": false, "analysis_vi": "Sai. AWS VPN: AWS Site-to-Site VPN tạo kết nối mạng riêng ảo bảo mật qua đường truyền Internet công cộng bằng giao thức IPsec giữa mạng on-premises và AWS VPC. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Kết nối Amazon", "is_correct": false, "analysis_vi": "Sai. Kết nối Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Direct Connect"]'::jsonb, NOW())
