INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-138', 'practice_283', 'Một công ty muốn di chuyển các ứng dụng của mình sang Đám mây AWS. Công ty có kế hoạch xác định và ưu tiên mọi cơ hội chuyển đổi kinh doanh cũng như đánh giá mức độ sẵn sàng của Đám mây AWS. Công ty nên sử dụng dịch vụ hoặc công cụ AWS nào để đáp ứng các yêu cầu này?', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Khung áp dụng đám mây AWS (AWS CAF) là một tập hợp các biện pháp thực hành, công cụ và hướng dẫn tốt nhất giúp các tổ chức bắt đầu với công nghệ đám mây. AWS CAF giúp các tổ chức xác định và ưu tiên các cơ hội chuyển đổi, đánh giá và cải thiện mức độ sẵn sàng của đám mây cũng như liên tục phát triển lộ trình chuyển đổi của họ. AWS CAF nhóm các khả năng của mình theo sáu khía cạnh: Kinh doanh, Con người, Quản trị, Nền tảng, Bảo mật và Vận hành. Mỗi khía cạnh bao gồm một tập hợp các khả năng mà các bên liên quan về chức năng sở hữu hoặc quản lý trong hành trình chuyển đổi sang đám mây1 Dịch vụ được quản lý AWS (AMS) là dịch vụ vận hành cơ sở hạ tầng AWS thay mặt cho khách hàng, cung cấp Vùng đích AWS an toàn, các tính năng giúp đáp ứng nhiều yêu cầu của chương trình tuân thủ, mô hình vận hành doanh nghiệp đã được chứng minh, tối ưu hóa chi phí liên tục và quản lý cơ sở hạ tầng hàng ngày. AMS không giúp khách hàng xác định và ưu tiên các cơ hội chuyển đổi kinh doanh hay đánh giá mức độ sẵn sàng trên đám mây của họ2 Khung kiến ​​trúc tối ưu AWS là một bộ gồm sáu trụ cột và lăng kính giúp các kiến ​​trúc sư đám mây thiết kế và chạy khối lượng công việc trên đám mây. Nó cung cấp một cách tiếp cận nhất quán để khách hàng và Đối tác AWS đánh giá và triển khai các thiết kế có quy mô phù hợp với nhu cầu của họ. AWS Well- Architected Framework giúp khách hàng hiểu được ưu và nhược điểm của các quyết định họ đưa ra khi xây dựng hệ thống trên AWS, nhưng không giúp họ xác định và ưu tiên các cơ hội chuyển đổi kinh doanh3 AWS Migration Hub là công cụ cho phép khách hàng khám phá, lập kế hoạch và theo dõi các máy chủ và ứng dụng hiện có của họ để di chuyển sang AWS. Nó cung cấp các mẫu hành trình, cộng tác giữa các nhóm, khám phá ứng dụng và máy chủ, đề xuất chiến lược, điều phối và bảng điều khiển đơn giản. Trung tâm di chuyển AWS đơn giản hóa quá trình di chuyển và hiện đại hóa, nhưng không giúp khách hàng xác định và ưu tiên các cơ hội chuyển đổi kinh doanh hoặc đánh giá mức độ sẵn sàng của đám mây4', '[{"label": "A", "text_vi": "Khung áp dụng đám mây AWS (AWS CAF)", "is_correct": true, "analysis_vi": "Đúng. Khung áp dụng đám mây AWS (AWS CAF) là đáp án chính xác. Khung áp dụng đám mây AWS (AWS CAF) là một tập hợp các biện pháp thực hành, công cụ và hướng dẫn tốt nhất giúp các tổ chức bắt đầu với công nghệ đám mây."}, {"label": "B", "text_vi": "Dịch vụ được quản lý AWS (AMS)", "is_correct": false, "analysis_vi": "Sai. Dịch vụ được quản lý AWS (AMS) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Khung kiến trúc tối ưu AWS", "is_correct": false, "analysis_vi": "Sai. Khung kiến trúc tối ưu AWS: Khung AWS Well-Architected bao gồm 6 trụ cột: Vận hành xuất sắc, Bảo mật, Độ tin cậy, Hiệu quả hiệu năng, Tối ưu hóa chi phí và Tính bền vững. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Trung tâm di chuyển AWS", "is_correct": false, "analysis_vi": "Sai. Trung tâm di chuyển AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
