INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-139', 'practice_283', 'Dịch vụ AWS nào có thể chống lại các cuộc tấn công DDoS?', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'AWS Shield Standard là dịch vụ cung cấp khả năng bảo vệ chống lại các cuộc tấn công từ chối dịch vụ phân tán (DDoS) cho tất cả khách hàng AWS mà không phải trả thêm phí. Nó tự động phát hiện và giảm thiểu các cuộc tấn công DDoS mạng và lớp vận chuyển phổ biến và thường xuyên xảy ra nhất nhắm vào các tài nguyên AWS, chẳng hạn như phiên bản Amazon EC2, Elastic Load Balancers, bản phân phối Amazon CloudFront và vùng lưu trữ trên Amazon Route 53. AWS Fire Manager là dịch vụ cho phép người dùng đặt cấu hình và quản lý tập trung các quy tắc tường lửa trên các tài khoản và tài nguyên AWS của họ, chẳng hạn như ACL web AWS WAF, biện pháp bảo vệ AWS Shield Advanced và Security Group Amazon VPC. AWS WAF là tường lửa ứng dụng web giúp bảo vệ các ứng dụng web khỏi các hoạt động khai thác web thông thường, chẳng hạn như chèn SQL, tạo tập lệnh chéo trang và tấn công bot. Amazon Inspector là dịch vụ đánh giá bảo mật tự động giúp cải thiện tính bảo mật và tuân thủ của các ứng dụng được triển khai trên AWS. Nó phân tích hành vi của các ứng dụng và kiểm tra các lỗ hổng, mức độ phơi nhiễm và sai lệch so với các phương pháp hay nhất.', '[{"label": "A", "text_vi": "Trình quản lý tường lửa AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý tường lửa AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Tiêu chuẩn lá chắn AWS", "is_correct": true, "analysis_vi": "Đúng. Tiêu chuẩn lá chắn AWS là đáp án chính xác. AWS Shield Standard là dịch vụ cung cấp khả năng bảo vệ chống lại các cuộc tấn công từ chối dịch vụ phân tán (DDoS) cho tất cả khách hàng AWS mà không phải trả thêm phí."}, {"label": "C", "text_vi": "AWS WAF", "is_correct": false, "analysis_vi": "Sai. AWS WAF: AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon Inspector: Amazon Inspector là dịch vụ quản lý lỗ hổng bảo mật tự động, quét các lỗ hổng phần mềm và phát hiện phơi nhiễm mạng ngoài ý muốn trên EC2, ECR và Lambda. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Shield", "AWS WAF", "Amazon Inspector", "AWS Secrets Manager"]'::jsonb, NOW())
