INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-140', 'practice_283', 'Một công ty đang vận hành và quản lý môi trường Docker của riêng mình trên các phiên bản Amazon EC2. Công ty muốn có một giải pháp thay thế để giúp quản lý quy mô cụm, lập kế hoạch và bảo trì môi trường. Dịch vụ AWS nào đáp ứng các yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'AWS Fargate là công cụ điện toán serverless dành cho các container hoạt động với cả Amazon Elastic Container Service (Amazon ECS) và Amazon Elastic Kubernetes Service (Amazon EKS). AWS Fargate cho phép bạn chạy bộ chứa mà không cần phải quản lý máy chủ hoặc cụm phiên bản Amazon EC2. Với AWS Fargate, bạn chỉ trả tiền cho các tài nguyên điện toán mà bạn sử dụng để chạy các bộ chứa của mình và bạn không cần phải lo lắng về việc mở rộng quy mô, vá lỗi, bảo mật hoặc duy trì cơ sở hạ tầng cơ bản. AWS Fargate đơn giản hóa việc triển khai và quản lý các ứng dụng trong bộ chứa, đồng thời cho phép bạn tập trung vào việc xây dựng và chạy các ứng dụng của mình thay vì quản lý cơ sở hạ tầng.', '[{"label": "A", "text_vi": "AWS Lambda", "is_correct": false, "analysis_vi": "Sai. AWS Lambda: AWS Lambda là dịch vụ điện toán không máy chủ (Serverless), tự động chạy mã phản hồi sự kiện và tính phí chính xác theo mili-giây thực thi, không cần quản lý máy chủ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon RDS", "is_correct": true, "analysis_vi": "Đúng. Amazon RDS là giải pháp đáp ứng yêu cầu. AWS Fargate là công cụ điện toán serverless dành cho các container hoạt động với cả Amazon Elastic Container Service (Amazon ECS) và Amazon Elastic Kubernetes Service (Amazon EKS). Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao."}, {"label": "C", "text_vi": "Cổng xa AWS", "is_correct": false, "analysis_vi": "Sai. Cổng xa AWS: AWS Fargate là công nghệ điện toán serverless cho container (ECS/EKS), giúp chạy container mà không cần quản trị máy chủ EC2 cơ sở. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Amazon Athena", "is_correct": false, "analysis_vi": "Sai. Amazon Athena không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS Lambda", "Amazon RDS"]'::jsonb, NOW())
