INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-141', 'practice_283', 'Một công ty không muốn dựa vào dự báo phức tạp để xác định việc sử dụng tài nguyên máy tính của mình. Thay vào đó, công ty chỉ muốn trả tiền cho những tài nguyên mà nó sử dụng. Công ty cũng cần khả năng tăng hoặc giảm việc sử dụng tài nguyên để đáp ứng yêu cầu kinh doanh. Trụ cột nào của Khung kiến ​​trúc tối ưu AWS phù hợp với những yêu cầu này?', 'Domain 1: Cloud Concepts', 'Khung kiến trúc tối ưu AWS (Well-Architected Framework)', 'Tối ưu hóa chi phí là trụ cột của Khung kiến trúc tối ưu AWS phù hợp với yêu cầu không dựa vào dự báo phức tạp và chỉ trả tiền cho những tài nguyên được sử dụng. Trụ cột tối ưu hóa chi phí tập trung vào khả năng của một hệ thống trong việc mang lại giá trị kinh doanh ở mức giá thấp nhất. Tối ưu hóa chi phí bao gồm việc sử dụng đúng dịch vụ và tài nguyên AWS cho khối lượng công việc, đo lường và giám sát chi phí cũng như mức sử dụng, đồng thời liên tục cải thiện hiệu quả chi phí. Tối ưu hóa chi phí cũng tận dụng các lợi ích của Đám mây AWS, chẳng hạn như mức giá thanh toán theo mức sử dụng, tính linh hoạt và khả năng mở rộng. Để biết thêm thông tin, hãy xem [Trụ cột tối ưu hóa chi phí] và [Tối ưu hóa chi phí].', '[{"label": "A", "text_vi": "Hoạt động xuất sắc", "is_correct": false, "analysis_vi": "Sai. Hoạt động xuất sắc không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Bảo mật", "is_correct": false, "analysis_vi": "Sai. Bảo mật không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Độ tin cậy", "is_correct": false, "analysis_vi": "Sai. Độ tin cậy không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Tối ưu hóa chi phí", "is_correct": true, "analysis_vi": "Đúng. Tối ưu hóa chi phí đáp ứng đầy đủ yêu cầu của đề bài. Tối ưu hóa chi phí là trụ cột của Khung kiến trúc tối ưu AWS phù hợp với yêu cầu không dựa vào dự báo phức tạp và chỉ trả tiền cho những tài nguyên được sử dụng."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
