INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-142', 'practice_283', 'Một công ty muốn di chuyển cơ sở dữ liệu quan hệ tại chỗ của mình sang Đám mây AWS. Công ty muốn sử dụng cơ sở hạ tầng càng gần vị trí địa lý hiện tại càng tốt. Công ty nên sử dụng dịch vụ hoặc tài nguyên AWS nào để chọn khu vực triển khai Amazon RDS của mình?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'AWS Region là dịch vụ hoặc tài nguyên AWS mà công ty nên sử dụng để chọn khu vực triển khai Amazon RDS của mình. AWS Region là các khu vực địa lý riêng biệt nơi AWS tập hợp các trung tâm dữ liệu của mình. Mỗi AWS Region bao gồm nhiều Availability Zone (AZ), biệt lập và tách biệt về mặt vật lý trong một khu vực địa lý. Mỗi AWS Region được thiết kế để tách biệt với các AWS Region khác nhằm đạt được độ ổn định và khả năng chịu lỗi cao nhất có thể. AWS cung cấp phạm vi hoạt động toàn cầu rộng hơn bất kỳ nhà cung cấp đám mây nào khác và để hỗ trợ phạm vi hoạt động toàn cầu của mình cũng như đảm bảo khách hàng được phục vụ trên toàn thế giới, AWS nhanh chóng mở ra các Khu vực mới. AWS duy trì nhiều Khu vực địa lý, bao gồm các Khu vực ở Bắc Mỹ, Nam Mỹ, Châu Âu, Trung Quốc, Châu Á Thái Bình Dương, Nam Phi và Trung Đông. Amazon RDS có sẵn ở một số AWS Region trên toàn thế giới. Để tạo hoặc làm việc với phiên bản Amazon RDS DB trong một AWS Region cụ thể, bạn phải sử dụng điểm cuối dịch vụ khu vực tương ứng. Bạn có thể chọn AWS Region đáp ứng các yêu cầu về độ trễ hoặc pháp lý của mình. Bạn cũng có thể sử dụng nhiều AWS Region để thiết kế giải pháp khắc phục thảm họa hoặc phân phối khối lượng công việc đọc của mình.', '[{"label": "A", "text_vi": "Kết nối Amazon", "is_correct": false, "analysis_vi": "Sai. Kết nối Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Bước sóng AWS", "is_correct": false, "analysis_vi": "Sai. Bước sóng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "AWS Region", "is_correct": true, "analysis_vi": "Đúng. AWS Region là đáp án chính xác. AWS Region là dịch vụ hoặc tài nguyên AWS mà công ty nên sử dụng để chọn khu vực triển khai Amazon RDS của mình."}, {"label": "D", "text_vi": "Kết nối trực tiếp AWS", "is_correct": false, "analysis_vi": "Sai. Kết nối trực tiếp AWS: AWS Direct Connect thiết lập kết nối mạng chuyên dụng riêng biệt từ hạ tầng on-premises tới AWS, bỏ qua mạng Internet công cộng để có băng thông ổn định. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon RDS", "AWS Direct Connect"]'::jsonb, NOW())
