INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-143', 'practice_283', 'Quan điểm nào trong Khung áp dụng đám mây AWS (AWS CAF) bao gồm khả năng cho kiến trúc phân tích và dữ liệu được thiết kế tốt?', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Câu trả lời đúng là D. Nền tảng. Phối cảnh Nền tảng trong Khung áp dụng đám mây AWS (AWS CAF) bao gồm khả năng dành cho kiến ​​trúc dữ liệu và phân tích được thiết kế tốt. Khả năng này giúp bạn thiết kế, triển khai và tối ưu hóa các giải pháp dữ liệu và phân tích trên AWS bằng cách sử dụng các dịch vụ như Amazon S3, Amazon Redshift, Amazon EMR, Amazon Kinesis, Amazon Athena và Amazon QuickSight. Kiến trúc phân tích và dữ liệu được thiết kế tốt cho phép bạn thu thập, lưu trữ, xử lý, phân tích và trực quan hóa dữ liệu từ nhiều nguồn khác nhau, đồng thời rút ra những hiểu biết sâu sắc có thể thúc đẩy các quyết định kinh doanh của bạn12. Khía cạnh Bảo mật không bao gồm khả năng về kiến ​​trúc dữ liệu và phân tích, nhưng nó bao gồm khả năng bảo vệ dữ liệu, giúp bạn bảo mật dữ liệu của mình khi lưu trữ và truyền đi bằng cách sử dụng mã hóa, quản lý khóa, kiểm soát truy cập và kiểm tra13. Phối cảnh Quản trị không bao gồm khả năng về kiến ​​trúc dữ liệu và phân tích, nhưng nó bao gồm khả năng quản trị dữ liệu, giúp bạn quản lý chất lượng, tính sẵn có, khả năng sử dụng, tính toàn vẹn và bảo mật của tài sản dữ liệu của bạn14. Phối cảnh Hoạt động không bao gồm khả năng về kiến ​​trúc dữ liệu và phân tích, nhưng nó bao gồm khả năng vận hành dữ liệu, giúp bạn giám sát, khắc phục sự cố và tối ưu hóa hiệu suất cũng như tính khả dụng của đường ống dữ liệu và khối lượng công việc của bạn1 .', '[{"label": "A", "text_vi": "Bảo mật", "is_correct": false, "analysis_vi": "Sai. Bảo mật không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Quản trị", "is_correct": false, "analysis_vi": "Sai. Khía cạnh Bảo mật không bao gồm khả năng về kiến ​​trúc dữ liệu và phân tích, nhưng nó bao gồm khả năng bảo vệ dữ liệu, giúp bạn bảo mật dữ liệu của mình khi lưu trữ và truyền đi bằng cách sử dụng mã hóa, quản lý khóa, kiểm soát truy cập và kiểm tra13."}, {"label": "C", "text_vi": "Hoạt động", "is_correct": false, "analysis_vi": "Sai. Phối cảnh Hoạt động không bao gồm khả năng về kiến ​​trúc dữ liệu và phân tích, nhưng nó bao gồm khả năng vận hành dữ liệu, giúp bạn giám sát, khắc phục sự cố và tối ưu hóa hiệu suất cũng như tính khả dụng của đường ống dữ liệu và khối lượng công việc của bạn1 .."}, {"label": "D", "text_vi": "Nền tảng", "is_correct": true, "analysis_vi": "Đúng. Nền tảng là đáp án chính xác. Phối cảnh Nền tảng trong Khung áp dụng đám mây AWS (AWS CAF) bao gồm khả năng dành cho kiến ​​trúc dữ liệu và phân tích được thiết kế tốt."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
