INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-144', 'practice_283', 'Amazon Aurora hỗ trợ những công cụ cơ sở dữ liệu nào? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Amazon Aurora là dịch vụ cơ sở dữ liệu quan hệ tương thích với các công cụ MySQL và PostgreSQL. Nó mang lại hiệu suất gấp năm lần so với MySQL và gấp ba lần hiệu suất của PostgreSQL. Nó cũng cung cấp tính sẵn sàng, khả năng mở rộng, bảo mật và độ bền cao1', '[{"label": "A", "text_vi": "Lời tiên tri", "is_correct": false, "analysis_vi": "Sai. Lời tiên tri không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Máy chủ Microsoft SQL", "is_correct": false, "analysis_vi": "Sai. Máy chủ Microsoft SQL không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "MySQL", "is_correct": true, "analysis_vi": "Đúng. MySQL là đáp án chính xác. Amazon Aurora là dịch vụ cơ sở dữ liệu quan hệ tương thích với các công cụ MySQL và PostgreSQL."}, {"label": "D", "text_vi": "PostgreSQL", "is_correct": true, "analysis_vi": "Đúng. PostgreSQL là đáp án chính xác. Amazon Aurora là dịch vụ cơ sở dữ liệu quan hệ tương thích với các công cụ MySQL và PostgreSQL."}, {"label": "E", "text_vi": "MongoDB", "is_correct": false, "analysis_vi": "Sai. MongoDB không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Ghi nhớ các ngưỡng SLA phản hồi: Business (<1h cho production down, 24/7 phone/chat/email), Enterprise (<15m cho mission-critical, có TAM)."]'::jsonb, '[{"term": "support plan", "points_to": "Developer / Business / Enterprise"}]'::jsonb, '["Amazon Aurora"]'::jsonb, NOW())
