INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-145', 'practice_283', 'Công ty có thể sử dụng dịch vụ AWS nào để thiết kế và xây dựng các ứng dụng serverless một cách trực quan?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS Application Composer là dịch vụ cho phép người dùng thiết kế và xây dựng các ứng dụng serverless một cách trực quan. Người dùng có thể kéo và thả các thành phần, chẳng hạn như hàm AWS Lambda, điểm cuối Amazon API Gateway, bảng Amazon DynamoDB và bộ chứa Amazon S3, để tạo kiến ​​trúc ứng dụng serverless. Người dùng cũng có thể định cấu hình các thuộc tính, quyền và phần phụ thuộc của từng thành phần cũng như triển khai ứng dụng vào tài khoản AWS của họ chỉ bằng vài cú nhấp chuột. AWS Application Composer đơn giản hóa thiết kế và cấu hình của các ứng dụng không có máy chủ, đồng thời giảm nhu cầu viết mã hoặc sử dụng các mẫu AWS CloudFormation.', '[{"label": "A", "text_vi": "AWS Lambda", "is_correct": false, "analysis_vi": "Sai. AWS Lambda: AWS Lambda là dịch vụ điện toán không máy chủ (Serverless), tự động chạy mã phản hồi sự kiện và tính phí chính xác theo mili-giây thực thi, không cần quản lý máy chủ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Lô AWS", "is_correct": false, "analysis_vi": "Sai. Lô AWS: AWS Batch cho phép các nhà phát triển và kỹ sư dễ dàng chạy hàng trăm nghìn công việc xử lý hàng loạt (batch computing) trên AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Trình soạn thảo ứng dụng AWS", "is_correct": true, "analysis_vi": "Đúng. Trình soạn thảo ứng dụng AWS là đáp án chính xác. AWS Application Composer là dịch vụ cho phép người dùng thiết kế và xây dựng các ứng dụng serverless một cách trực quan."}, {"label": "D", "text_vi": "Trình chạy ứng dụng AWS", "is_correct": false, "analysis_vi": "Sai. Trình chạy ứng dụng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Lambda"]'::jsonb, NOW())
