INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-146', 'practice_283', 'Một công ty đang di chuyển các ứng dụng của mình từ tại chỗ sang Đám mây AWS. Công ty muốn đảm bảo rằng các ứng dụng chỉ được cấp các quyền tối thiểu cần thiết để thực hiện tất cả các hoạt động. Dịch vụ AWS nào sẽ đáp ứng những yêu cầu này''?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'AWS Identity and Access Management (IAM) là dịch vụ giúp bạn kiểm soát quyền truy cập vào tài nguyên AWS cho người dùng của mình một cách an toàn. Bạn sử dụng IAM để kiểm soát ai có thể sử dụng tài nguyên AWS của bạn (xác thực) và họ có thể sử dụng tài nguyên nào cũng như theo cách nào (ủy quyền). IAM cũng cho phép bạn tuân theo nguyên tắc đặc quyền tối thiểu, nghĩa là chỉ cấp những quyền cần thiết để thực hiện một nhiệm vụ1.', '[{"label": "A", "text_vi": "Quản lý quyền truy cập và nhận dạng AWS (IAM)", "is_correct": true, "analysis_vi": "Đúng. Quản lý quyền truy cập và nhận dạng AWS (IAM) là đáp án chính xác. AWS Identity and Access Management (IAM) là dịch vụ giúp bạn kiểm soát quyền truy cập vào tài nguyên AWS cho người dùng của mình một cách an toàn."}, {"label": "B", "text_vi": "Amazon CloudWatch", "is_correct": false, "analysis_vi": "Sai. Amazon CloudWatch: Amazon CloudWatch là dịch vụ giám sát và quan sát tài nguyên, thu thập chỉ số (metrics), log và gửi cảnh báo (alarms) theo thời gian thực. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon Macie", "is_correct": false, "analysis_vi": "Sai. Amazon Macie: Amazon Macie sử dụng máy học và đối sánh mẫu để tự động phát hiện, phân loại và bảo vệ dữ liệu nhạy cảm (như PII, số thẻ tín dụng) trên Amazon S3. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Nhiệm vụ bảo vệ của Amazon: Amazon GuardDuty là dịch vụ phát hiện mối đe dọa thông minh sử dụng máy học để liên tục phân tích VPC Flow Logs, CloudTrail Logs và DNS Logs. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon CloudWatch", "Amazon GuardDuty", "Amazon Macie", "AWS IAM"]'::jsonb, NOW())
