INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-147', 'practice_283', 'Dịch vụ cơ sở dữ liệu AWS nào cung cấp khả năng lưu trữ dữ liệu trong bộ nhớ?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Câu trả lời đúng là B vì Amazon ElastiCache là dịch vụ cung cấp dịch vụ lưu trữ dữ liệu trong bộ nhớ. Amazon ElastiCache là một dịch vụ có hiệu suất cao, có thể mở rộng và được quản lý toàn phần, hỗ trợ hai công cụ trong bộ nhớ nguồn mở phổ biến: Redis và Memcached. Amazon ElastiCache cho phép người dùng lưu trữ và truy xuất dữ liệu từ các hệ thống trong bộ nhớ nhanh, độ trễ thấp và thông lượng cao. Người dùng có thể sử dụng Amazon ElastiCache để cải thiện hiệu suất ứng dụng của mình bằng cách lưu vào bộ nhớ đệm dữ liệu được truy cập thường xuyên, giảm tải cơ sở dữ liệu và cho phép xử lý dữ liệu theo thời gian thực. Các tùy chọn khác không chính xác vì chúng không phải là dịch vụ cung cấp lưu trữ dữ liệu trong bộ nhớ. Amazon DynamoDB là dịch vụ cung cấp khả năng lưu trữ dữ liệu tài liệu và khóa-giá trị. Amazon RDS là dịch vụ cung cấp khả năng lưu trữ dữ liệu quan hệ. Amazon Timestream là dịch vụ cung cấp khả năng lưu trữ dữ liệu chuỗi thời gian.', '[{"label": "A", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon DynamoDB: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon ElastiCache", "is_correct": true, "analysis_vi": "Đúng. Amazon ElastiCache là đáp án chính xác. Câu trả lời đúng là B vì Amazon ElastiCache là dịch vụ cung cấp dịch vụ lưu trữ dữ liệu trong bộ nhớ."}, {"label": "C", "text_vi": "Amazon RDS", "is_correct": false, "analysis_vi": "Sai. Amazon RDS: Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Dòng thời gian của Amazon", "is_correct": false, "analysis_vi": "Sai. Dòng thời gian của Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon RDS", "Amazon DynamoDB"]'::jsonb, NOW())
