INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-148', 'practice_283', 'Một công ty bán lẻ đang di chuyển các ứng dụng cơ sở hạ tầng CNTT của mình từ cơ sở sang Đám mây AWS. Công ty sẽ loại bỏ những chi phí nào khi di chuyển này? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Quản lý chi phí & Thanh toán AWS', 'Các chi phí mà công ty sẽ loại bỏ khi di chuyển này là chi phí cấp phép ứng dụng và chi phí phần cứng máy chủ vật lý. Chi phí cấp phép ứng dụng là khoản phí mà công ty phải trả để sử dụng các ứng dụng phần mềm trên các máy chủ tại chỗ của mình. Chi phí phần cứng máy chủ vật lý là chi phí mà công ty phải chịu để mua, bảo trì và nâng cấp máy chủ cũng như các thiết bị liên quan. Bằng cách di chuyển sang Đám mây AWS, công ty có thể tránh được những chi phí này bằng cách sử dụng các dịch vụ và tài nguyên AWS đã được AWS cấp phép và quản lý. Để biết thêm thông tin, hãy xem [Kinh tế đám mây] và [Công cụ tính tổng chi phí sở hữu (TCO) của AWS].', '[{"label": "A", "text_vi": "Chi phí vận hành trung tâm dữ liệu", "is_correct": false, "analysis_vi": "Sai. Chi phí vận hành trung tâm dữ liệu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Chi phí cấp phép ứng dụng", "is_correct": true, "analysis_vi": "Đúng. Chi phí cấp phép ứng dụng là đáp án chính xác. Các chi phí mà công ty sẽ loại bỏ khi di chuyển này là chi phí cấp phép ứng dụng và chi phí phần cứng máy chủ vật lý."}, {"label": "C", "text_vi": "Chi phí cho chiến dịch tiếp thị", "is_correct": false, "analysis_vi": "Sai. Chi phí cho chiến dịch tiếp thị không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Chi phí phần cứng máy chủ vật lý", "is_correct": true, "analysis_vi": "Đúng. Chi phí phần cứng máy chủ vật lý là đáp án chính xác. Các chi phí mà công ty sẽ loại bỏ khi di chuyển này là chi phí cấp phép ứng dụng và chi phí phần cứng máy chủ vật lý."}, {"label": "E", "text_vi": "Chi phí quản lý mạng", "is_correct": false, "analysis_vi": "Sai. Chi phí quản lý mạng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '[]'::jsonb, NOW())
