INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-149', 'practice_283', 'Một công ty đang xem xét việc di chuyển sang Đám mây AWS. Công ty muốn có một dịch vụ hoặc tính năng được quản lý hoàn toàn có thể truyền dữ liệu phát trực tuyến từ nhiều nguồn sang bộ chứa Amazon S3. Công ty nên sử dụng dịch vụ hoặc tính năng nào của AWS để đáp ứng các yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ lưu trữ Amazon S3 & Vòng đời dữ liệu', 'Amazon Kinesis Data Firehose là dịch vụ được quản lý toàn phần, cung cấp dữ liệu truyền theo thời gian thực tới các điểm đến như Amazon S3, Amazon Redshift, Amazon Elasticsearch Service và Splunk. Bạn có thể sử dụng Amazon Kinesis Data Firehose để thu thập, chuyển đổi và tải dữ liệu truyền phát từ nhiều nguồn, chẳng hạn như ứng dụng web, thiết bị di động, cảm biến IoT và mạng xã hội.', '[{"label": "A", "text_vi": "Đồng bộ dữ liệu AWS", "is_correct": false, "analysis_vi": "Sai. Đồng bộ dữ liệu AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Firehose dữ liệu Amazon Kinesis", "is_correct": true, "analysis_vi": "Đúng. Firehose dữ liệu Amazon Kinesis là đáp án chính xác. Amazon Kinesis Data Firehose là dịch vụ được quản lý toàn phần, cung cấp dữ liệu truyền theo thời gian thực tới các điểm đến như Amazon S3, Amazon Redshift, Amazon Elasticsearch Service và Splunk."}, {"label": "C", "text_vi": "S3 Chọn", "is_correct": false, "analysis_vi": "Sai. S3 Chọn: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Nhóm chuyển giao AWS", "is_correct": false, "analysis_vi": "Sai. Nhóm chuyển giao AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3"]'::jsonb, NOW())
