INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-150', 'practice_283', 'Gói Hỗ trợ AWS nào cung cấp cho khách hàng quyền truy cập vào trình quản lý tài khoản kỹ thuật AWS (TAM)?', 'Domain 4: Billing, Pricing and Support', 'Các gói hỗ trợ kỹ thuật AWS Support Plans', 'Câu trả lời đúng là D vì AWS Enterprise Support là gói hỗ trợ cung cấp cho khách hàng quyền truy cập vào trình quản lý tài khoản kỹ thuật (TAM) của AWS. AWS Enterprise Support là gói hỗ trợ cấp cao nhất do AWS cung cấp và cung cấp cho khách hàng trải nghiệm hỗ trợ toàn diện và được cá nhân hóa nhất. AWS TAM là nguồn lực kỹ thuật chuyên dụng làm việc chặt chẽ với khách hàng để hiểu nhu cầu kinh doanh và kỹ thuật của họ, cung cấp hướng dẫn chủ động và điều phối hỗ trợ giữa các nhóm AWS. Các tùy chọn khác không chính xác vì chúng không phải là các gói hỗ trợ cung cấp cho khách hàng quyền truy cập vào AWS TAM. AWS Basic Support là gói hỗ trợ mặc định và miễn phí, cung cấp cho khách hàng quyền truy cập vào tài liệu, diễn đàn và thông tin tài khoản trực tuyến. Hỗ trợ nhà phát triển AWS là gói hỗ trợ trả phí ở mức thấp nhất cung cấp cho khách hàng quyền truy cập vào hỗ trợ kỹ thuật trong giờ làm việc, hướng dẫn chung và đề xuất phương pháp hay nhất. AWS Business Support là cấp độ trung cấp của gói hỗ trợ trả phí, cung cấp cho khách hàng quyền tiếp cận hỗ trợ kỹ thuật 24/7, kiểm tra tình trạng hệ thống, hướng dẫn kiến ​​trúc và quản lý trường hợp.', '[{"label": "A", "text_vi": "Hỗ trợ cơ bản của AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ cơ bản của AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Hỗ trợ nhà phát triển AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ nhà phát triển AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Hỗ trợ kinh doanh của AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ kinh doanh của AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Hỗ trợ doanh nghiệp AWS", "is_correct": true, "analysis_vi": "Đúng. Hỗ trợ doanh nghiệp AWS là đáp án chính xác. Câu trả lời đúng là D vì AWS Enterprise Support là gói hỗ trợ cung cấp cho khách hàng quyền truy cập vào trình quản lý tài khoản kỹ thuật (TAM) của AWS."}]'::jsonb, '["Ghi nhớ các ngưỡng SLA phản hồi: Business (<1h cho production down, 24/7 phone/chat/email), Enterprise (<15m cho mission-critical, có TAM)."]'::jsonb, '[{"term": "support plan", "points_to": "Developer / Business / Enterprise"}]'::jsonb, '["AWS Secrets Manager"]'::jsonb, NOW())
