INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-151', 'practice_283', 'Nhiệm vụ nào chỉ người dùng root tài khoản AWS mới có thể thực hiện?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Người dùng root của tài khoản AWS là địa chỉ email bạn sử dụng để đăng ký AWS. Người dùng root có toàn quyền truy cập vào tất cả các dịch vụ và tài nguyên AWS trong tài khoản. Người dùng root có thể thực hiện các tác vụ mà chỉ người dùng root mới có thể thực hiện, chẳng hạn như thay đổi gói AWS Support, đóng tài khoản và khôi phục quyền của người dùng IAM34 Các bãi chứa AWS-Certified-Cloud-Practitioner hợp lệ được EduDump.com chia sẻ để giúp vượt qua kỳ thi AWS-Certified-Cloud-Practitioner! EduDump.com hiện cung cấp các kết xuất bài thi AWS- Certified-Cloud-Practitioner mới nhất, các câu hỏi thi EduDump.com AWS-Certified-Cloud-Practitioner đã được cập nhật và các câu trả lời đã được sửa. Hãy tải các kết xuất bài thi EduDump.com AWS-Certified-Cloud-Practitioner mới nhất với Test Engine tại đây: https://www.edudump.com/exams/Amazon/AWS-Certified-Cloud-Practitioner/premium/ ( 600 lượt hỏi đáp, GIẢM GIÁ 35% Mã giảm giá đặc biệt: freecram )', '[{"label": "A", "text_vi": "Thay đổi gói Hỗ trợ AWS", "is_correct": true, "analysis_vi": "Đúng. Thay đổi gói Hỗ trợ AWS là đáp án chính xác. Người dùng root có thể thực hiện các tác vụ mà chỉ người dùng root mới có thể thực hiện, chẳng hạn như thay đổi gói AWS Support, đóng tài khoản và khôi phục quyền của người dùng IAM34 Các bãi chứa AWS-Certified-Cloud-Practitioner hợp lệ được EduDump.com chia sẻ để giúp vượt qua kỳ thi AWS-Certified-Cloud-Practitioner! EduDump.com hiện cung cấp các kết xuất bài thi AWS- Certified-Cloud-Practitioner mới nhất, các câu hỏi thi EduDump.com AWS-Certified-Cloud-Practitioner đã được cập nhật và các câu trả lời đã được sửa."}, {"label": "B", "text_vi": "Xóa tài nguyên AWS", "is_correct": false, "analysis_vi": "Sai. Xóa tài nguyên AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Tạo cặp khóa phiên bản Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Tạo cặp khóa phiên bản Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Định cấu hình AWS WAF", "is_correct": false, "analysis_vi": "Sai. Định cấu hình AWS WAF: AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS WAF"]'::jsonb, NOW())
