INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-152', 'practice_283', 'Dịch vụ AWS nào cung cấp khả năng lưu trữ đối tượng có độ bền cao?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ lưu trữ Amazon S3 & Vòng đời dữ liệu', 'Amazon S3 là dịch vụ AWS cung cấp khả năng lưu trữ đối tượng có độ bền cao. Amazon S3 được thiết kế để mang lại độ bền 99,999999999% cho các vật thể trong một năm nhất định. Điều này có nghĩa là bạn có thể lưu trữ dữ liệu của mình với độ tin cậy cao rằng dữ liệu sẽ không bị mất. Amazon S3 cũng cung cấp tính sẵn sàng, khả năng mở rộng, bảo mật và hiệu suất cao cho dữ liệu của bạn. Bạn có thể sử dụng Amazon S3 để lưu trữ và truy xuất bất kỳ lượng dữ liệu nào vào bất kỳ lúc nào, từ bất kỳ đâu trên web5.', '[{"label": "A", "text_vi": "Amazon S3", "is_correct": true, "analysis_vi": "Đúng. Amazon S3 là giải pháp đáp ứng yêu cầu. Amazon S3 là dịch vụ AWS cung cấp khả năng lưu trữ đối tượng có độ bền cao. Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website."}, {"label": "B", "text_vi": "Hệ thống tệp đàn hồi của Amazon (Amazon EFS)", "is_correct": false, "analysis_vi": "Sai. Hệ thống tệp đàn hồi của Amazon (Amazon EFS): Amazon EFS cung cấp hệ thống tệp chia sẻ mạng (NFS) co giãn hoàn toàn tự động, có thể gắn đồng thời vào hàng nghìn phiên bản EC2 trên nhiều AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Cửa hàng khối đàn hồi Amazon (Amazon EBS)", "is_correct": false, "analysis_vi": "Sai. Cửa hàng khối đàn hồi Amazon (Amazon EBS): Amazon EBS cung cấp các khối lưu trữ cấp block gắn trực tiếp vào phiên bản EC2 với độ trễ thấp và tính bền vững cao trong một Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Amazon FSx", "is_correct": false, "analysis_vi": "Sai. Amazon FSx không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3"]'::jsonb, NOW())
