INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-153', 'practice_283', 'Một công ty cần lưu trữ dữ liệu từ công cụ đề xuất trong cơ sở dữ liệu. Dịch vụ AWS nào cung cấp chức năng này với chi phí vận hành ÍT NHẤT?', 'Domain 3: Cloud Technology and Services', 'Quản lý chi phí & Thanh toán AWS', 'Amazon DynamoDB là cơ sở dữ liệu tài liệu và khóa-giá trị mang lại hiệu suất mili giây một chữ số ở mọi quy mô. Đó là cơ sở dữ liệu bền bỉ, đa vùng, đa hoạt động, được quản lý toàn phần với tính năng bảo mật, sao lưu và khôi phục tích hợp cũng như bộ nhớ đệm trong bộ nhớ dành cho các ứng dụng trên quy mô internet. DynamoDB có thể xử lý hơn 10 nghìn tỷ yêu cầu mỗi ngày và có thể hỗ trợ mức cao nhất là hơn 20 triệu yêu cầu mỗi giây. DynamoDB cung cấp ít chi phí hoạt động nhất để lưu trữ dữ liệu từ công cụ đề xuất vì nó không yêu cầu cung cấp, vá lỗi hoặc bảo trì máy chủ3', '[{"label": "A", "text_vi": "Amazon RDS cho PostgreSQL", "is_correct": false, "analysis_vi": "Sai. Amazon RDS cho PostgreSQL: Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon DynamoDB", "is_correct": true, "analysis_vi": "Đúng. Amazon DynamoDB là đáp án chính xác. Amazon DynamoDB là cơ sở dữ liệu tài liệu và khóa-giá trị mang lại hiệu suất mili giây một chữ số ở mọi quy mô."}, {"label": "C", "text_vi": "Sao Hải Vương Amazon", "is_correct": false, "analysis_vi": "Sai. Sao Hải Vương Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Amazon cực quang", "is_correct": false, "analysis_vi": "Sai. Amazon cực quang: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon RDS", "Amazon Aurora", "Amazon DynamoDB"]'::jsonb, NOW())
