INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-154', 'practice_283', 'Những lựa chọn nào là các bên liên quan phổ biến đối với phối cảnh nền tảng Khung áp dụng đám mây AWS (AWS CAF)? (Chọn HAI.)', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Các bên liên quan chung của nền tảng AWS Cloud Adoption Framework (AWS CAF) là các kiến trúc sư và kỹ sư CNTT. AWS CAF là hướng dẫn giúp các tổ chức thiết kế và thực hiện lộ trình nhanh chóng để áp dụng đám mây thành công. AWS CAF tổ chức quy trình áp dụng đám mây thành sáu lĩnh vực trọng tâm, được gọi là quan điểm, đó là kinh doanh, con người, quản trị, nền tảng, bảo mật và vận hành. Mỗi quan điểm được chia thành các khả năng, sau đó lại được chia thành các kỹ năng và trách nhiệm. Quan điểm nền tảng tập trung vào việc cung cấp và quản lý cơ sở hạ tầng và dịch vụ đám mây hỗ trợ các ứng dụng kinh doanh. Các khả năng của phối cảnh nền tảng là thiết kế, triển khai và tối ưu hóa. Các bên liên quan về khía cạnh nền tảng là các kiến ​​trúc sư và kỹ sư CNTT chịu trách nhiệm thiết kế, triển khai và tối ưu hóa nền tảng đám mây. Giám đốc tài chính (CFO), giám đốc thông tin (CIO) và giám đốc dữ liệu (CDO) không phải là các bên liên quan chung đối với quan điểm nền tảng AWS CAF. Các giám đốc tài chính là các bên liên quan chung trong quan điểm kinh doanh AWS CAF, trong đó tập trung vào việc hiện thực hóa giá trị của việc áp dụng đám mây. CIO là các bên liên quan chung trong quan điểm quản trị AWS CAF, trong đó tập trung vào việc điều chỉnh chiến lược và quy trình CNTT với chiến lược và mục tiêu kinh doanh. CDO là các bên liên quan chung trong khía cạnh bảo mật AWS CAF, trong đó tập trung vào việc bảo vệ tài sản thông tin và hệ thống trên đám mây.', '[{"label": "A", "text_vi": "Giám đốc tài chính (CFO)", "is_correct": false, "analysis_vi": "Sai. Giám đốc tài chính (CFO), giám đốc thông tin (CIO) và giám đốc dữ liệu (CDO) không phải là các bên liên quan chung đối với quan điểm nền tảng AWS CAF."}, {"label": "B", "text_vi": "Kiến trúc sư CNTT", "is_correct": true, "analysis_vi": "Đúng. Kiến trúc sư CNTT là đáp án chính xác. Các bên liên quan chung của nền tảng AWS Cloud Adoption Framework (AWS CAF) là các kiến trúc sư và kỹ sư CNTT."}, {"label": "C", "text_vi": "Giám đốc thông tin (CIO)", "is_correct": false, "analysis_vi": "Sai. Giám đốc tài chính (CFO), giám đốc thông tin (CIO) và giám đốc dữ liệu (CDO) không phải là các bên liên quan chung đối với quan điểm nền tảng AWS CAF."}, {"label": "D", "text_vi": "Giám đốc dữ liệu (CDO)", "is_correct": false, "analysis_vi": "Sai. Giám đốc tài chính (CFO), giám đốc thông tin (CIO) và giám đốc dữ liệu (CDO) không phải là các bên liên quan chung đối với quan điểm nền tảng AWS CAF."}, {"label": "E", "text_vi": "Kỹ sư", "is_correct": true, "analysis_vi": "Đúng. Kỹ sư đáp ứng đầy đủ yêu cầu của đề bài. Các bên liên quan chung của nền tảng AWS Cloud Adoption Framework (AWS CAF) là các kiến trúc sư và kỹ sư CNTT."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
