INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-155', 'practice_283', 'Một công ty cần chạy một khối lượng công việc cho một số ứng dụng kết xuất hình ảnh hàng loạt. Việc khối lượng công việc có thời gian chết là có thể chấp nhận được. Mô hình định giá Amazon EC2 nào sẽ tiết kiệm chi phí NHẤT trong tình huống này?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'Phiên bản dùng ngay Amazon EC2 là các phiên bản sử dụng dung lượng EC2 dự phòng được cung cấp với mức giảm giá lên tới 90% so với giá Theo yêu cầu. Bạn có thể sử dụng Phiên bản Spot cho nhiều ứng dụng không trạng thái, có khả năng chịu lỗi hoặc linh hoạt khác nhau, chẳng hạn như dữ liệu lớn, khối lượng công việc trong bộ chứa, điện toán hiệu năng cao (HPC) cũng như khối lượng công việc thử nghiệm & phát triển. Phiên bản Spot lý tưởng cho khối lượng công việc có thể bị gián đoạn, chẳng hạn như các ứng dụng kết xuất hình ảnh hàng loạt1. Phiên bản theo yêu cầu là phiên bản cho phép bạn trả phí cho công suất điện toán theo giờ hoặc giây (tối thiểu 60 giây) mà không cần cam kết dài hạn. Điều này giúp bạn thoát khỏi những chi phí và sự phức tạp trong việc lập kế hoạch, mua và bảo trì phần cứng, đồng thời biến những chi phí cố định thường lớn thành những chi phí biến đổi nhỏ hơn nhiều2. Phiên bản dự trữ là phiên bản cung cấp cho bạn mức giảm giá đáng kể (lên tới 75%) so với giá Phiên bản theo yêu cầu. Đổi lại, bạn chọn một thời hạn và thanh toán trước để dự trữ một lượng công suất tính toán nhất định cho thời hạn đó3. Phiên bản chuyên dụng là các phiên bản chạy trong VPC trên phần cứng dành riêng cho một khách hàng. Phiên bản chuyên dụng của bạn được cách ly về mặt vật lý ở cấp độ phần cứng máy chủ với các phiên bản thuộc các tài khoản AWS khác4.', '[{"label": "A", "text_vi": "Phiên bản theo yêu cầu", "is_correct": false, "analysis_vi": "Sai. Phiên bản theo yêu cầu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Phiên bản dự trữ", "is_correct": false, "analysis_vi": "Sai. Phiên bản dự trữ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Phiên bản chuyên dụng", "is_correct": false, "analysis_vi": "Sai. Phiên bản chuyên dụng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Phiên bản Spot", "is_correct": true, "analysis_vi": "Đúng. Phiên bản Spot là đáp án chính xác. Phiên bản dùng ngay Amazon EC2 là các phiên bản sử dụng dung lượng EC2 dự phòng được cung cấp với mức giảm giá lên tới 90% so với giá Theo yêu cầu."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
