INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-156', 'practice_283', 'Mô hình định giá Amazon EC2 nào có hiệu quả chi phí NHẤT cho khối lượng công việc không bị gián đoạn chạy mỗi năm một lần trong 24 giờ?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'Phiên bản theo yêu cầu là mô hình định giá tiết kiệm chi phí nhất cho khối lượng công việc không bị gián đoạn chạy mỗi năm một lần trong 24 giờ. Phiên bản Theo yêu cầu cho phép bạn trả phí cho công suất điện toán theo giờ hoặc giây, tùy thuộc vào phiên bản bạn chạy. Không yêu cầu cam kết dài hạn hoặc thanh toán trả trước. Bạn có thể tăng hoặc giảm công suất điện toán để đáp ứng nhu cầu của ứng dụng và chỉ trả mức phí theo giờ được chỉ định cho phiên bản bạn sử dụng1. Mô hình này phù hợp để phát triển/thử nghiệm các ứng dụng có khối lượng công việc ngắn hạn hoặc không thể đoán trước2. Các mô hình định giá khác không hiệu quả về mặt chi phí cho trường hợp sử dụng này. Phiên bản dự trữ và Gói tiết kiệm yêu cầu cam kết về mức sử dụng nhất quán, tính bằng USD mỗi giờ, trong thời hạn 1 hoặc 3 năm. Chúng cung cấp mức chiết khấu đáng kể so với Phiên bản theo yêu cầu, nhưng chúng không linh hoạt hoặc không thể mở rộng quy mô đối với khối lượng công việc chỉ chạy một lần mỗi năm12. Phiên bản dùng ngay là lựa chọn rẻ nhất nhưng chúng không phù hợp với khối lượng công việc không bị gián đoạn vì chúng có thể được AWS thu hồi bất kỳ lúc nào. Chúng được khuyên dùng cho các ứng dụng có thời gian bắt đầu và kết thúc linh hoạt hoặc chỉ khả thi ở mức giá điện toán rất thấp12. Phiên bản chuyên dụng được thiết kế để đáp ứng các yêu cầu về tuân thủ và cấp phép chứ không phải để tối ưu hóa chi phí. Chúng đắt hơn các tùy chọn khác vì chúng chạy trên phần cứng của một bên thuê12.', '[{"label": "A", "text_vi": "Phiên bản theo yêu cầu", "is_correct": true, "analysis_vi": "Đúng. Phiên bản theo yêu cầu là đáp án chính xác. Phiên bản theo yêu cầu là mô hình định giá tiết kiệm chi phí nhất cho khối lượng công việc không bị gián đoạn chạy mỗi năm một lần trong 24 giờ."}, {"label": "B", "text_vi": "Phiên bản dự trữ", "is_correct": false, "analysis_vi": "Sai. Phiên bản theo yêu cầu là mô hình định giá tiết kiệm chi phí nhất cho khối lượng công việc không bị gián đoạn chạy mỗi năm một lần trong 24 giờ."}, {"label": "C", "text_vi": "Phiên bản Spot", "is_correct": false, "analysis_vi": "Sai. Phiên bản theo yêu cầu là mô hình định giá tiết kiệm chi phí nhất cho khối lượng công việc không bị gián đoạn chạy mỗi năm một lần trong 24 giờ."}, {"label": "D", "text_vi": "Phiên bản chuyên dụng", "is_correct": false, "analysis_vi": "Sai. Phiên bản theo yêu cầu là mô hình định giá tiết kiệm chi phí nhất cho khối lượng công việc không bị gián đoạn chạy mỗi năm một lần trong 24 giờ."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
