INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-157', 'practice_283', 'AWS cung cấp những tùy chọn nào cho khách hàng muốn tìm hiểu về bảo mật trên đám mây trong môi trường có người hướng dẫn? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'Câu trả lời đúng là B và E vì AWS Online Tech Talks và AWS Classroom Training là các lựa chọn mà AWS cung cấp cho những khách hàng muốn tìm hiểu về bảo mật trên đám mây trong môi trường do người hướng dẫn hướng dẫn. Tọa đàm công nghệ trực tuyến AWS là các bài thuyết trình trực tuyến, trực tiếp bao gồm nhiều chủ đề ở các cấp độ kỹ thuật khác nhau. Tọa đàm công nghệ trực tuyến AWS do các chuyên gia AWS tổ chức và có các phiên hỏi đáp trực tiếp với khán giả. Đào tạo trong lớp học AWS là các khóa học trực tiếp hoặc ảo do các giảng viên AWS được công nhận dẫn dắt. Chương trình đào tạo trong lớp học AWS cung cấp các phòng thí nghiệm thực hành, bài tập và phương pháp thực hành tốt nhất để giúp khách hàng có được sự tự tin và kỹ năng trên AWS. Các tùy chọn khác không chính xác vì chúng không phải là các tùy chọn mà AWS cung cấp cho những khách hàng muốn tìm hiểu về bảo mật trên đám mây trong cài đặt do người hướng dẫn hướng dẫn. AWS Trusted Advisor là dịch vụ AWS cung cấp hướng dẫn theo thời gian thực để giúp khách hàng thực hiện theo các biện pháp thực hành tốt nhất của AWS về bảo mật, hiệu suất, tối ưu hóa chi phí và khả năng chịu lỗi. Blog AWS là tài nguyên AWS cung cấp tin tức, thông báo và thông tin chi tiết từ các chuyên gia và khách hàng AWS. Diễn đàn AWS là tài nguyên AWS cho phép khách hàng tương tác với những người dùng AWS khác và nhận phản hồi cũng như hỗ trợ.', '[{"label": "A", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. AWS Trusted Advisor: AWS Trusted Advisor quét toàn bộ tài khoản AWS và đưa ra khuyến nghị tối ưu theo 5 trụ cột: Chi phí, Hiệu năng, Bảo mật, Khả năng chịu lỗi và Giới hạn dịch vụ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Tọa đàm công nghệ trực tuyến của AWS", "is_correct": true, "analysis_vi": "Đúng. Tọa đàm công nghệ trực tuyến của AWS là đáp án chính xác. Câu trả lời đúng là B và E vì AWS Online Tech Talks và AWS Classroom Training là các lựa chọn mà AWS cung cấp cho những khách hàng muốn tìm hiểu về bảo mật trên đám mây trong môi trường do người hướng dẫn hướng dẫn."}, {"label": "C", "text_vi": "Blog AWS", "is_correct": false, "analysis_vi": "Sai. Blog AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Diễn đàn AWS", "is_correct": false, "analysis_vi": "Sai. Diễn đàn AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Đào tạo trên lớp học AWS", "is_correct": true, "analysis_vi": "Đúng. Đào tạo trên lớp học AWS là đáp án chính xác. Câu trả lời đúng là B và E vì AWS Online Tech Talks và AWS Classroom Training là các lựa chọn mà AWS cung cấp cho những khách hàng muốn tìm hiểu về bảo mật trên đám mây trong môi trường do người hướng dẫn hướng dẫn."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["AWS Trusted Advisor"]'::jsonb, NOW())
