INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-158', 'practice_283', 'Một công ty đang thiết kế giải pháp quản lý quyền truy cập danh tính cho một ứng dụng. Công ty muốn người dùng có thể sử dụng tài khoản mạng xã hội, email hoặc mua sắm trực tuyến của họ để truy cập ứng dụng. Dịch vụ AWS nào cung cấp chức năng này?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Câu trả lời đúng là C vì Amazon Cognito cung cấp liên kết danh tính và xác thực người dùng cho các ứng dụng web và di động. Amazon Cognito cho phép người dùng đăng nhập bằng tài khoản mạng xã hội, email hoặc mua sắm trực tuyến của họ. Các tùy chọn khác không chính xác vì chúng không cung cấp liên kết danh tính hoặc xác thực người dùng. Trung tâm nhận dạng AWS IAM (AWS Single Sign-On) là dịch vụ cho phép người dùng truy cập nhiều tài khoản và ứng dụng AWS chỉ bằng trải nghiệm đăng nhập một lần. AWS Config là dịch vụ cho phép người dùng đánh giá, kiểm tra và đánh giá cấu hình tài nguyên AWS của họ. AWS Identity and Access Management (IAM) là dịch vụ cho phép người dùng quản lý quyền truy cập vào tài nguyên AWS bằng cách sử dụng người dùng, nhóm, vai trò và chính sách.', '[{"label": "A", "text_vi": "Trung tâm nhận dạng AWS IAM (Đăng nhập một lần AWS)", "is_correct": false, "analysis_vi": "Sai. Trung tâm nhận dạng AWS IAM (Đăng nhập một lần AWS): AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Cấu hình AWS", "is_correct": false, "analysis_vi": "Sai. Cấu hình AWS: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Nhận thức của Amazon", "is_correct": true, "analysis_vi": "Đúng. Nhận thức của Amazon là đáp án chính xác. Câu trả lời đúng là C vì Amazon Cognito cung cấp liên kết danh tính và xác thực người dùng cho các ứng dụng web và di động."}, {"label": "D", "text_vi": "Quản lý quyền truy cập và nhận dạng AWS (IAM)", "is_correct": false, "analysis_vi": "Sai. Quản lý quyền truy cập và nhận dạng AWS (IAM): AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS IAM"]'::jsonb, NOW())
