INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-159', 'practice_283', 'Tùy chọn nào là lợi thế của điện toán đám mây AWS giúp giảm thiểu chi phí biến đổi?', 'Domain 1: Cloud Concepts', 'Quản lý chi phí & Thanh toán AWS', 'Một trong những lợi thế của điện toán đám mây AWS là nó giảm thiểu chi phí biến đổi bằng cách tận dụng tính kinh tế theo quy mô. Điều này có nghĩa là AWS có thể đạt được chi phí trên mỗi đơn vị tài nguyên điện toán thấp hơn bằng cách phân bổ chi phí cố định khi xây dựng và bảo trì trung tâm dữ liệu cho một số lượng lớn khách hàng. Do đó, AWS có thể đưa ra mức giá thấp hơn và dễ dự đoán hơn cho khách hàng của mình, những người chỉ trả tiền cho những tài nguyên họ tiêu thụ. Do đó, câu trả lời đúng là B. Bạn có thể tìm hiểu thêm về giá AWS và tính kinh tế theo quy mô từ trang này.', '[{"label": "A", "text_vi": "Tính sẵn sàng cao", "is_correct": false, "analysis_vi": "Sai. Tính sẵn sàng cao: Tính sẵn sàng cao (High Availability) đảm bảo ứng dụng vận hành liên tục không gián đoạn bằng cách triển khai phân tán trên nhiều Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Tính kinh tế theo quy mô", "is_correct": true, "analysis_vi": "Đúng. Tính kinh tế theo quy mô là đáp án chính xác. Một trong những lợi thế của điện toán đám mây AWS là nó giảm thiểu chi phí biến đổi bằng cách tận dụng tính kinh tế theo quy mô."}, {"label": "C", "text_vi": "Phạm vi tiếp cận toàn cầu", "is_correct": false, "analysis_vi": "Sai. Phạm vi tiếp cận toàn cầu: Phạm vi tiếp cận toàn cầu (Go global in minutes) cho phép triển khai ứng dụng tới người dùng ở nhiều quốc gia với độ trễ thấp thông qua mạng lưới AWS Regions và Edge Locations. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Nhanh nhẹn", "is_correct": false, "analysis_vi": "Sai. Nhanh nhẹn: Tính nhanh nhạy (Agility) giúp rút ngắn thời gian khởi tạo và thử nghiệm công nghệ từ hàng tuần xuống chỉ còn vài phút. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '[]'::jsonb, NOW())
