INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-160', 'practice_283', 'Một công ty muốn di chuyển kho dữ liệu tại chỗ của mình sang AWS. Thông tin trong kho dữ liệu được sử dụng để điền vào bảng điều khiển phân tích. Công ty nên sử dụng dịch vụ AWS nào cho kho dữ liệu?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Dịch vụ AWS mà công ty nên sử dụng cho kho dữ liệu là Amazon Redshift. Amazon Redshift là dịch vụ kho dữ liệu quy mô petabyte, được quản lý toàn phần, được tối ưu hóa cho các truy vấn phân tích. Nó có thể tích hợp với nhiều nguồn dữ liệu và công cụ kinh doanh thông minh khác nhau để cung cấp thông tin chuyên sâu nhanh chóng và tiết kiệm chi phí. Amazon Redshift cũng cung cấp các tính năng có tính sẵn sàng, khả năng mở rộng, bảo mật và tuân thủ cao. [Tổng quan về dịch chuyển đỏ của Amazon]', '[{"label": "A", "text_vi": "Amazon ElastiCache", "is_correct": false, "analysis_vi": "Sai. Amazon ElastiCache: Amazon ElastiCache là dịch vụ bộ nhớ đệm in-memory (Redis hoặc Memcached) giúp tăng tốc độ truy xuất dữ liệu với độ trễ dưới 1 mili-giây. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon cực quang", "is_correct": false, "analysis_vi": "Sai. Amazon cực quang: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon RDS", "is_correct": false, "analysis_vi": "Sai. Amazon RDS: Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Dịch chuyển đỏ của Amazon", "is_correct": true, "analysis_vi": "Đúng. Dịch chuyển đỏ của Amazon là đáp án chính xác. Dịch vụ AWS mà công ty nên sử dụng cho kho dữ liệu là Amazon Redshift."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon RDS", "Amazon Aurora"]'::jsonb, NOW())
