INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-161', 'practice_283', 'Một công ty sử dụng Amazon Aurora làm dịch vụ cơ sở dữ liệu của mình. Công ty muốn mã hóa cơ sở dữ liệu và sao lưu cơ sở dữ liệu của mình. Bên nào quản lý việc mã hóa các cụm cơ sở dữ liệu và kết xuất nhanh cơ sở dữ liệu theo mô hình trách nhiệm chung của AWS?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'AWS quản lý việc mã hóa các cụm cơ sở dữ liệu và kết xuất nhanh cơ sở dữ liệu cho Amazon Aurora cũng như các khóa mã hóa. Đây là một phần của mô hình trách nhiệm chung của AWS, trong đó AWS chịu trách nhiệm về tính bảo mật của đám mây và khách hàng chịu trách nhiệm về tính bảo mật trên đám mây. Mã hóa là một trong những tính năng bảo mật mà AWS cung cấp để bảo vệ dữ liệu khi lưu trữ và truyền tải. Để biết thêm thông tin, hãy xem Câu hỏi thường gặp về Amazon Aurora và Mô hình trách nhiệm chung của AWS.', '[{"label": "A", "text_vi": "AWS", "is_correct": true, "analysis_vi": "Đúng. AWS đáp ứng đầy đủ yêu cầu của đề bài. AWS quản lý việc mã hóa các cụm cơ sở dữ liệu và kết xuất nhanh cơ sở dữ liệu cho Amazon Aurora cũng như các khóa mã hóa."}, {"label": "B", "text_vi": "Công ty", "is_correct": false, "analysis_vi": "Sai. Công ty không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Đối tác của AWS Marketplace", "is_correct": false, "analysis_vi": "Sai. Đối tác của AWS Marketplace không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Đối tác bên thứ ba", "is_correct": false, "analysis_vi": "Sai. Đối tác bên thứ ba không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon Aurora"]'::jsonb, NOW())
