INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-162', 'practice_283', 'Thành phần nào sau đây là thành phần của kết nối VPN Site-to-Site của AWS? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Câu trả lời đúng là B và D vì cổng riêng ảo và cổng khách hàng là các thành phần của kết nối VPN Site-to-Site của AWS. Cổng riêng ảo là phía AWS của kết nối VPN gắn với VPC của khách hàng. Cổng khách hàng là phía khách hàng của kết nối VPN nằm trong mạng của khách hàng. Các tùy chọn khác không chính xác vì chúng không phải là thành phần của kết nối VPN Site-to-Site của AWS. AWS Storage Gateway là dịch vụ kết nối các ứng dụng phần mềm tại chỗ với bộ lưu trữ trên nền tảng đám mây. NAT Gateway là dịch vụ cho phép các phiên bản trong mạng con riêng kết nối với Internet hoặc các dịch vụ AWS khác nhưng ngăn Internet bắt đầu kết nối với các phiên bản đó. Cổng Internet là dịch vụ cho phép liên lạc giữa các phiên bản trong VPC và internet.', '[{"label": "A", "text_vi": "AWS Storage Gateway", "is_correct": false, "analysis_vi": "Sai. AWS Storage Gateway: AWS Storage Gateway kết nối môi trường tại chỗ với lưu trữ đám mây AWS, cung cấp quyền truy cập liền mạch vào S3 và EBS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Cổng riêng ảo", "is_correct": true, "analysis_vi": "Đúng. Cổng riêng ảo là đáp án chính xác. Câu trả lời đúng là B và D vì cổng riêng ảo và cổng khách hàng là các thành phần của kết nối VPN Site-to-Site của AWS."}, {"label": "C", "text_vi": "NAT Gateway", "is_correct": false, "analysis_vi": "Sai. NAT Gateway: NAT Gateway cho phép các phiên bản trong Private Subnet kết nối ra Internet để tải bản vá/cập nhật nhưng chặn Internet khởi tạo kết nối vào. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Cổng khách hàng", "is_correct": true, "analysis_vi": "Đúng. Cổng khách hàng là đáp án chính xác. Câu trả lời đúng là B và D vì cổng riêng ảo và cổng khách hàng là các thành phần của kết nối VPN Site-to-Site của AWS."}, {"label": "E", "text_vi": "Cổng Internet", "is_correct": false, "analysis_vi": "Sai. Cổng Internet: Internet Gateway là thành phần VPC cho phép giao tiếp hai chiều giữa các tài nguyên trong VPC và mạng Internet công cộng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Direct Connect", "AWS Storage Gateway"]'::jsonb, NOW())
