INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-163', 'practice_283', 'Một công ty muốn chuyển cơ sở dữ liệu tại chỗ của mình sang các dịch vụ cơ sở dữ liệu đám mây được quản lý bằng cách sử dụng quy trình di chuyển đơn giản hóa. Dịch vụ hoặc công cụ AWS nào có thể giúp công ty đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Dịch vụ di chuyển cơ sở dữ liệu AWS (AWS DMS) là dịch vụ đám mây giúp di chuyển cơ sở dữ liệu quan hệ, kho dữ liệu, cơ sở dữ liệu NoSQL và các loại kho dữ liệu khác. Bạn có thể sử dụng AWS DMS để di chuyển dữ liệu của mình vào Đám mây AWS hoặc giữa các tổ hợp thiết lập đám mây và tại chỗ. Với AWS DMS, bạn có thể khám phá kho lưu trữ dữ liệu nguồn, chuyển đổi lược đồ nguồn và di chuyển dữ liệu của mình. AWS DMS hỗ trợ di chuyển giữa hơn 20 cơ sở dữ liệu và công cụ phân tích, chẳng hạn như Oracle sang Amazon Aurora Phiên bản tương thích với MySQL, MySQL sang Cơ sở dữ liệu quan hệ Amazon (RDS) cho MySQL, Microsoft SQL Server sang Phiên bản tương thích với Amazon Aurora PostgreSQL, MongoDB sang Amazon DocumentDB (có khả năng tương thích với MongoDB), Oracle sang Amazon Redshift và Amazon Simple Storage Service (S3). Bạn có thể thực hiện di chuyển một lần hoặc sao chép các thay đổi đang diễn ra để giữ cho nguồn và đích được đồng bộ hóa. AWS DMS tự động quản lý việc triển khai, quản lý và giám sát tất cả phần cứng và phần mềm cần thiết cho quá trình di chuyển của bạn. AWS DMS là dịch vụ đám mây bảo mật, có độ linh hoạt cao, cung cấp khả năng khám phá cơ sở dữ liệu, chuyển đổi lược đồ, di chuyển dữ liệu và sao chép liên tục đến và từ nhiều cơ sở dữ liệu và hệ thống phân tích12.', '[{"label": "A", "text_vi": "AWS Storage Gateway", "is_correct": false, "analysis_vi": "Sai. AWS Storage Gateway: AWS Storage Gateway kết nối môi trường tại chỗ với lưu trữ đám mây AWS, cung cấp quyền truy cập liền mạch vào S3 và EBS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Dịch vụ di chuyển ứng dụng AWS", "is_correct": false, "analysis_vi": "Sai. Dịch vụ di chuyển ứng dụng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Đồng bộ hóa dữ liệu AWS", "is_correct": false, "analysis_vi": "Sai. Đồng bộ hóa dữ liệu AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Dịch vụ di chuyển cơ sở dữ liệu AWS (AWS DMS)", "is_correct": true, "analysis_vi": "Đúng. Dịch vụ di chuyển cơ sở dữ liệu AWS (AWS DMS) là đáp án chính xác. Dịch vụ di chuyển cơ sở dữ liệu AWS (AWS DMS) là dịch vụ đám mây giúp di chuyển cơ sở dữ liệu quan hệ, kho dữ liệu, cơ sở dữ liệu NoSQL và các loại kho dữ liệu khác."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Storage Gateway"]'::jsonb, NOW())
