INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-164', 'practice_283', 'Điều nào sau đây là lợi thế của việc chuyển sang Đám mây AWS? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Lợi thế điện toán đám mây & Hạ tầng toàn cầu', 'Ưu điểm của việc chuyển sang Đám mây AWS là khả năng sử dụng mô hình trả tiền theo mức sử dụng và không còn phải đoán xem sẽ cần dung lượng gì. Mô hình trả tiền theo nhu cầu sử dụng cho phép người dùng chỉ trả tiền cho những tài nguyên họ sử dụng mà không cần bất kỳ cam kết trả trước hoặc dài hạn nào. Điều này làm giảm chi phí và rủi ro của việc cung cấp quá mức hoặc cung cấp thiếu nguồn lực. Không còn phải đoán dung lượng sẽ được yêu cầu nghĩa là người dùng có thể tăng hoặc giảm quy mô tài nguyên của mình theo nhu cầu mà không lãng phí tiền vào tài nguyên nhàn rỗi hoặc mất khách hàng do không đủ dung lượng4.', '[{"label": "A", "text_vi": "Khả năng chuyển giao trách nhiệm về mọi vấn đề bảo mật cho AWS.", "is_correct": false, "analysis_vi": "Sai. Ưu điểm của việc chuyển sang Đám mây AWS là khả năng sử dụng mô hình trả tiền theo mức sử dụng và không còn phải đoán xem sẽ cần dung lượng gì."}, {"label": "B", "text_vi": "Khả năng sử dụng mô hình trả tiền theo mức sử dụng.", "is_correct": true, "analysis_vi": "Đúng. Khả năng sử dụng mô hình trả tiền theo mức sử dụng. là đáp án chính xác. Ưu điểm của việc chuyển sang Đám mây AWS là khả năng sử dụng mô hình trả tiền theo mức sử dụng và không còn phải đoán xem sẽ cần dung lượng gì."}, {"label": "C", "text_vi": "Khả năng có toàn quyền kiểm soát cơ sở hạ tầng vật lý.", "is_correct": false, "analysis_vi": "Sai. Ưu điểm của việc chuyển sang Đám mây AWS là khả năng sử dụng mô hình trả tiền theo mức sử dụng và không còn phải đoán xem sẽ cần dung lượng gì."}, {"label": "D", "text_vi": "Không còn phải đoán xem sẽ cần dung lượng bao nhiêu.", "is_correct": true, "analysis_vi": "Đúng. Không còn phải đoán xem sẽ cần dung lượng bao nhiêu. là đáp án chính xác. Ưu điểm của việc chuyển sang Đám mây AWS là khả năng sử dụng mô hình trả tiền theo mức sử dụng và không còn phải đoán xem sẽ cần dung lượng gì."}, {"label": "E", "text_vi": "Không còn lo lắng về việc kiểm soát quyền truy cập của người dùng.", "is_correct": false, "analysis_vi": "Sai. Ưu điểm của việc chuyển sang Đám mây AWS là khả năng sử dụng mô hình trả tiền theo mức sử dụng và không còn phải đoán xem sẽ cần dung lượng gì."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
