INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-165', 'practice_283', 'Điều nào sau đây là trụ cột của Khung kiến trúc tối ưu AWS? (Chọn HAI)', 'Domain 1: Cloud Concepts', 'Khung kiến trúc tối ưu AWS (Well-Architected Framework)', 'Khung kiến trúc tối ưu AWS là một bộ gồm sáu trụ cột và ống kính giúp các kiến trúc sư đám mây thiết kế và chạy khối lượng công việc trên đám mây. Sáu trụ cột là: hoạt động xuất sắc, bảo mật, độ tin cậy, hiệu quả hoạt động, tối ưu hóa chi phí và tính bền vững. Mỗi trụ cột có một bộ nguyên tắc thiết kế và các phương pháp thực hành tốt nhất hướng dẫn các quyết định về kiến ​​trúc. Tính sẵn sàng cao không phải là một trụ cột riêng biệt mà là chất lượng có thể đạt được bằng cách áp dụng các nguyên tắc của trụ cột độ tin cậy. Đưa ra toàn cầu trong vài phút và phát triển liên tục không phải là trụ cột của khuôn khổ mà là những lợi ích có thể có khi sử dụng dịch vụ AWS và tuân theo các đề xuất của khuôn khổ.', '[{"label": "A", "text_vi": "Tính sẵn sàng cao", "is_correct": false, "analysis_vi": "Sai. Tính sẵn sàng cao: Tính sẵn sàng cao (High Availability) đảm bảo ứng dụng vận hành liên tục không gián đoạn bằng cách triển khai phân tán trên nhiều Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Hiệu quả hoạt động", "is_correct": true, "analysis_vi": "Đúng. Hiệu quả hoạt động là đáp án chính xác. Sáu trụ cột là: hoạt động xuất sắc, bảo mật, độ tin cậy, hiệu quả hoạt động, tối ưu hóa chi phí và tính bền vững."}, {"label": "C", "text_vi": "Tối ưu hóa chi phí", "is_correct": true, "analysis_vi": "Đúng. Tối ưu hóa chi phí đáp ứng đầy đủ yêu cầu của đề bài. Khung kiến trúc tối ưu AWS là một bộ gồm sáu trụ cột và ống kính giúp các kiến trúc sư đám mây thiết kế và chạy khối lượng công việc trên đám mây."}, {"label": "D", "text_vi": "Vươn ra toàn cầu trong vài phút", "is_correct": false, "analysis_vi": "Sai. Đưa ra toàn cầu trong vài phút và phát triển liên tục không phải là trụ cột của khuôn khổ mà là những lợi ích có thể có khi sử dụng dịch vụ AWS và tuân theo các đề xuất của khuôn khổ.."}, {"label": "E", "text_vi": "Phát triển không ngừng", "is_correct": false, "analysis_vi": "Sai. Đưa ra toàn cầu trong vài phút và phát triển liên tục không phải là trụ cột của khuôn khổ mà là những lợi ích có thể có khi sử dụng dịch vụ AWS và tuân theo các đề xuất của khuôn khổ.."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
