INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-167', 'practice_283', 'Dịch vụ AWS nào có thể báo cáo cấu hình tài nguyên AWS đã thay đổi như thế nào theo thời gian?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS Config là dịch vụ cho phép người dùng đánh giá, kiểm tra và đánh giá cấu hình của tài nguyên AWS. Nó liên tục theo dõi và ghi lại các thay đổi cấu hình của tài nguyên và đánh giá chúng theo cấu hình mong muốn và các phương pháp hay nhất. Nó cũng cung cấp cái nhìn chi tiết về lịch sử và các mối quan hệ cấu hình tài nguyên, cũng như các báo cáo và thông báo tuân thủ. AWS Config có thể giúp người dùng duy trì cấu hình nhất quán và an toàn, khắc phục sự cố và đơn giản hóa việc kiểm tra tuân thủ. Tổng quan về cấu hình AWSNgười thực hành đám mây được chứng nhận của AWS - aws.amazon.com', '[{"label": "A", "text_vi": "AWS CloudTrail", "is_correct": false, "analysis_vi": "Sai. AWS CloudTrail: AWS CloudTrail ghi nhật ký và giám sát toàn bộ hoạt động gọi API của tài khoản AWS, phục vụ quản trị, kiểm toán bảo mật và tuân thủ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon CloudWatch", "is_correct": false, "analysis_vi": "Sai. Amazon CloudWatch: Amazon CloudWatch là dịch vụ giám sát và quan sát tài nguyên, thu thập chỉ số (metrics), log và gửi cảnh báo (alarms) theo thời gian thực. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Cấu hình AWS", "is_correct": true, "analysis_vi": "Đúng. Cấu hình AWS là đáp án chính xác. AWS Config là dịch vụ cho phép người dùng đánh giá, kiểm tra và đánh giá cấu hình của tài nguyên AWS."}, {"label": "D", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon Inspector: Amazon Inspector là dịch vụ quản lý lỗ hổng bảo mật tự động, quét các lỗ hổng phần mềm và phát hiện phơi nhiễm mạng ngoài ý muốn trên EC2, ECR và Lambda. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon CloudWatch", "AWS CloudTrail", "Amazon Inspector"]'::jsonb, NOW())
