  updated_at = NOW();

INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-168', 'practice_283', 'Một công ty muốn khởi chạy ứng dụng web của mình ở AWS Region thứ hai. Công ty cần xác định những dịch vụ nào phải được định cấu hình theo khu vực cho lần ra mắt này. Những dịch vụ AWS nào có thể được cấu hình ở cấp Khu vực? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Lợi thế điện toán đám mây & Hạ tầng toàn cầu', 'Amazon Route 53 và AWS WAF là các dịch vụ AWS có thể được cấu hình ở cấp Khu vực. Amazon Route 53 là dịch vụ web Hệ thống tên miền (DNS) trên nền tảng đám mây có tính sẵn sàng cao và có khả năng mở rộng cho phép bạn đăng ký tên miền, định tuyến lưu lượng truy cập đến tài nguyên và kiểm tra tình trạng tài nguyên của bạn. AWS WAF là tường lửa ứng dụng web giúp bảo vệ các ứng dụng web hoặc API của bạn khỏi các hoạt động khai thác web phổ biến có thể ảnh hưởng đến tính khả dụng, xâm phạm bảo mật hoặc tiêu tốn quá nhiều tài nguyên. Amazon EC2, Amazon CloudFront và Amazon DynamoDB là các dịch vụ AWS có thể được đặt cấu hình ở cấp độ toàn cầu hoặc cấp Availability Zone (AZ).', '[{"label": "A", "text_vi": "Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Tuyến đường Amazon 53", "is_correct": true, "analysis_vi": "Đúng. Tuyến đường Amazon 53 là đáp án chính xác. Amazon Route 53 và AWS WAF là các dịch vụ AWS có thể được cấu hình ở cấp Khu vực."}, {"label": "C", "text_vi": "Amazon CloudFront", "is_correct": false, "analysis_vi": "Sai. Amazon CloudFront: Amazon CloudFront là dịch vụ mạng phân phối nội dung (CDN) toàn cầu với độ trễ thấp thông qua mạng lưới các Edge Location. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "AWS WAF", "is_correct": true, "analysis_vi": "Đúng. AWS WAF là giải pháp đáp ứng yêu cầu. Amazon Route 53 và AWS WAF là các dịch vụ AWS có thể được cấu hình ở cấp Khu vực. AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS."}, {"label": "E", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon DynamoDB: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon DynamoDB", "Amazon CloudFront", "Amazon Route 53", "AWS WAF"]'::jsonb, NOW())
