INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-169', 'practice_283', 'Một công ty muốn đưa ra cam kết trả trước về việc tiếp tục sử dụng các phiên bản Amazon EC2 sản xuất của mình để đổi lấy tổng chi phí giảm xuống. Tùy chọn giá nào đáp ứng các yêu cầu này với chi phí THẤP NHẤT? (Chọn HAI.)', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'Phiên bản dự trữ (RI) là mô hình định giá cho phép bạn đặt trước phiên bản EC2 trong một khoảng thời gian xác định (một hoặc ba năm) và được giảm giá đáng kể so với giá Theo yêu cầu. RI phù hợp với khối lượng công việc có kiểu sử dụng có thể dự đoán được và yêu cầu cam kết lâu dài. Bạn có thể chọn giữa ba tùy chọn thanh toán: Trả trước toàn bộ, Trả trước một phần hoặc Không trả trước. Trả trước càng nhiều thì chiết khấu càng lớn1. Gói tiết kiệm là mô hình định giá linh hoạt có thể giúp bạn giảm tới 72% chi phí EC2 so với giá Theo yêu cầu, để đổi lấy cam kết về mức sử dụng nhất quán (tính bằng USD/giờ) trong thời hạn một hoặc ba năm. Savings Plans áp dụng cho mức sử dụng trên EC2, AWS Lambda và AWS Fargate. Bạn có thể chọn giữa hai loại Kế hoạch tiết kiệm: Kế hoạch tiết kiệm điện toán và Kế hoạch tiết kiệm phiên bản EC2. Kế hoạch tiết kiệm điện toán mang đến sự linh hoạt nhất và áp dụng cho mọi dòng phiên bản, quy mô, hệ điều hành, hình thức thuê hoặc khu vực. Gói tiết kiệm phiên bản EC2 mang lại mức chiết khấu cao nhất và áp dụng cho một dòng phiên bản cụ thể trong một khu vực2. Phiên bản Spot là mô hình định giá cho phép bạn đặt giá thầu cho dung lượng EC2 chưa sử dụng trên đám mây AWS và có mức chiết khấu lên tới 90% so với giá Theo yêu cầu. Phiên bản Spot phù hợp với khối lượng công việc có khả năng chịu lỗi hoặc không trạng thái, có thể chạy trên phần cứng không đồng nhất và có thời gian bắt đầu và kết thúc linh hoạt. Tuy nhiên, Phiên bản Spot không được đảm bảo và có thể bị gián đoạn bởi AWS bất cứ lúc nào nếu nhu cầu về công suất tăng hoặc giá thầu của bạn thấp hơn giá Spot hiện tại3. Phiên bản theo yêu cầu là mô hình định giá cho phép bạn thanh toán cho công suất điện toán theo giờ hoặc giây mà không cần cam kết dài hạn. Phiên bản Theo yêu cầu phù hợp với khối lượng công việc ngắn hạn, đột biến hoặc không thể đoán trước mà không thể bị gián đoạn hoặc dành cho các ứng dụng đang được phát triển hoặc thử nghiệm trên EC2 lần đầu tiên. Tuy nhiên, Phiên bản theo yêu cầu là lựa chọn đắt nhất trong số bốn mô hình định giá4. Máy chủ chuyên dụng là máy chủ EC2 vật lý hoàn toàn dành riêng cho bạn sử dụng. Máy chủ chuyên dụng có thể giúp bạn giảm chi phí bằng cách cho phép bạn sử dụng các giấy phép phần mềm gắn với máy chủ hiện có, chẳng hạn như Windows Server, SQL Server và SUSE Linux Enterprise Server. Bạn có thể mua Máy chủ chuyên dụng theo yêu cầu hoặc như một phần của Savings Plans. Máy chủ chuyên dụng phù hợp với khối lượng công việc cần chạy trên máy chủ vật lý chuyên dụng hoặc có yêu cầu cấp phép nghiêm ngặt. Tuy nhiên, Máy chủ chuyên dụng không phải là lựa chọn có chi phí thấp nhất trong số bốn mô hình định giá.', '[{"label": "A", "text_vi": "Phiên bản Spot", "is_correct": false, "analysis_vi": "Sai. Phiên bản Spot không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Phiên bản theo yêu cầu", "is_correct": true, "analysis_vi": "Đúng. Phiên bản theo yêu cầu là đáp án chính xác. Phiên bản dự trữ (RI) là mô hình định giá cho phép bạn đặt trước phiên bản EC2 trong một khoảng thời gian xác định (một hoặc ba năm) và được giảm giá đáng kể so với giá Theo yêu cầu."}, {"label": "C", "text_vi": "Phiên bản dự trữ", "is_correct": true, "analysis_vi": "Đúng. Phiên bản dự trữ là đáp án chính xác. Phiên bản dự trữ (RI) là mô hình định giá cho phép bạn đặt trước phiên bản EC2 trong một khoảng thời gian xác định (một hoặc ba năm) và được giảm giá đáng kể so với giá Theo yêu cầu."}, {"label": "D", "text_vi": "Kế hoạch tiết kiệm", "is_correct": false, "analysis_vi": "Sai. Kế hoạch tiết kiệm không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Máy chủ chuyên dụng", "is_correct": false, "analysis_vi": "Sai. Máy chủ chuyên dụng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
