INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-170', 'practice_283', 'Một công ty cần thiết lập xác thực người dùng cho ứng dụng di động. Người dùng phải có khả năng đăng nhập trực tiếp bằng tên người dùng và mật khẩu hoặc thông qua nhà cung cấp danh tính bên thứ ba. Công ty nên sử dụng dịch vụ AWS nào để đáp ứng những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Amazon Cognito là dịch vụ cung cấp xác thực và ủy quyền người dùng cho các ứng dụng web và di động. Bạn có thể sử dụng Amazon Cognito để cho phép người dùng đăng nhập trực tiếp bằng tên người dùng và mật khẩu hoặc thông qua nhà cung cấp bên thứ ba, chẳng hạn như Facebook, Google hoặc Amazon. Bạn cũng có thể sử dụng Amazon Cognito để quản lý hồ sơ người dùng, tùy chọn và cài đặt bảo mật3', '[{"label": "A", "text_vi": "Trung tâm nhận dạng AWS IAM (Đăng nhập một lần AWS)", "is_correct": false, "analysis_vi": "Sai. Trung tâm nhận dạng AWS IAM (Đăng nhập một lần AWS): AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Người ký AWS", "is_correct": false, "analysis_vi": "Sai. Người ký AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Nhận thức của Amazon", "is_correct": true, "analysis_vi": "Đúng. Nhận thức của Amazon là đáp án chính xác. Amazon Cognito là dịch vụ cung cấp xác thực và ủy quyền người dùng cho các ứng dụng web và di động."}, {"label": "D", "text_vi": "Dịch vụ thư mục AWS", "is_correct": false, "analysis_vi": "Sai. Dịch vụ thư mục AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS IAM"]'::jsonb, NOW())
