INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-171', 'practice_283', 'Một công ty muốn đặt ra các mục tiêu chi tiêu của AWS và theo dõi chi phí theo các mục tiêu đó. Công ty nên sử dụng công cụ hoặc tính năng nào của AWS để đáp ứng các yêu cầu này?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'AWS Budgets là công cụ cho phép người dùng đặt mục tiêu chi tiêu AWS và theo dõi chi phí theo các mục tiêu đó. Người dùng có thể tạo ngân sách cho nhiều thứ nguyên khác nhau, chẳng hạn như dịch vụ, tài khoản được liên kết, thẻ, v.v. Người dùng cũng có thể nhận được thông báo khi chi phí thực tế hoặc dự báo vượt quá hoặc dự kiến ​​vượt quá số tiền dự toán. AWS Cost Explorer, Báo cáo chi phí và sử dụng AWS cũng như Kế hoạch tiết kiệm là các công cụ hoặc tính năng khác của AWS có thể giúp người dùng quản lý và tối ưu hóa chi phí AWS của họ nhưng không cho phép người dùng đặt và theo dõi mục tiêu chi tiêu.', '[{"label": "A", "text_vi": "Trình AWS Cost Explorer AWS", "is_correct": false, "analysis_vi": "Sai. AWS Cost Explorer, Báo cáo chi phí và sử dụng AWS cũng như Kế hoạch tiết kiệm là các công cụ hoặc tính năng khác của AWS có thể giúp người dùng quản lý và tối ưu hóa chi phí AWS của họ nhưng không cho phép người dùng đặt và theo dõi mục tiêu chi tiêu.."}, {"label": "B", "text_vi": "Ngân sách AWS", "is_correct": true, "analysis_vi": "Đúng. Ngân sách AWS là đáp án chính xác. AWS Budgets là công cụ cho phép người dùng đặt mục tiêu chi tiêu AWS và theo dõi chi phí theo các mục tiêu đó."}, {"label": "C", "text_vi": "Báo cáo chi phí và mức sử dụng AWS", "is_correct": false, "analysis_vi": "Sai. AWS Cost Explorer, Báo cáo chi phí và sử dụng AWS cũng như Kế hoạch tiết kiệm là các công cụ hoặc tính năng khác của AWS có thể giúp người dùng quản lý và tối ưu hóa chi phí AWS của họ nhưng không cho phép người dùng đặt và theo dõi mục tiêu chi tiêu.."}, {"label": "D", "text_vi": "Kế hoạch tiết kiệm", "is_correct": false, "analysis_vi": "Sai. AWS Cost Explorer, Báo cáo chi phí và sử dụng AWS cũng như Kế hoạch tiết kiệm là các công cụ hoặc tính năng khác của AWS có thể giúp người dùng quản lý và tối ưu hóa chi phí AWS của họ nhưng không cho phép người dùng đặt và theo dõi mục tiêu chi tiêu.."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["AWS Cost Explorer", "AWS Budgets"]'::jsonb, NOW())
