INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-172', 'practice_283', 'Một công ty đã thiết lập VPC trên AWS. Công ty cần có kết nối chuyên dụng giữa VPC và mạng tại chỗ của công ty. Công ty nên thực hiện hành động nào để đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Hạ tầng mạng & Phân phối nội dung (VPC & Networking)', 'Thiết lập kết nối AWS Direct Connect giữa VPC và mạng tại chỗ của công ty là hành động mà công ty nên thực hiện để đáp ứng yêu cầu có kết nối chuyên dụng giữa VPC và mạng tại chỗ của công ty. AWS Direct Connect là dịch vụ cho phép bạn thiết lập kết nối mạng chuyên dụng giữa mạng của bạn và một trong các vị trí AWS Direct Connect. Bằng cách sử dụng AWS Direct Connect, bạn có thể tạo kết nối riêng giữa AWS và trung tâm dữ liệu, văn phòng hoặc môi trường colocation, điều này có thể giảm chi phí mạng, tăng thông lượng băng thông và cung cấp trải nghiệm mạng nhất quán hơn so với kết nối dựa trên internet. Thiết lập kết nối VPN giữa VPC và mạng tại chỗ của công ty là hành động mà công ty có thể thực hiện để tạo kết nối an toàn và được mã hóa giữa VPC và mạng tại chỗ của công ty, nhưng đây không phải là kết nối chuyên dụng vì nó sử dụng Internet công cộng làm cơ chế truyền tải. Gắn cổng internet vào VPC và sử dụng điểm cuối công cộng AWS để kết nối là hành động mà công ty có thể thực hiện để kích hoạt giao tiếp giữa VPC và internet, nhưng đó không phải là kết nối chuyên dụng vì nó cũng sử dụng internet công cộng làm cơ chế truyền tải. Việc định cấu hình Amazon Connect để cung cấp kết nối giữa VPC và mạng tại chỗ của công ty không phải là hành động mà công ty có thể thực hiện vì Amazon Connect là dịch vụ cho phép bạn thiết lập và quản lý trung tâm liên hệ trên đám mây, nhưng nó không cung cấp kết nối mạng giữa VPC và mạng tại chỗ của công ty.', '[{"label": "A", "text_vi": "Thiết lập kết nối VPN giữa VPC và mạng tại chỗ của công ty.", "is_correct": false, "analysis_vi": "Sai. Thiết lập kết nối VPN giữa VPC và mạng tại chỗ của công ty.: Amazon VPC cho phép khởi tạo mạng ảo riêng biệt được cô lập logic trên đám mây AWS, kiểm soát toàn diện dải IP, subnet, bảng định tuyến và cổng mạng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Thiết lập kết nối AWS Direct Connect giữa VPC và mạng tại chỗ của công ty.", "is_correct": true, "analysis_vi": "Đúng. Thiết lập kết nối AWS Direct Connect giữa VPC và mạng tại chỗ của công ty. là đáp án chính xác. Thiết lập kết nối AWS Direct Connect giữa VPC và mạng tại chỗ của công ty là hành động mà công ty nên thực hiện để đáp ứng yêu cầu có kết nối chuyên dụng giữa VPC và mạng tại chỗ của công ty."}, {"label": "C", "text_vi": "Gắn cổng internet vào VPC. Sử dụng các điểm cuối công khai của AWS để kết nối.", "is_correct": false, "analysis_vi": "Sai. Gắn cổng internet vào VPC. Sử dụng các điểm cuối công khai của AWS để kết nối.: Amazon VPC cho phép khởi tạo mạng ảo riêng biệt được cô lập logic trên đám mây AWS, kiểm soát toàn diện dải IP, subnet, bảng định tuyến và cổng mạng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Định cấu hình Amazon Connect để cung cấp kết nối giữa VPC và mạng tại chỗ của công ty.", "is_correct": false, "analysis_vi": "Sai. Định cấu hình Amazon Connect để cung cấp kết nối giữa VPC và mạng tại chỗ của công ty.: Amazon VPC cho phép khởi tạo mạng ảo riêng biệt được cô lập logic trên đám mây AWS, kiểm soát toàn diện dải IP, subnet, bảng định tuyến và cổng mạng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon VPC", "AWS Direct Connect", "AWS Storage Gateway"]'::jsonb, NOW())
