INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-173', 'practice_283', '"Bảo mật của đám mây" đề cập đến điều gì trong mô hình trách nhiệm chung của AWS?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Bảo mật của đám mây đề cập đến tính bảo mật của cơ sở hạ tầng đám mây chạy tất cả các dịch vụ AWS. Điều này bao gồm phần cứng, phần mềm, mạng và cơ sở vật chất mà AWS vận hành và quản lý. AWS chịu trách nhiệm bảo vệ tính bảo mật của đám mây như một phần của mô hình trách nhiệm chung của AWS. Tính khả dụng của các dịch vụ AWS như Amazon EC2 đề cập đến khả năng thiết lập và chạy các dịch vụ cũng như đáp ứng hiệu suất mong đợi. Tính khả dụng là một phần trong trụ cột về độ tin cậy của Khung kiến ​​trúc tối ưu AWS và là trách nhiệm chung giữa AWS và khách hàng. Việc triển khai chính sách mật khẩu cho người dùng IAM đề cập đến tính bảo mật của dữ liệu khách hàng và ứng dụng trên đám mây. Điều này bao gồm cấu hình và quản lý quyền của người dùng IAM, khóa mã hóa, quy tắc Security Group, ACL mạng và các khía cạnh khác của quản lý quyền truy cập. Khách hàng có trách nhiệm bảo vệ tính bảo mật trên đám mây như một phần của mô hình trách nhiệm chung của AWS. Bảo mật môi trường khách hàng bằng cách sử dụng đối tác Tường lửa mạng AWS đề cập đến tính bảo mật của dữ liệu khách hàng và ứng dụng trên đám mây. Tường lửa mạng AWS là dịch vụ được quản lý nhằm cung cấp khả năng bảo vệ mạng cho Amazon VPC. Nó cho phép khách hàng sử dụng các đối tác của AWS Marketplace để triển khai các quy tắc và chính sách tường lửa. Khách hàng chịu trách nhiệm bảo vệ tính bảo mật trên đám mây như một phần của mô hình trách nhiệm chung của AWS.', '[{"label": "A", "text_vi": "Tính khả dụng của các dịch vụ AWS như Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Tính khả dụng của các dịch vụ AWS như Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Bảo mật cơ sở hạ tầng đám mây chạy tất cả các dịch vụ AWS", "is_correct": true, "analysis_vi": "Đúng. Bảo mật cơ sở hạ tầng đám mây chạy tất cả các dịch vụ AWS là đáp án chính xác. Bảo mật của đám mây đề cập đến tính bảo mật của cơ sở hạ tầng đám mây chạy tất cả các dịch vụ AWS."}, {"label": "C", "text_vi": "Triển khai chính sách mật khẩu cho người dùng IAM", "is_correct": false, "analysis_vi": "Sai. Triển khai chính sách mật khẩu cho người dùng IAM: AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Bảo mật môi trường khách hàng bằng cách sử dụng đối tác Tường lửa mạng AWS", "is_correct": false, "analysis_vi": "Sai. Bảo mật môi trường khách hàng bằng cách sử dụng đối tác Tường lửa mạng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon EC2", "AWS IAM"]'::jsonb, NOW())
