INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-174', 'practice_283', 'Dịch vụ hoặc tính năng AWS nào xác định xem bộ chứa Amazon S3 hay vai trò IAM đã được chia sẻ với thực thể bên ngoài chưa?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Trình phân tích truy cập AWS IAM là dịch vụ giúp bạn xác định các tài nguyên trong tổ chức và tài khoản của mình, chẳng hạn như bộ chứa Amazon S3 hoặc vai trò IAM, được chia sẻ với một thực thể bên ngoài. Điều này cho phép bạn xác định quyền truy cập ngoài ý muốn vào tài nguyên và dữ liệu của mình, đây là một rủi ro bảo mật. Trình phân tích truy cập IAM sử dụng lý luận dựa trên logic để phân tích các chính sách dựa trên tài nguyên trong môi trường AWS của bạn. Đối với mỗi phiên bản tài nguyên được chia sẻ bên ngoài tài khoản của bạn, Trình phân tích truy cập IAM sẽ tạo ra một kết quả. Các phát hiện bao gồm thông tin về quyền truy cập và quyền chính bên ngoài được cấp cho nó345.', '[{"label": "A", "text_vi": "Danh mục dịch vụ AWS", "is_correct": false, "analysis_vi": "Sai. Danh mục dịch vụ AWS: AWS Service Catalog cho phép tổ chức tạo và quản lý các danh mục dịch vụ CNTT đã được phê duyệt sẵn để người dùng tự triển khai. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Trình quản lý hệ thống AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý hệ thống AWS: AWS Systems Manager cung cấp giao diện quản lý tập trung tài nguyên, tự động hóa tác vụ vận hành, quản lý bản vá (Patch Manager) và chạy lệnh (Run Command). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Trình phân tích truy cập AWS IAM", "is_correct": true, "analysis_vi": "Đúng. Trình phân tích truy cập AWS IAM là đáp án chính xác. Trình phân tích truy cập AWS IAM là dịch vụ giúp bạn xác định các tài nguyên trong tổ chức và tài khoản của mình, chẳng hạn như bộ chứa Amazon S3 hoặc vai trò IAM, được chia sẻ với một thực thể bên ngoài."}, {"label": "D", "text_vi": "AWS Organizations", "is_correct": false, "analysis_vi": "Sai. AWS Organizations: AWS Organizations giúp quản lý tập trung nhiều tài khoản AWS, hỗ trợ xuất hóa đơn hợp nhất (Consolidated Billing) và áp dụng chính sách SCP. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3", "AWS Organizations", "AWS Secrets Manager", "AWS IAM"]'::jsonb, NOW())
