INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-175', 'practice_283', 'Dịch vụ AWS nào đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS CloudFormation là dịch vụ cung cấp cho các nhà phát triển và doanh nghiệp một cách dễ dàng để tạo tập hợp các tài nguyên AWS và bên thứ ba có liên quan, đồng thời cung cấp và quản lý chúng theo cách có trật tự và có thể dự đoán được. Bạn có thể sử dụng các mẫu mẫu của AWS CloudFormation hoặc tạo mẫu của riêng mình để mô tả các tài nguyên của AWS và bên thứ ba cũng như mọi phần phụ thuộc liên quan hoặc tham số thời gian chạy cần thiết để chạy ứng dụng của bạn.', '[{"label": "A", "text_vi": "Đám mây AWS", "is_correct": true, "analysis_vi": "Đúng. Đám mây AWS là đáp án chính xác. AWS CloudFormation là dịch vụ cung cấp cho các nhà phát triển và doanh nghiệp một cách dễ dàng để tạo tập hợp các tài nguyên AWS và bên thứ ba có liên quan, đồng thời cung cấp và quản lý chúng theo cách có trật tự và có thể dự đoán được."}, {"label": "B", "text_vi": "AWS Elastic Beanstalk", "is_correct": false, "analysis_vi": "Sai. AWS Elastic Beanstalk: AWS Elastic Beanstalk là dịch vụ PaaS cho phép lập trình viên tải mã nguồn lên và AWS tự động xử lý việc cấp phát máy chủ, cân bằng tải, tự động co giãn và giám sát. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "AWS Cloud9", "is_correct": false, "analysis_vi": "Sai. AWS Cloud9 không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "AWS CloudShell", "is_correct": false, "analysis_vi": "Sai. AWS CloudShell không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Elastic Beanstalk", "AWS CloudFormation"]'::jsonb, NOW())
