INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-176', 'practice_283', 'Điều nào sau đây là lợi ích của việc tách kiến trúc Đám mây AWS?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Lợi ích của việc tách kiến trúc Đám mây AWS là khả năng nâng cấp các thành phần một cách độc lập. Tách rời là một cách thiết kế hệ thống để giảm sự phụ thuộc lẫn nhau và giảm thiểu tác động của những thay đổi. Việc tách rời cho phép các thành phần tương tác với nhau thông qua các giao diện được xác định rõ ràng thay vì tham chiếu trực tiếp. Điều này làm giảm nguy cơ thất bại và lỗi lan truyền trên toàn hệ thống, đồng thời cho phép khả năng mở rộng, tính sẵn sàng và khả năng bảo trì cao hơn. Bằng cách tách kiến ​​trúc Đám mây AWS, người dùng có thể nâng cấp hoặc sửa đổi một thành phần mà không ảnh hưởng đến các thành phần khác5.', '[{"label": "A", "text_vi": "Giảm độ trễ", "is_correct": false, "analysis_vi": "Sai. Giảm độ trễ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Khả năng nâng cấp linh kiện độc lập", "is_correct": true, "analysis_vi": "Đúng. Khả năng nâng cấp linh kiện độc lập là đáp án chính xác. Lợi ích của việc tách kiến trúc Đám mây AWS là khả năng nâng cấp các thành phần một cách độc lập."}, {"label": "C", "text_vi": "Giảm chi phí", "is_correct": false, "analysis_vi": "Sai. Giảm chi phí không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Ít thành phần hơn để quản lý", "is_correct": false, "analysis_vi": "Sai. Ít thành phần hơn để quản lý không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
