INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-177', 'practice_283', 'Điều nào sau đây mô tả AWS Region?', 'Domain 3: Cloud Technology and Services', 'Lợi thế điện toán đám mây & Hạ tầng toàn cầu', 'AWS Region là một vị trí cụ thể trong khu vực địa lý có tính sẵn sàng cao. Một AWS Region bao gồm hai hoặc nhiều Availability Zone (AZ), là các vị trí biệt lập trong cùng một Khu vực. Mỗi Availability Zone (AZ) có nguồn điện, khả năng làm mát và bảo mật vật lý độc lập, đồng thời được kết nối với các Availability Zone (AZ) khác trong cùng Khu vực bằng mạng có độ trễ thấp, thông lượng cao và tính dự phòng cao. Dịch vụ AWS có sẵn ở nhiều Khu vực trên khắp thế giới, cho phép người dùng chọn nơi chạy ứng dụng và lưu trữ dữ liệu của họ1.', '[{"label": "A", "text_vi": "Một vị trí cụ thể trong một khu vực địa lý có tính sẵn sàng cao", "is_correct": true, "analysis_vi": "Đúng. Một vị trí cụ thể trong một khu vực địa lý có tính sẵn sàng cao là đáp án chính xác. AWS Region là một vị trí cụ thể trong khu vực địa lý có tính sẵn sàng cao."}, {"label": "B", "text_vi": "Một tập hợp các trung tâm dữ liệu trải dài trên nhiều quốc gia", "is_correct": false, "analysis_vi": "Sai. Một tập hợp các trung tâm dữ liệu trải dài trên nhiều quốc gia không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Bức tranh toàn cảnh về môi trường điện toán đám mây của người dùng", "is_correct": false, "analysis_vi": "Sai. Bức tranh toàn cảnh về môi trường điện toán đám mây của người dùng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Một tập hợp các cơ sở dữ liệu chỉ có thể được truy cập từ một khu vực địa lý cụ thể", "is_correct": false, "analysis_vi": "Sai. Một tập hợp các cơ sở dữ liệu chỉ có thể được truy cập từ một khu vực địa lý cụ thể không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
