INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-178', 'practice_283', 'Một công ty muốn triển khai các biện pháp kiểm soát (lan can) trong khu vực hạ cánh của Tháp điều khiển AWS mới được tạo. Công ty có thể sử dụng những dịch vụ hoặc tính năng nào của AWS để tạo và xác định các biện pháp kiểm soát (rào chắn) này? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Lợi thế điện toán đám mây & Hạ tầng toàn cầu', 'Cấu hình AWS và chính sách kiểm soát dịch vụ (SCP) là các dịch vụ hoặc tính năng AWS mà công ty có thể sử dụng để tạo và xác định các biện pháp kiểm soát (rào chắn) trong vùng hạ cánh của Tháp điều khiển AWS mới được tạo. AWS Config là dịch vụ cho phép người dùng đánh giá, kiểm tra và đánh giá cấu hình tài nguyên AWS của họ. Nó có thể được sử dụng để tạo các quy tắc kiểm tra việc tuân thủ các cấu hình mong muốn và báo cáo mọi sai lệch. Tháp điều khiển AWS cung cấp một bộ quy tắc AWS Config được xác định trước có thể được kích hoạt dưới dạng rào chắn để thực thi sự tuân thủ trên toàn khu vực hạ cánh1. Chính sách kiểm soát dịch vụ (SCP) là một loại chính sách có thể được sử dụng để quản lý các quyền trong AWS Organs. Chúng có thể được sử dụng để hạn chế các hành động mà người dùng và vai trò trong tài khoản thành viên có thể thực hiện trên tài nguyên AWS. Tháp điều khiển AWS cung cấp một tập hợp các SCP được xác định trước có thể được kích hoạt làm rào chắn để ngăn chặn quyền truy cập vào một số dịch vụ hoặc khu vực nhất định trên khu vực hạ cánh2. Amazon GuardDuty là dịch vụ cung cấp khả năng phát hiện mối đe dọa thông minh và giám sát liên tục đối với các tài khoản và tài nguyên AWS. Đây không phải là một tính năng có thể được sử dụng để tạo và xác định các điều khiển (lan can) trong khu vực hạ cánh. AWS Identity and Access Management (IAM) là dịch vụ cho phép người dùng quản lý quyền truy cập vào các tài nguyên và dịch vụ AWS. Nó có thể được sử dụng để tạo người dùng, nhóm, vai trò và chính sách kiểm soát ai có thể làm gì trong AWS. Đây không phải là một tính năng có thể được sử dụng để tạo và xác định các điều khiển (lan can) trong khu vực hạ cánh. Security Group là tường lửa ảo kiểm soát lưu lượng vào và ra cho các phiên bản Amazon EC2. Chúng có thể được sử dụng để cho phép hoặc từ chối quyền truy cập vào phiên bản EC2 dựa trên cổng, giao thức và nguồn hoặc đích. Chúng không phải là một tính năng có thể được sử dụng để tạo và xác định các điều khiển (lan can) trong bãi đáp.', '[{"label": "A", "text_vi": "Cấu hình AWS", "is_correct": true, "analysis_vi": "Đúng. Cấu hình AWS là đáp án chính xác. Cấu hình AWS và chính sách kiểm soát dịch vụ (SCP) là các dịch vụ hoặc tính năng AWS mà công ty có thể sử dụng để tạo và xác định các biện pháp kiểm soát (rào chắn) trong vùng hạ cánh của Tháp điều khiển AWS mới được tạo."}, {"label": "B", "text_vi": "Chính sách kiểm soát dịch vụ (SCP)", "is_correct": true, "analysis_vi": "Đúng. Chính sách kiểm soát dịch vụ (SCP) là đáp án chính xác. Cấu hình AWS và chính sách kiểm soát dịch vụ (SCP) là các dịch vụ hoặc tính năng AWS mà công ty có thể sử dụng để tạo và xác định các biện pháp kiểm soát (rào chắn) trong vùng hạ cánh của Tháp điều khiển AWS mới được tạo."}, {"label": "C", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Nhiệm vụ bảo vệ của Amazon: Amazon GuardDuty là dịch vụ phát hiện mối đe dọa thông minh sử dụng máy học để liên tục phân tích VPC Flow Logs, CloudTrail Logs và DNS Logs. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Quản lý quyền truy cập và nhận dạng AWS (IAM)", "is_correct": false, "analysis_vi": "Sai. Quản lý quyền truy cập và nhận dạng AWS (IAM): AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "E", "text_vi": "Security Group", "is_correct": false, "analysis_vi": "Sai. Security Group: Security Group là tường lửa ảo ở cấp instance, hoạt động có trạng thái (Stateful) và chỉ cấu hình các quy tắc cho phép (Allow rules). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon GuardDuty", "AWS IAM"]'::jsonb, NOW())
