INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-179', 'practice_283', 'Dịch vụ AWS nào được sử dụng để tạm thời cung cấp thông tin xác thực bảo mật liên kết cho một', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'Dịch vụ AWS được dùng để tạm thời cung cấp thông tin xác thực bảo mật liên kết cho người dùng là Dịch vụ mã thông báo bảo mật AWS (AWS STS). AWS STS là dịch vụ cho phép khách hàng yêu cầu thông tin xác thực tạm thời, có đặc quyền giới hạn cho người dùng AWS Identity and Access Management (IAM) hoặc cho người dùng mà họ xác thực (người dùng liên kết). Công ty có thể sử dụng AWS STS để cấp cho người dùng liên kết quyền truy cập vào tài nguyên AWS mà không cần tạo người dùng IAM cố định hoặc chia sẻ thông tin xác thực dài hạn. AWS STS giúp khách hàng quản lý và bảo mật quyền truy cập vào tài nguyên AWS của họ cho người dùng liên kết. Amazon GuardDuty, AWS Secrets Manager và AWS Certification Manager không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này. Amazon GuardDuty là dịch vụ phát hiện mối đe dọa nhằm giám sát hoạt động độc hại và hành vi trái phép trên các tài khoản và tài nguyên AWS. AWS Secrets Manager là dịch vụ giúp khách hàng quản lý và xoay vòng các bí mật, chẳng hạn như thông tin xác thực cơ sở dữ liệu, khóa API và mật khẩu. AWS Certification Manager là dịch vụ giúp khách hàng cung cấp, quản lý và triển khai các chứng chỉ Lớp cổng bảo mật/Bảo mật lớp truyền tải (SSL/TLS) công khai và riêng tư để sử dụng với các dịch vụ AWS và tài nguyên được kết nối nội bộ. Các dịch vụ này hữu ích hơn cho các loại nhiệm vụ tuân thủ và bảo mật khác nhau thay vì cung cấp thông tin xác thực bảo mật liên kết tạm thời cho người dùng.', '[{"label": "A", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Amazon GuardDuty, AWS Secrets Manager và AWS Certification Manager không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này."}, {"label": "B", "text_vi": "Dịch vụ mã thông báo đơn giản AWS (AWS STS)", "is_correct": true, "analysis_vi": "Đúng. Dịch vụ mã thông báo đơn giản AWS (AWS STS) là đáp án chính xác. Dịch vụ AWS được dùng để tạm thời cung cấp thông tin xác thực bảo mật liên kết cho người dùng là Dịch vụ mã thông báo bảo mật AWS (AWS STS)."}, {"label": "C", "text_vi": "AWS Secrets Manager", "is_correct": false, "analysis_vi": "Sai. Amazon GuardDuty, AWS Secrets Manager và AWS Certification Manager không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này."}, {"label": "D", "text_vi": "AWS Certificate Manager (ACM)", "is_correct": false, "analysis_vi": "Sai. Amazon GuardDuty, AWS Secrets Manager và AWS Certification Manager không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["Amazon GuardDuty", "AWS Secrets Manager"]'::jsonb, NOW())
