INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-180', 'practice_283', 'Những lựa chọn nào là các quan điểm bao gồm các khả năng nền tảng của Khung áp dụng đám mây AWS (AWS CAF)? (Chọn HAI.)', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Các tùy chọn là các khía cạnh bao gồm các khả năng nền tảng của Khung áp dụng đám mây AWS (AWS CAF) là vận hành và hiệu suất hoạt động. AWS CAF là hướng dẫn giúp các tổ chức thiết kế và thực hiện lộ trình nhanh chóng để áp dụng đám mây thành công. AWS CAF tổ chức quy trình áp dụng đám mây thành sáu lĩnh vực trọng tâm, được gọi là quan điểm, đó là kinh doanh, con người, quản trị, nền tảng, bảo mật và vận hành. Mỗi quan điểm được chia thành các khả năng, sau đó lại được chia thành các kỹ năng và trách nhiệm. Khía cạnh vận hành tập trung vào việc quản lý và giám sát các tài nguyên và ứng dụng đám mây, cũng như tự động hóa và tối ưu hóa các quy trình vận hành. Các khả năng của phối cảnh hoạt động là hỗ trợ hoạt động, tích hợp hoạt động và quản lý dịch vụ. Quan điểm hiệu quả hiệu suất tập trung vào việc lựa chọn và cấu hình các tài nguyên và dịch vụ đám mây phù hợp để đáp ứng các yêu cầu về hiệu suất của ứng dụng, cũng như việc cải tiến và đổi mới liên tục các giải pháp đám mây. Các khả năng của quan điểm hiệu quả hoạt động là lựa chọn, xem xét và giám sát. Tính bền vững, bảo mật và độ tin cậy không phải là các khía cạnh của AWS CAF mà là các khía cạnh của Khung kiến ​​trúc tối ưu AWS. Khung kiến ​​trúc tối ưu AWS là hướng dẫn giúp người dùng xây dựng và vận hành các hệ thống an toàn, đáng tin cậy, hiệu quả và tiết kiệm chi phí trên đám mây. Khung kiến ​​trúc tối ưu AWS bao gồm năm trụ cột là hoạt động xuất sắc, bảo mật, độ tin cậy, hiệu quả hoạt động và tối ưu hóa chi phí. Tính bền vững là một chủ đề xuyên suốt áp dụng cho tất cả các trụ cột và đề cập đến tác động môi trường và xã hội của các giải pháp đám mây.', '[{"label": "A", "text_vi": "Tính bền vững", "is_correct": false, "analysis_vi": "Sai. Tính bền vững, bảo mật và độ tin cậy không phải là các khía cạnh của AWS CAF mà là các khía cạnh của Khung kiến ​​trúc tối ưu AWS."}, {"label": "B", "text_vi": "Bảo mật", "is_correct": false, "analysis_vi": "Sai. Bảo mật không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Hoạt động", "is_correct": true, "analysis_vi": "Đúng. Hoạt động là đáp án chính xác. Các tùy chọn là các khía cạnh bao gồm các khả năng nền tảng của Khung áp dụng đám mây AWS (AWS CAF) là vận hành và hiệu suất hoạt động."}, {"label": "D", "text_vi": "Hiệu quả hoạt động", "is_correct": true, "analysis_vi": "Đúng. Hiệu quả hoạt động là đáp án chính xác. Các tùy chọn là các khía cạnh bao gồm các khả năng nền tảng của Khung áp dụng đám mây AWS (AWS CAF) là vận hành và hiệu suất hoạt động."}, {"label": "E", "text_vi": "Độ tin cậy", "is_correct": false, "analysis_vi": "Sai. Độ tin cậy không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
