INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-182', 'practice_283', 'Một công ty đã thiết kế cơ sở hạ tầng Đám mây AWS để vận hành khối lượng công việc của mình một cách hiệu quả. Công ty cũng có sẵn các quy trình để liên tục cải tiến các quy trình hỗ trợ. Kịch bản này thể hiện trụ cột nào của Khung kiến ​​trúc tối ưu AWS?', 'Domain 1: Cloud Concepts', 'Khung kiến trúc tối ưu AWS (Well-Architected Framework)', 'Kịch bản này thể hiện trụ cột vận hành xuất sắc của Khung kiến trúc tối ưu AWS, tập trung vào việc vận hành và giám sát các hệ thống để mang lại giá trị kinh doanh và liên tục cải tiến các quy trình và thủ tục hỗ trợ1. Bảo mật, hiệu quả hoạt động, tối ưu hóa chi phí và độ tin cậy là bốn trụ cột khác của khuôn khổ1.', '[{"label": "A", "text_vi": "Bảo mật", "is_correct": false, "analysis_vi": "Sai. Bảo mật không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Hiệu quả hoạt động", "is_correct": false, "analysis_vi": "Sai. Hiệu quả hoạt động không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Tối ưu hóa chi phí", "is_correct": false, "analysis_vi": "Sai. Tối ưu hóa chi phí không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Hoạt động xuất sắc", "is_correct": true, "analysis_vi": "Đúng. Hoạt động xuất sắc là đáp án chính xác. Kịch bản này thể hiện trụ cột vận hành xuất sắc của Khung kiến trúc tối ưu AWS, tập trung vào việc vận hành và giám sát các hệ thống để mang lại giá trị kinh doanh và liên tục cải tiến các quy trình và thủ tục hỗ trợ1."}]'::jsonb, '["Ghi nhớ các ngưỡng SLA phản hồi: Business (<1h cho production down, 24/7 phone/chat/email), Enterprise (<15m cho mission-critical, có TAM)."]'::jsonb, '[{"term": "support plan", "points_to": "Developer / Business / Enterprise"}]'::jsonb, '[]'::jsonb, NOW())
