INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-183', 'practice_283', 'Người dùng muốn xác định bất kỳ Security Group nào đang cho phép lưu lượng SSH đến không bị hạn chế. Dịch vụ AWS nào có thể được sử dụng để hoàn thành mục tiêu này?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Câu trả lời đúng cho câu hỏi là D vì AWS Trusted Advisor là dịch vụ AWS có thể được sử dụng để hoàn thành mục tiêu xác định bất kỳ Security Group nào đang cho phép lưu lượng SSH đến không bị hạn chế. AWS Trusted Advisor là dịch vụ cung cấp cho khách hàng những đề xuất giúp họ thực hiện theo các biện pháp thực hành tốt nhất của AWS. Trusted Advisor đánh giá môi trường AWS của khách hàng và xác định các cách để tối ưu hóa cơ sở hạ tầng AWS của họ, cải thiện tính bảo mật và hiệu suất, giảm chi phí và giám sát định mức dịch vụ. Một trong những kiểm tra mà Trusted Advisor thực hiện là kiểm tra Security Group - Cổng cụ thể không bị hạn chế, đánh dấu các Security Group cho phép truy cập không hạn chế vào các cổng cụ thể, chẳng hạn như cổng 22 cho SSH. Khách hàng có thể sử dụng bước kiểm tra này để xem xét và sửa đổi các quy tắc Security Group của mình nhằm hạn chế quyền truy cập SSH chỉ vào các nguồn được ủy quyền.', '[{"label": "A", "text_vi": "Amazon Cognito", "is_correct": false, "analysis_vi": "Sai. Amazon Cognito không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Khiên AWS", "is_correct": false, "analysis_vi": "Sai. Khiên AWS: AWS Shield là dịch vụ phòng chống tấn công từ chối dịch vụ phân tán (DDoS), bản Standard miễn phí tích hợp sẵn và bản Advanced hỗ trợ phản ứng 24/7 từ đội SRT. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon Macie", "is_correct": false, "analysis_vi": "Sai. Amazon Macie: Amazon Macie sử dụng máy học và đối sánh mẫu để tự động phát hiện, phân loại và bảo vệ dữ liệu nhạy cảm (như PII, số thẻ tín dụng) trên Amazon S3. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "AWS Trusted Advisor", "is_correct": true, "analysis_vi": "Đúng. AWS Trusted Advisor là đáp án chính xác. Câu trả lời đúng cho câu hỏi là D vì AWS Trusted Advisor là dịch vụ AWS có thể được sử dụng để hoàn thành mục tiêu xác định bất kỳ Security Group nào đang cho phép lưu lượng SSH đến không bị hạn chế."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Trusted Advisor", "AWS Shield", "Amazon Macie"]'::jsonb, NOW())
