INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-184', 'practice_283', 'Một công ty đang sử dụng AWS Organs để định cấu hình tài khoản AWS. Một công ty đang lên kế hoạch di chuyển sang Đám mây AWS. Công ty đang xác định những khoảng trống về năng lực của mình bằng cách sử dụng các phối cảnh Khung áp dụng đám mây AWS (AWS CAF). Giai đoạn nào của hành trình chuyển đổi sang đám mây bao gồm các hoạt động nhận dạng này?', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Giai đoạn Hình dung của hành trình chuyển đổi sang đám mây là nơi công ty xác định tầm nhìn, động lực kinh doanh và kết quả mong muốn của việc áp dụng đám mây. Công ty cũng xác định những khoảng trống về năng lực của mình bằng cách sử dụng các khía cạnh Khung áp dụng đám mây AWS (AWS CAF), bao gồm kinh doanh, con người, quản trị, nền tảng, bảo mật và vận hành2.', '[{"label": "A", "text_vi": "Hình dung", "is_correct": true, "analysis_vi": "Đúng. Hình dung là đáp án chính xác. Giai đoạn Hình dung của hành trình chuyển đổi sang đám mây là nơi công ty xác định tầm nhìn, động lực kinh doanh và kết quả mong muốn của việc áp dụng đám mây."}, {"label": "B", "text_vi": "Căn chỉnh", "is_correct": false, "analysis_vi": "Sai. Căn chỉnh không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Quy mô", "is_correct": false, "analysis_vi": "Sai. Quy mô không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Khởi động", "is_correct": false, "analysis_vi": "Sai. Khởi động không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Organizations"]'::jsonb, NOW())
