INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-185', 'practice_283', 'Những khả năng nào là lợi ích của Đám mây AWS? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Đám mây AWS mang lại nhiều lợi ích như: Trao đổi chi phí biến đổi lấy chi phí vốn: Bạn chỉ có thể thanh toán cho những tài nguyên bạn sử dụng, thay vì đầu tư trả trước vào chi phí cố định. Điều này giúp giảm rủi ro và sự phức tạp khi lập kế hoạch và quản lý cơ sở hạ tầng CNTT của bạn4 Triển khai trên toàn cầu trong vài phút: Bạn có thể tận dụng cơ sở hạ tầng toàn cầu của AWS để triển khai các ứng dụng và dữ liệu của mình ở nhiều vùng và Availability Zone (AZ). Điều này cho phép bạn tiếp cận khách hàng nhanh hơn, cải thiện hiệu suất và tăng độ tin cậy5', '[{"label": "A", "text_vi": "Chuyển đổi chi phí biến đổi thành chi phí vốn.", "is_correct": false, "analysis_vi": "Sai. Chuyển đổi chi phí biến đổi thành chi phí vốn. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Triển khai trên toàn cầu trong vài phút.", "is_correct": true, "analysis_vi": "Đúng. Triển khai trên toàn cầu trong vài phút. là đáp án chính xác. Điều này giúp giảm rủi ro và sự phức tạp khi lập kế hoạch và quản lý cơ sở hạ tầng CNTT của bạn4 Triển khai trên toàn cầu trong vài phút: Bạn có thể tận dụng cơ sở hạ tầng toàn cầu của AWS để triển khai các ứng dụng và dữ liệu của mình ở nhiều vùng và Availability Zone (AZ)."}, {"label": "C", "text_vi": "Lập kế hoạch năng lực trước khi triển khai.", "is_correct": false, "analysis_vi": "Sai. Lập kế hoạch năng lực trước khi triển khai. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Tận dụng lợi thế kinh tế nhờ quy mô.", "is_correct": true, "analysis_vi": "Đúng. Tận dụng lợi thế kinh tế nhờ quy mô. là đáp án chính xác. Đám mây AWS mang lại nhiều lợi ích như: Trao đổi chi phí biến đổi lấy chi phí vốn: Bạn chỉ có thể thanh toán cho những tài nguyên bạn sử dụng, thay vì đầu tư trả trước vào chi phí cố định."}, {"label": "E", "text_vi": "Giảm sự phụ thuộc vào kết nối mạng.", "is_correct": false, "analysis_vi": "Sai. Giảm sự phụ thuộc vào kết nối mạng. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Direct Connect"]'::jsonb, NOW())
