INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-186', 'practice_283', 'Điều nào sau đây là trụ cột của Khung kiến trúc tối ưu AWS? (Chọn HAI.)', 'Domain 1: Cloud Concepts', 'Khung kiến trúc tối ưu AWS (Well-Architected Framework)', 'Câu trả lời đúng cho các câu hỏi là B và E vì độ tin cậy và khả năng vận hành xuất sắc là trụ cột của Khung kiến trúc tối ưu AWS. Khung kiến ​​trúc tối ưu AWS là một tập hợp các biện pháp thực hành và hướng dẫn tốt nhất để thiết kế và vận hành các hệ thống đáng tin cậy, an toàn, hiệu quả và tiết kiệm chi phí trên đám mây. Khung kiến ​​trúc tối ưu AWS bao gồm năm trụ cột: vận hành xuất sắc, bảo mật, độ tin cậy, hiệu quả hoạt động và tối ưu hóa chi phí. Mỗi trụ cột có một bộ nguyên tắc thiết kế mô tả các đặc điểm của một hệ thống được kiến ​​trúc tốt. Độ tin cậy là trụ cột tập trung vào khả năng hệ thống phục hồi sau lỗi và đáp ứng nhu cầu kinh doanh và khách hàng. Hoạt động xuất sắc là trụ cột tập trung vào khả năng của một hệ thống trong việc vận hành và giám sát các quy trình nhằm hỗ trợ kết quả kinh doanh và liên tục cải tiến. Các tùy chọn khác không chính xác vì chúng không phải là trụ cột của Khung kiến ​​trúc tối ưu AWS. Tính sẵn sàng, khả năng mở rộng và thiết kế đáp ứng là những khía cạnh quan trọng của kiến ​​trúc đám mây, nhưng chúng không phải là những trụ cột riêng biệt trong khuôn khổ. Tính sẵn sàng và khả năng mở rộng liên quan đến các trụ cột về độ tin cậy và hiệu quả hoạt động, trong khi thiết kế đáp ứng liên quan đến trải nghiệm của khách hàng và giao diện người dùng.', '[{"label": "A", "text_vi": "Sẵn có", "is_correct": false, "analysis_vi": "Sai. Sẵn có không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Độ tin cậy", "is_correct": true, "analysis_vi": "Đúng. Độ tin cậy đáp ứng đầy đủ yêu cầu của đề bài. Câu trả lời đúng cho các câu hỏi là B và E vì độ tin cậy và khả năng vận hành xuất sắc là trụ cột của Khung kiến trúc tối ưu AWS."}, {"label": "C", "text_vi": "Khả năng mở rộng", "is_correct": false, "analysis_vi": "Sai. Khả năng mở rộng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Thiết kế đáp ứng", "is_correct": false, "analysis_vi": "Sai. Thiết kế đáp ứng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Hoạt động xuất sắc", "is_correct": true, "analysis_vi": "Đúng. Hoạt động xuất sắc là đáp án chính xác. Câu trả lời đúng cho các câu hỏi là B và E vì độ tin cậy và khả năng vận hành xuất sắc là trụ cột của Khung kiến trúc tối ưu AWS."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
