INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-187', 'practice_283', 'Một công ty đang chạy khối lượng công việc cho nhiều phòng ban trong một VPC. Công ty cần có khả năng lập hóa đơn cho từng bộ phận về việc sử dụng tài nguyên của mình. Công ty nên thực hiện hành động nào để hoàn thành mục tiêu này với chi phí hoạt động ÍT NHẤT?', 'Domain 3: Cloud Technology and Services', 'Quản lý chi phí & Thanh toán AWS', 'Thêm thẻ bộ phận vào từng tài nguyên và định cấu hình thẻ phân bổ chi phí là một hành động có thể giúp bạn hoàn thành mục tiêu lập hoá đơn cho từng bộ phận về việc sử dụng tài nguyên với chi phí hoạt động ít nhất. Thẻ là các nhãn đơn giản bao gồm một khóa và một giá trị tùy chọn mà bạn có thể gán cho tài nguyên AWS. Bạn có thể sử dụng thẻ để sắp xếp tài nguyên và theo dõi chi phí AWS ở mức độ chi tiết. Thẻ phân bổ chi phí cho phép bạn theo dõi chi phí AWS của mình ở mức độ chi tiết. Sau khi bạn kích hoạt thẻ phân bổ chi phí, AWS sử dụng thẻ phân bổ chi phí để sắp xếp chi phí tài nguyên trên báo cáo phân bổ chi phí của bạn, giúp bạn phân loại và theo dõi chi phí AWS2 dễ dàng hơn2. Di chuyển từng tài nguyên của bộ phận sang VPC riêng hoặc tài khoản AWS riêng của bộ phận đó là hành động có thể giúp bạn tách biệt và kiểm soát tài nguyên cho từng bộ phận, nhưng việc này sẽ phát sinh nhiều chi phí hoạt động hơn so với việc sử dụng thẻ. Sử dụng AWS Organs để nhận báo cáo thanh toán cho từng bộ phận là một hành động có thể giúp bạn hợp nhất việc lập hóa đơn và thanh toán trên nhiều tài khoản AWS, nhưng sẽ không giúp bạn lập hóa đơn cho từng bộ phận về mức sử dụng tài nguyên trong một VPC duy nhất.', '[{"label": "A", "text_vi": "Thêm thẻ bộ phận vào từng tài nguyên và định cấu hình thẻ phân bổ chi phí.", "is_correct": true, "analysis_vi": "Đúng. Thêm thẻ bộ phận vào từng tài nguyên và định cấu hình thẻ phân bổ chi phí. là đáp án chính xác. Thêm thẻ bộ phận vào từng tài nguyên và định cấu hình thẻ phân bổ chi phí là một hành động có thể giúp bạn hoàn thành mục tiêu lập hoá đơn cho từng bộ phận về việc sử dụng tài nguyên với chi phí hoạt động ít nhất."}, {"label": "B", "text_vi": "Di chuyển từng tài nguyên của bộ phận sang VPC riêng.", "is_correct": false, "analysis_vi": "Sai. Di chuyển từng tài nguyên của bộ phận sang VPC riêng.: Amazon VPC cho phép khởi tạo mạng ảo riêng biệt được cô lập logic trên đám mây AWS, kiểm soát toàn diện dải IP, subnet, bảng định tuyến và cổng mạng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Di chuyển từng tài nguyên của bộ phận sang tài khoản AWS riêng của bộ phận đó.", "is_correct": false, "analysis_vi": "Sai. Di chuyển từng tài nguyên của bộ phận sang tài khoản AWS riêng của bộ phận đó. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Sử dụng AWS Organs để nhận báo cáo thanh toán cho từng bộ phận.", "is_correct": false, "analysis_vi": "Sai. Sử dụng AWS Organs để nhận báo cáo thanh toán cho từng bộ phận.: AWS Organizations giúp quản lý tập trung nhiều tài khoản AWS, hỗ trợ xuất hóa đơn hợp nhất (Consolidated Billing) và áp dụng chính sách SCP. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["AWS Organizations", "Amazon VPC"]'::jsonb, NOW())
