INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-188', 'practice_283', 'Một công ty muốn có mức độ phát hiện cao và giảm nhẹ gần thời gian thực (NRT) trước các cuộc tấn công từ chối dịch vụ phân tán (DDoS) quy mô lớn và tinh vi vào các ứng dụng chạy trên AWS. Công ty nên sử dụng dịch vụ AWS nào?', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'AWS Shield Advanced là dịch vụ cung cấp mức độ phát hiện cao và giảm nhẹ gần như theo thời gian thực (NRT) trước các cuộc tấn công từ chối dịch vụ phân tán (DDoS) quy mô lớn và tinh vi vào các ứng dụng chạy trên AWS. AWS Shield Advanced cũng cung cấp cho bạn quyền truy cập 24x7 vào Nhóm phản hồi DDoS (DRT) của AWS và bảo vệ khỏi các cuộc tấn công DDoS ở mọi quy mô hoặc thời lượng1. Amazon GuardDuty là dịch vụ cung cấp khả năng phát hiện mối đe dọa cho tài khoản và khối lượng công việc AWS của bạn nhưng không cung cấp tính năng bảo vệ DDoS3. Amazon Inspector là dịch vụ giúp bạn cải thiện tính bảo mật và tuân thủ của các ứng dụng được triển khai trên AWS bằng cách tự động đánh giá chúng để phát hiện các lỗ hổng và sai lệch so với các biện pháp thực hành tốt nhất. Amazon Macie là dịch vụ sử dụng công nghệ máy học và khớp mẫu để khám phá và bảo vệ dữ liệu nhạy cảm của bạn trong AWS.', '[{"label": "A", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Amazon GuardDuty là dịch vụ cung cấp khả năng phát hiện mối đe dọa cho tài khoản và khối lượng công việc AWS của bạn nhưng không cung cấp tính năng bảo vệ DDoS3."}, {"label": "B", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon Inspector là dịch vụ giúp bạn cải thiện tính bảo mật và tuân thủ của các ứng dụng được triển khai trên AWS bằng cách tự động đánh giá chúng để phát hiện các lỗ hổng và sai lệch so với các biện pháp thực hành tốt nhất."}, {"label": "C", "text_vi": "AWS Shield nâng cao", "is_correct": true, "analysis_vi": "Đúng. AWS Shield nâng cao là đáp án chính xác. AWS Shield Advanced là dịch vụ cung cấp mức độ phát hiện cao và giảm nhẹ gần như theo thời gian thực (NRT) trước các cuộc tấn công từ chối dịch vụ phân tán (DDoS) quy mô lớn và tinh vi vào các ứng dụng chạy trên AWS."}, {"label": "D", "text_vi": "Amazon Macie", "is_correct": false, "analysis_vi": "Sai. Amazon Macie: Amazon Macie sử dụng máy học và đối sánh mẫu để tự động phát hiện, phân loại và bảo vệ dữ liệu nhạy cảm (như PII, số thẻ tín dụng) trên Amazon S3. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Shield", "Amazon GuardDuty", "Amazon Inspector", "Amazon Macie"]'::jsonb, NOW())
