INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-189', 'practice_283', 'Dịch vụ AWS nào sử dụng Trình tối ưu hóa điện toán AWS để cung cấp đề xuất định cỡ dựa trên số liệu khối lượng công việc?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Amazon EC2 là dịch vụ web cung cấp khả năng tính toán bảo mật và có thể thay đổi kích thước trên đám mây. Nó cho phép bạn khởi chạy các máy chủ ảo, được gọi là phiên bản, với các cấu hình CPU, bộ nhớ, bộ lưu trữ và tài nguyên mạng khác nhau. Trình tối ưu hóa điện toán AWS phân tích thông số kỹ thuật và số liệu sử dụng của các phiên bản Amazon EC2 của bạn, đồng thời đưa ra đề xuất về các loại phiên bản tối ưu có thể giảm chi phí và cải thiện hiệu suất. Bạn có thể xem các đề xuất trên bảng điều khiển AWS Computer Optimizer hoặc bảng điều khiển Amazon EC212. Amazon RDS, Amazon Lightsail và AWS Step Functions không được AWS Computer Optimizer hỗ trợ. Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý cho phép bạn thiết lập, vận hành và mở rộng quy mô cơ sở dữ liệu quan hệ trên đám mây. Amazon Lightsail là nền tảng đám mây dễ sử dụng, cung cấp mọi thứ bạn cần để xây dựng ứng dụng hoặc trang web, cùng với gói hàng tháng, tiết kiệm chi phí. AWS Step Functions cho phép bạn điều phối nhiều dịch vụ AWS thành các quy trình làm việc phi máy chủ để bạn có thể xây dựng và cập nhật ứng dụng một cách nhanh chóng3 .', '[{"label": "A", "text_vi": "Amazon EC2", "is_correct": true, "analysis_vi": "Đúng. Amazon EC2 là giải pháp đáp ứng yêu cầu. Amazon EC2 là dịch vụ web cung cấp khả năng tính toán bảo mật và có thể thay đổi kích thước trên đám mây. Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật."}, {"label": "B", "text_vi": "Amazon RDS", "is_correct": false, "analysis_vi": "Sai. Amazon RDS: Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Cánh buồm ánh sáng của Amazon", "is_correct": false, "analysis_vi": "Sai. Amazon RDS, Amazon Lightsail và AWS Step Functions không được AWS Computer Optimizer hỗ trợ."}, {"label": "D", "text_vi": "Chức năng bước AWS", "is_correct": false, "analysis_vi": "Sai. Chức năng bước AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon RDS"]'::jsonb, NOW())
