INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-190', 'practice_283', 'Nên sử dụng dịch vụ AWS nào khi công ty cần cung cấp máy tính để bàn ảo cho nhân viên từ xa?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Dịch vụ AWS nên được sử dụng khi công ty cần cung cấp máy tính để bàn ảo cho nhân viên từ xa là Amazon WorkSpaces. Amazon WorkSpaces là giải pháp máy tính để bàn dưới dạng dịch vụ (DaaS) an toàn, được quản lý toàn phần chạy trên AWS. Amazon WorkSpaces cho phép người dùng cung cấp máy tính để bàn ảo dựa trên đám mây và cung cấp cho người dùng cuối quyền truy cập vào các tài liệu, ứng dụng và tài nguyên họ cần từ mọi thiết bị được hỗ trợ, bao gồm máy tính Windows và Mac, Chromebook, iPad, máy tính bảng Fire và máy tính bảng Android4. Amazon Identity and Access Management (IAM), AWS Directory Service và AWS IAM Identity Center (AWS Single Sign-On) là các dịch vụ AWS khác liên quan đến quản lý danh tính và quyền truy cập nhưng chúng không cung cấp máy tính để bàn ảo.', '[{"label": "A", "text_vi": "Quản lý quyền truy cập và nhận dạng Amazon (IAM)", "is_correct": false, "analysis_vi": "Sai. Quản lý quyền truy cập và nhận dạng Amazon (IAM): AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Dịch vụ thư mục AWS", "is_correct": false, "analysis_vi": "Sai. Amazon Identity and Access Management (IAM), AWS Directory Service và AWS IAM Identity Center (AWS Single Sign-On) là các dịch vụ AWS khác liên quan đến quản lý danh tính và quyền truy cập nhưng chúng không cung cấp máy tính để bàn ảo.."}, {"label": "C", "text_vi": "Trung tâm nhận dạng AWS IAM (Đăng nhập một lần AWS)", "is_correct": false, "analysis_vi": "Sai. Trung tâm nhận dạng AWS IAM (Đăng nhập một lần AWS): AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Không gian làm việc của Amazon", "is_correct": true, "analysis_vi": "Đúng. Không gian làm việc của Amazon là đáp án chính xác. Dịch vụ AWS nên được sử dụng khi công ty cần cung cấp máy tính để bàn ảo cho nhân viên từ xa là Amazon WorkSpaces."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS IAM"]'::jsonb, NOW())
